var e=e=>Array.isArray(e)?e.join(` `):e,t=(t,n)=>({da:e(t),en:e(n)}),n=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),r={"crawl-wedged-door":{opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`,`npc3`],title:t(`Den vandplettede side`,`The Water-Stained Page`),summary:t([`Sent på aftenen opsøger {npc1} heltene med en side fra opmålingsholdets logbog i hånden: Den er skrevet af {npc1}s mor, og den sidste notits nævner {villain}.`,`{npc1} beder dem gå ned i {place} efter {villain} og hente resten af logbogen op, før porten bliver muret til ved daggry.`,`Byen kan give flere svar, før de går, men hvert besøg koster tid, som {villain} bruger dernede.`],[`Late in the evening {npc1} seeks out the heroes with a page of the survey party’s logbook in hand: it is written by {npc1}’s mother, and its last entry names {villain}.`,`{npc1} begs them to go down into {place} after {villain} and bring the rest of the logbook up before the gate is walled up at dawn.`,`The town can give more answers before they go, but every visit costs time that {villain} spends below.`]),readAloud:t([`Kroen er ved at lukke, da en skikkelse i en fugtig kappe går lige hen til heltenes bord og glatter en side ud mellem krusene.`,`Papiret er vandplettet og skørt i kanterne, og håndskriften er fast og pæn.`,`Gennem den åbne dør ses en vogn med mørtelsække rumle forbi på vej mod porten til {place}.`],[`The inn is about to close when a figure in a damp cloak walks straight to your table and smooths a page out between the mugs.`,`The paper is water-stained and brittle at the edges, and the handwriting is firm and neat.`,`Through the open door a cart loaded with sacks of mortar rumbles past on its way to the gate of {place}.`]),details:[t(`{npc1} fandt siden i det skrammel, som {foe} slæber ud af {place}, og viste den rundt i byen. Morgenen efter underskrev {villain} ordren om at mure porten til, og ved mørkets frembrud så {npc1}, hvordan {villain} gik alene ud mod porten med en lampe og et brækjern.`,`{npc1} found the page in the junk that {foe} drag out of {place} and showed it around town. The next morning {villain} signed the order to wall up the gate, and at nightfall {npc1} watched {villain} walk out to the gate alone with a lamp and a crowbar.`),t(`Tre steder i byen koster en omvej på en halv time hver: rådets forråd, hvor protokollen viser, hvad {villain} hentede i går; {npc3}, sølvsmeden, der har en barre med holdets kompasrose; og {villain}s skrivepult i rådssalen med det gamle opmålingskort, det eneste, der viser krybegangen. {npc2}, murermesteren, sidder med ordren ved porten, som heltene alligevel skal forbi.`,`Three places in town each cost a half-hour detour: the council stores, where the ledger shows what {villain} took out yesterday; {npc3}, the silversmith, who has an ingot stamped with the party’s compass rose; and {villain}’s desk in the council hall, holding the old survey map, the only thing that shows the crawlway. {npc2}, the master mason, sits with the order at the gate, which the heroes must pass anyway.`),t(`Vejen: fra {town} til porten en halv time, gennem de øverste sale en halv time, til holdets lejr i de midterste sale 1 time ad oliesporet eller 1½ time ad kridtpilene, derfra en halv time til den fastkilede dør og en halv time mere til salen med de syv søjler. Uden omveje står heltene ved døren efter 2½ time, lige før {villain} bryder den op; hvert ophold i byen eller i salene lægges oven i.`,`Getting there: from {town} to the gate, half an hour; through the upper halls, half an hour; to the party’s camp in the middle halls, 1 hour by the oil trail or 1½ hours by the chalk arrows; from there, half an hour to the wedged door and half an hour more to the hall of seven pillars. Without detours the heroes stand at the door after 2½ hours, just before {villain} breaks it open; every stop in town or in the halls adds to that.`),t(`{villain} har en times forspring og når holdets gamle lejr ved det første tik. Kun en gruppe, der går direkte ned, kan nå frem, mens ilden bliver tændt.`,`{villain} has an hour’s lead and reaches the party’s old camp at the first tick. Only a group that goes straight down can get there while the fire is being lit.`)],checks:[n(`Charisma (Persuasion)`,`medium`,t(`{npc2} viser ordren, lukker heltene ind uden at slå alarm og lover at sende bud ned ad trappen, før den sidste sten bliver sat.`,`{npc2} shows the order, lets the heroes in without raising the alarm and promises to send word down the stair before the last stone is set.`),t(`{npc2} holder sig til ordren om, at ingen må gå ind; heltene må vente, til murerne går fra bålet, eller snige sig forbi, og det koster en halv time.`,`{npc2} sticks to the order that no one may go in; the heroes must wait until the masons leave their fire, or sneak past, and that costs half an hour.`)),n(`Intelligence (Investigation)`,`medium`,t(`I {villain}s skrivepult finder heltene det gamle opmålingskort og ved nu, at den dybeste sal har en anden udgang 300 skridt øst for porten.`,`In {villain}’s desk the heroes find the old survey map and now know that the deepest hall has a second way out, 300 paces east of the gate.`),t(`Kortet ligger under en løs bund i skuffen; heltene finder det, men først efter endnu en halv times søgen.`,`The map lies under a false bottom in the drawer; the heroes find it, but only after another half hour of searching.`))],fight:!1,alternatives:[t(`Gå direkte ned uden omveje: Heltene kan nå lejren, før den brænder, men ved intet om krybegangen.`,`Go straight down without detours: the heroes may reach the camp before it burns, but know nothing of the crawlway.`),t(`Har heltene kortet, kan {npc1} gå til krybegangens udgang øst for porten og vente dér med et par naboer, så {villain} ikke slipper ubemærket ud.`,`If the heroes have the map, {npc1} can go to the far end of the crawlway east of the gate and wait there with a few neighbours, so that {villain} cannot slip out unseen.`)],dmNotes:t(`Lad spillerne selv vælge mellem viden og tid. Sig højt, hvad hvert besøg koster, og lad endnu en vogn med mørtel rumle forbi, når de tøver.`,`Let the players choose between knowledge and time themselves. Say aloud what each visit costs, and let another mortar cart rumble past whenever they hesitate.`)},middle:[{kind:`exploration`,at:`site`,present:[],title:t(`Oliesporet på trappen`,`The Oil Trail on the Stair`),summary:t([`Bag porten ligger de øverste sale, hvor {foe} har slæbt skrammel sammen i bunker.`,`Friske dryp af lampeolie og aftryk af fine bystøvler fører forbi alle sidegange og lige ned, mens holdets gamle kridtpile tager en længere vej mod samme mål.`,`Scenen viser, at {villain} kender vejen, og at holdet engang gik den samme.`],[`Beyond the gate lie the upper halls, where {foe} have dragged junk together in heaps.`,`Fresh drips of lamp oil and the prints of good town boots lead past every side passage and straight down, while the party’s old chalk arrows take a longer way to the same place.`,`The scene shows that {villain} knows the way, and that the party once walked it too.`]),readAloud:t([`Trappen bag porten er glat af fugt, og på hvert tiende trin sidder en lille, blank plet, der lugter af lampeolie.`,`I salen nedenfor ligger bunker af knækkede kasser, rustne spande og gamle tæpper, slæbt sammen og gennemrodet.`,`På en søjle sidder en falmet kridtpil med en lille kompasrose og peger videre ned i mørket.`],[`The stair beyond the gate is slick with damp, and every tenth step has a small, glossy spot that smells of lamp oil.`,`In the hall below lie heaps of broken crates, rusty buckets and old blankets, dragged together and rummaged through.`,`On a pillar a faded chalk arrow marked with a little compass rose points on down into the dark.`]),details:[t(`Bunkerne er samlet af {foe}, og nogle af dem sover i skramlet om natten. Imellem bunkerne ligger rester fra holdets tid: en sprukken lygte og en rusten målestang med kompasrosen brændt ind.`,`The heaps are the work of {foe}, and some of them sleep in the junk at night. Among the heaps lie remains from the party’s time: a cracked lantern and a rusty measuring rod with the compass rose burned into it.`),t(`Oliesporet går lige ned og sparer en halv time; kridtpilene følger holdets gamle opmåling gennem sidegangene. Begge fører til holdets lejr i de midterste sale og derfra videre til den fastkilede dør.`,`The oil trail goes straight down and saves half an hour; the chalk arrows follow the party’s old survey through the side passages. Both lead to the party’s camp in the middle halls, and from there on to the wedged door.`),t(`Er det første tik passeret, driver lugten af brændt læder og papir op ad trappen. Efter det andet tik er den fastkilede dør brudt op, og {foe} fra de nederste sale strejfer rundt heroppe, selv i sale, heltene allerede har ryddet.`,`If the first tick has passed, the smell of burnt leather and paper drifts up the stair. After the second tick the wedged door is open, and {foe} from the lower halls roam up here too, even in halls the heroes have already cleared.`)],checks:[n(`Wisdom (Survival)`,`easy`,t(`Støvleaftrykkene er fra i aften: én person, der går hurtigt og holder sig midt på gulvet, som om vedkommende er bange for væggene. Heltene følger oliesporet og sparer en halv time.`,`The boot prints are from tonight: one person, walking fast and keeping to the middle of the floor, as if afraid of the walls. The heroes follow the oil trail and save half an hour.`),t(`Heltene følger kridtpilene i stedet, og holdets gamle omvej koster en halv time.`,`The heroes follow the chalk arrows instead, and the party’s old detour costs half an hour.`)),n(`Dexterity (Stealth)`,`medium`,t(`Heltene kommer forbi bunkerne uden at vække noget.`,`The heroes get past the heaps without waking anything.`),t(`En spand vælter, og nogle {foe} vågner. De følger efter på afstand og blander sig, når heltene når den fastkilede dør.`,`A bucket topples and some {foe} wake. They follow at a distance and join in when the heroes reach the wedged door.`))],fight:!1,alternatives:[t(`Følg kridtpilene med vilje: Omvejen koster tid, men fører ud på en afsats over holdets lejr, så heltene kan se, hvem der er dernede, før de går ind.`,`Follow the chalk arrows on purpose: the detour costs time but comes out on a ledge above the party’s camp, so the heroes can see who is down there before they go in.`),t(`Læg mad eller noget blankt ud ved bunkerne, så {foe} har travlt med at slås om det, mens heltene smutter forbi.`,`Put out food or something shiny by the heaps, so that {foe} are busy squabbling over it while the heroes slip past.`)],dmNotes:t(`Nævn oliedryppene, hver gang heltene vælger vej. De er en tråd, spillerne kan holde fast i, og en påmindelse om, at {villain} er foran dem.`,`Mention the oil drips every time the heroes choose which way to go. They are a thread for the players to hold on to, and a reminder that {villain} is ahead of them.`)},{kind:`investigation`,at:`site`,present:[],title:t(`Den brændte lejr`,`The Burnt Camp`),summary:t([`I de midterste sale ligger opmålingsholdets gamle lejr, hvor holdet boede, før det gik ned bag døren.`,`{villain} har brændt alt, hvad der var tilbage, men under en halvbrændt kiste ligger en forkullet seddel, der fortæller, hvor logbogen er.`,`Når heltene frem før det første tik, ser de ilden blive tændt.`],[`In the middle halls lies the survey party’s old camp, where the party lived before going down behind the door.`,`{villain} has burnt everything left there, but under a half-burnt chest lies a charred scrap that tells where the logbook is.`,`If the heroes get there before the first tick, they see the fire being lit.`]),readAloud:t([`Salen stinker af brændt læder og lampeolie, og soden på væggene er stadig varm.`,`Soveskind, en kiste og en stak papirer er blevet til en sort, rygende bunke midt på gulvet.`,`Langs væggen står en række rustne vanddunke, pænt på linje, som om nogen regnede med at komme tilbage.`],[`The hall reeks of burnt leather and lamp oil, and the soot on the walls is still warm.`,`Bedrolls, a chest and a stack of papers have become a black, smoking heap in the middle of the floor.`,`Along the wall stands a row of rusty water jugs, neatly lined up, as if someone expected to come back.`]),details:[t(`Under kisten, hvor ilden ikke nåede helt ind, ligger en forkullet seddel, som {villain} har overset: Lederen tog æsken med logbogen med ind i salen med de syv søjler.`,`Under the chest, where the fire did not quite reach, lies a charred scrap that {villain} missed: the leader took the box with the logbook into the hall of seven pillars.`),t(`Når heltene frem før det første tik, står {villain} midt i lejren og hælder olie over soveskindene. Ved synet af dem taber {villain} den ene lygte, ilden tager fat, og {villain} løber videre ned mod den fastkilede dør. Heltene kan jage {villain} eller redde, hvad der ligger i flammerne, men ikke begge dele.`,`If the heroes arrive before the first tick, {villain} is standing in the middle of the camp, pouring oil over the bedrolls. At the sight of them {villain} drops one of the lanterns, the fire catches, and {villain} runs on down toward the wedged door. The heroes can chase {villain} or save what lies in the flames, but not both.`),t(`Asken gløder stadig under overfladen, og olien har gjort gulvet glat. Den, der roder i bunken med bare hænder, brænder sig, og et uforsigtigt skridt kan sætte ild i olien igen.`,`The ash still glows beneath the surface, and the oil has made the floor slick. Anyone digging in the heap with bare hands gets burnt, and a careless step can set the oil alight again.`)],checks:[n(`Intelligence (Investigation)`,`medium`,t(`Heltene får sedlen fri under kisten uden at skade den og ved nu, at logbogen ligger i salen med de syv søjler.`,`The heroes work the scrap free from under the chest without harming it, and now know the logbook lies in the hall of seven pillars.`),t(`Sedlen smuldrer halvt i hænderne på dem; kun ordene "syv søjler" kan stadig læses.`,`Half the scrap crumbles in their hands; only the words "seven pillars" can still be read.`))],fight:!1,alternatives:[t(`Spring lejren over, og følg oliesporet direkte videre: Heltene vinder tid, men uden sedlen eller kortet ved de ikke, hvilken af de nederste sale de skal lede i.`,`Skip the camp and follow the oil trail straight on: the heroes gain time, but without the scrap or the map they do not know which of the lower halls to search.`)],dmNotes:t(`Lejren er stedet, hvor spillerne forstår, at {villain} ikke kom for at holde {foe} inde, men for at brænde sandheden. Giv dem et øjeblik med det, før uret driver dem videre.`,`The camp is where the players understand that {villain} did not come to keep {foe} in but to burn the truth. Give them a moment with that before the clock drives them on.`)},{kind:`combat`,at:`site`,present:[],title:t(`Den fastkilede dør`,`The Wedged Door`),summary:t([`Døren til de nederste sale blev kilet fast udefra for tyve år siden, med holdet på den anden side.`,`Efter det andet tik har {villain} brudt den op, og {foe} fra de nederste sale vælter op gennem gangene; når heltene frem før, står {villain} stadig og arbejder med brækjernet.`,`Her bliver det tydeligt, at ingen hvælving styrtede sammen: Holdet blev lukket inde.`],[`The door to the lower halls was wedged shut from the outside twenty years ago, with the party on the other side.`,`After the second tick {villain} has pried it open and {foe} from the lower halls are pouring up through the passages; if the heroes get here sooner, {villain} is still at work with the crowbar.`,`Here it becomes plain that no vault fell: the party was shut in.`]),readAloud:t([`Gangen ender ved en svær egetræsdør med jernbeslag.`,`Langs karmen sidder jernkiler, drevet ind udefra og rustne efter tyve år, og hen over dem løber friske, blanke ridser fra et brækjern.`,`Under døren siver en kold luft ud, der lugter af gammelt støv, og bag døren bevæger noget sig.`],[`The passage ends at a heavy oak door bound with iron.`,`Iron wedges, driven in from the outside and rusted by twenty years, line the frame, and across them run fresh, bright scratches from a crowbar.`,`Cold air seeps out under the door, smelling of old dust, and something is moving on the other side.`]),details:[t(`Før det andet tik står {villain} her med lygten og brækjernet og har næsten fået døren op. Ved synet af heltene river {villain} den sidste kile løs i panik: Døren giver sig med et skrig af jern mod sten, {foe} vælter ud mellem dem, og {villain} smutter ind i mørket bag døren.`,`Before the second tick {villain} stands here with the lantern and the crowbar, the door almost open. At the sight of the heroes {villain} tears the last wedge loose in a panic: the door gives with a shriek of iron on stone, {foe} pour out between them, and {villain} slips into the dark beyond.`),t(`Efter det andet tik står døren åben, kilerne ligger bøjede på gulvet, og {foe} fra de nederste sale strejfer op gennem {place}; heltene møder dem i døråbningen.`,`After the second tick the door stands open, the wedges lie bent on the floor, and {foe} from the lower halls are roaming up through {place}; the heroes meet them in the doorway.`),t(`Indersiden af døren er fuld af ridser i skulderhøjde og et par ord skåret med en kniv: holdets navne og en dato, flere dage efter den dag, {villain} kom op og fortalte om hvælvingen. Under døren er der en sprække, lige bred nok til et ark papir; det var her, lederen skubbede den side ud, som {npc1} fandt.`,`The inside of the door is covered in scratches at shoulder height and a few words cut with a knife: the party’s names and a date several days after the day {villain} came up and told of the fallen vault. Under the door is a gap just wide enough for a sheet of paper; this is where the leader pushed out the page that {npc1} found.`)],checks:[n(`Intelligence (Investigation)`,`easy`,t(`Heltene tyder ordene på indersiden af døren: Holdet var i live i flere dage efter den dag, {villain} sagde, de døde. Det er et bevis, rådet kan se med egne øjne.`,`The heroes make out the words inside the door: the party was alive for days after the day {villain} said they died. It is proof the council can see with its own eyes.`),t(`Ridserne er for slidte til at læse i lygtelyset, men heltene kan tegne dem af og få dem læst senere.`,`The scratches are too worn to read by lantern light, but the heroes can copy them and have them read later.`)),n(`Strength (Athletics)`,`medium`,t(`Heltene holder døråbningen, så kun få {foe} kan komme til ad gangen, og kampen bliver lettere.`,`The heroes hold the doorway so that only a few {foe} can reach them at a time, and the fight gets easier.`),t(`Heltene bliver skubbet tilbage ud i gangen, og {foe} kommer til fra flere sider; kampen bliver hårdere, men bagefter er vejen gennem døren åben.`,`The heroes are pushed back into the passage and {foe} come at them from several sides; the fight is harder, but afterwards the way through the door is open.`))],fight:!0,alternatives:[t(`Gem jer i en sidegang, og lad {villain} gøre arbejdet: Når døren giver sig, vælter {foe} op forbi skjulestedet, og heltene kan følge {villain}s lygte ind i mørket.`,`Hide in a side passage and let {villain} do the work: when the door gives, {foe} rush up past the hiding place, and the heroes can follow {villain}’s lantern into the dark.`),t(`Lok {foe} væk med larm eller et kastet lys, og smut gennem døren, mens de leder.`,`Lure {foe} away with noise or a thrown light, and slip through the door while they search.`)],dmNotes:t(`Brug tidspunktet. Når heltene frem før det andet tik, så lad døren give sig foran dem; kommer de senere, er kampen allerede spredt ud i gangene, og {villain} har et langt forspring.`,`Use the timing. If the heroes arrive before the second tick, let the door give way in front of them; if they come later, the fight has already spread through the passages and {villain} has a long lead.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:t(`Salen med de syv søjler`,`The Hall of Seven Pillars`),summary:t([`Den dybeste sal er nu {boss}s hule, og her ligger holdets sidste lejr: knogler i rådne kapper og blikæsken med logbogen hos lederen.`,`{villain} er her med olie og fyrtøj for at brænde logbogen og derefter smutte ud gennem krybegangen, men {boss} tjener ingen og angriber alt, der forstyrrer salen.`,`Heltene skal få æsken ud, før den brænder, og afgøre, om {villain} slipper væk.`],[`The deepest hall is {boss}’s lair now, and here lies the party’s last camp: bones in rotted cloaks, and the tin box with the logbook beside the leader.`,`{villain} is here with oil and a tinderbox to burn the logbook and then slip out through the crawlway, but {boss} serves no one and attacks whatever disturbs the hall.`,`The heroes must get the box out before it burns, and decide whether {villain} gets away.`]),readAloud:t([`Syv søjler rejser sig ind i mørket, og lyset når kun de tre første.`,`Mellem dem ligger resterne af en lejr: reb, udtørrede vandsække og knogler, der stadig er svøbt i rådne kapper.`,`Længst inde står en lygte på gulvet ved den yderste søjle, og en skikkelse i en fin rådskappe bøjer sig over en lille blikæske med en flaske i hånden.`],[`Seven pillars rise into the dark, and the light reaches only the first three.`,`Between them lie the remains of a camp: rope, dried-out water skins and bones still wrapped in rotted cloaks.`,`Far inside, a lantern stands on the floor by the farthest pillar, and a figure in a fine council cloak bends over a small tin box, a flask in hand.`]),details:[t(`{boss} og nogle {foe} har deres hule her og tjener ikke {villain}, der har sneget sig forbi dem i mørket og er lige så bange for dem som for heltene. Når kampen begynder, går {boss} efter de nærmeste, og {villain} bruger larmen til at sætte ild til æsken eller løbe mod krybegangen.`,`{boss} and some {foe} lair here and do not serve {villain}, who crept past them in the dark and is as afraid of them as of the heroes. When the fight begins, {boss} goes for whoever is nearest, and {villain} uses the noise to set the box alight or run for the crawlway.`),t(`Krybegangen begynder som en lav sprække bag den yderste søjle og kommer ud 300 skridt øst for porten. Holdet fandt den aldrig i mørket, men den står på {villain}s gamle kort. Er gangen spærret, eller venter nogen ved udgangen, har {villain} ingen vej ud og overgiver sig hellere end at blive alene i mørket.`,`The crawlway starts as a low crack behind the farthest pillar and comes out 300 paces east of the gate. The party never found it in the dark, but it is on {villain}’s old map. If it is blocked, or someone waits at its far end, {villain} has no way out and would rather surrender than be left alone in the dark.`),t(`Hvælvingen over salen er hel; her er aldrig styrtet noget sammen. Er heltene langt efter {villain}, brænder de første sider allerede, når de kommer ind, og de har én runde til at redde resten. Ved daggry lyder skrabet af murskeer ned ad trapperne, og fra da af er krybegangen den eneste vej ud.`,`The vault above the hall is intact; nothing ever fell in here. If the heroes are far behind {villain}, the first pages are already burning as they come in, and they have one round to save the rest. At dawn the scrape of trowels carries down the stairs, and from then on the crawlway is the only way out.`)],checks:[n(`Dexterity (Sleight of Hand)`,`medium`,t(`Heltene river æsken fra {villain} eller ud af flammerne, før ilden får fat i siderne.`,`The heroes snatch the box from {villain} or out of the flames before the fire takes the pages.`),t(`Heltene får æsken, men de yderste sider er brændt; de sidste notitser kan stadig læses.`,`The heroes get the box, but the outer pages are burnt; the last entries can still be read.`)),n(`Charisma (Intimidation)`,`medium`,t(`{villain} taber olieflasken og vil hellere overgive sig til heltene end blive alene med {boss} i mørket.`,`{villain} drops the oil flask and would rather surrender to the heroes than be left alone in the dark with {boss}.`),t(`{villain} slår gnister med fyrtøjet og løber mod krybegangen; æsken lander i olien, og heltene må vælge mellem den og {villain}.`,`{villain} strikes a spark and runs for the crawlway; the box lands in the oil, and the heroes must choose between it and {villain}.`))],fight:!0,alternatives:[t(`Spær krybegangen først, hvis heltene kender den fra kortet: Uden vej ud forhandler {villain} om lys og følgeskab op til porten og giver æsken fra sig.`,`Block the crawlway first if the heroes know of it from the map: with no way out, {villain} bargains for light and an escort up to the gate, and hands over the box.`),t(`Brug larm eller ild til at trække {boss} væk fra den yderste søjle, mens én helt sniger sig ind og henter æsken.`,`Use noise or fire to draw {boss} away from the farthest pillar while one hero sneaks in and takes the box.`)],dmNotes:t(`Spil {villain}s skræk: Hernede er {villain} ikke rådsformand, kun en, der er bange for mørket. Hvert spor, heltene har fundet, kan bruges her, især kortet med krybegangen.`,`Play {villain}’s fear: down here {villain} is not the head of the council, only someone afraid of the dark. Every clue the heroes found can be used here, above all the map with the crawlway.`)}},"crawl-wound-traps":{opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`,`npc3`],title:t(`Tegnestuen ved daggry`,`The Drawing Office at Dawn`),summary:t([`Ved daggry lægger {npc1}, bygmesteren, nøglerne til porten og en pung på bordet og beder heltene gå gennem {place} før rådet, finde ud af, hvorfor arbejderne dør, og gøre stedet sikkert inden middag.`,`{npc1} sværger, at arbejdet var i orden, og de gamle bygmestertegninger på bordet viser et kammer under den dybeste sal, som ingen nulevende har set.`,`Byen kan give flere svar, men hver time i {town} er en time mindre dernede.`],[`At dawn {npc1}, the master builder, puts the gate keys and a purse on the table and asks the heroes to walk through {place} before the council does, find out why the workers are dying, and make the place safe by noon.`,`{npc1} swears the work was sound, and the old builders’ plans on the table show a chamber beneath the deepest hall that no one living has seen.`,`The town can give more answers, but every hour in {town} is an hour less below.`]),readAloud:t([`Tegnestuen lugter af lampeolie og vådt blæk, og på bordet ligger gulnede tegninger, holdt nede af en hammer og en nøglering.`,`På den ældste tegning løber tynde streger fra hver sal ned til et lille kammer under den dybeste.`,`Gennem vinduet ses det første grå lys over vejen til {place}.`],[`The drawing office smells of lamp oil and wet ink, and on the table lie yellowed plans, held down by a hammer and a ring of keys.`,`On the oldest sheet, thin lines run from every hall down to a small chamber beneath the deepest one.`,`Through the window the first grey light shows over the road to {place}.`]),details:[t(`Tegningerne er de gamle bygmestres egne. Kammeret under den dybeste sal er optrækskammeret, og påskriften siger det rent ud: Hjulet trukket op, og salene er lukket for alle. {npc1} har aldrig forstået, at urværket stadig virker.`,`The plans are the old builders’ own. The chamber beneath the deepest hall is the winding room, and the note on it says it plainly: wheel wound, and the halls are closed to all. {npc1} never understood that the clockwork still works.`),t(`Tre spor venter i byen, og hvert koster en halv time: {npc2}, arbejderen, der overlevede den sidste ulykke, så en lygte i den dybeste sal aftenen før og hørte nogen nynne den vise, {villain} altid nynner på stilladserne; {npc3}, smeden, har ordrebogen med {villain}s nye fjedre og lås; og blandt rådets papirer ligger et brev fra {villain}, dateret en uge før den første ulykke.`,`Three clues wait in town, and each costs half an hour. {npc2}, the worker who survived the last accident, saw a lantern in the deepest hall the night before and heard someone humming the tune {villain} always hums on the scaffolds. {npc3}, the smith, has the order book with {villain}’s new springs and lock. And among the council’s papers lies a letter from {villain}, dated a week before the first accident.`),t(`Rådet kommer ved middagstid, om seks timer, og {npc1} kan ikke udsætte inspektionen uden at miste opgaven. {villain} er inviteret med som gæst og spørger allerede rundt i byen, om nogen er gået ind i {place}.`,`The council comes at noon, in six hours, and {npc1} cannot put off the inspection without losing the commission. {villain} is invited along as a guest and is already asking around town whether anyone has gone into {place}.`)],checks:[n(`Intelligence (Investigation)`,`medium`,t(`Heltene forstår tegningen: Hver fælde er koblet til et hjul i kammeret under den dybeste sal, og en bremse dernede kan låse dem alle på én gang.`,`The heroes make sense of the plans: every trap is linked to a wheel in the chamber beneath the deepest hall, and a brake down there can lock them all at once.`),t(`Tegningerne er for mange og for gamle; heltene ved, at kammeret findes, men ikke hvad det gør, før de ser kæderne dernede.`,`The plans are too many and too old; the heroes know the chamber exists, but not what it does until they see the chains below.`)),n(`Charisma (Persuasion)`,`easy`,t(`{npc2} fortæller om lygten og visen og om, at fælden, der tog de andre, var nysmurt, selv om ingen af {npc1}s folk havde rørt mekanismen.`,`{npc2} tells of the lantern and the tune, and that the trap that took the others was freshly greased, though none of {npc1}’s people had touched the mechanism.`),t(`{npc2} er bange for at miste arbejdet og siger kun, at det ikke var en ulykke; navnet kommer først, når heltene vender tilbage med beviser.`,`{npc2} is afraid of losing their job and will only say it was no accident; the name comes out only when the heroes come back with proof.`))],fight:!1,alternatives:[t(`Gå direkte ned med tegningerne: Heltene sparer tiden i byen, men har ingen beviser mod {villain}, kun fælderne selv.`,`Go straight down with the plans: the heroes save the time in town but have no proof against {villain}, only the traps themselves.`),t(`Lad en af heltene blive i byen og holde øje med {villain}: Når {villain} hører, at nogen er gået ind i {place}, tager {villain} en lygte og fører den, der følger efter, lige til en sidegang.`,`Leave one hero in town to keep an eye on {villain}: when {villain} hears that someone has gone into {place}, {villain} takes a lantern and leads whoever follows straight to a side passage.`)],dmNotes:t(`Læg tegningerne på bordet foran spillerne; de er både et kort og et løfte om, at der findes en bremse. Sig højt, hvor lang tid hvert besøg i byen koster.`,`Put the plans on the table in front of the players; they are both a map and a promise that a brake exists. Say aloud how long each visit in town costs.`)},middle:[{kind:`puzzle`,at:`site`,present:[],title:t(`Fælden ved stilladset`,`The Trap by the Scaffold`),summary:t([`I salen, hvor den sidste ulykke skete, står stilladset endnu, og en vippeflise foran det har allerede taget et liv.`,`Når heltene afvæbner fælden, drejer det store hjul et hak, og ti minutter senere klikker den på plads igen.`,`Her lærer heltene, at fælderne styres et andet sted fra, og at kun en fælde, der er kilet fast, forbliver sikker.`],[`In the hall where the last accident happened, the scaffold still stands, and a tipping flagstone in front of it has already taken a life.`,`When the heroes disarm the trap, the great wheel turns a notch, and ten minutes later the trap clicks back into place.`,`Here the heroes learn that the traps are driven from somewhere else, and that only a wedged trap stays safe.`]),readAloud:t([`Stilladset står stadig langs væggen, og værktøjet ligger, hvor arbejderne tabte det.`,`Foran stilladset er en stor gulvflise strøet med savsmuld, og fra loftet over den løber en tynd kæde hen over salen og forsvinder ned ad en trappe.`,`Luften lugter af frisk fedt.`],[`The scaffold still stands along the wall, and the tools lie where the workers dropped them.`,`In front of the scaffold a large flagstone is strewn with sawdust, and from the ceiling above it a thin chain runs across the hall and disappears down a stair.`,`The air smells of fresh grease.`]),details:[t(`Salene lige inden for porten er sat i stand og sikre, men flisen her vipper, når nogen træder på den, og sender vedkommende ned i en dyb skakt. Det var her, den sidste ulykke skete, og ingen er gået længere ind siden.`,`The halls just inside the gate are restored and safe, but this flagstone tips when someone steps on it and drops them into a deep shaft. This is where the last accident happened, and nobody has gone further in since.`),t(`Afvæbner heltene fælden (første tik), drejer det store hjul i optrækskammeret et hak: En langsom tikken går gennem væggene, og ti minutter senere klikker fælden på plads igen. Kun en fælde, der er kilet fast med jern eller træ, forbliver sikker.`,`If the heroes disarm the trap (the first tick), the great wheel in the winding room turns a notch: a slow ticking runs through the walls, and ten minutes later the trap clicks back into place. Only a trap wedged with iron or wood stays safe.`),t(`Skiller heltene mekanismen ad, finder de nye fjedre, frisk fedt og en lille messingplade med mærket fra {villain}s værksted, en vinkel i en cirkel. Kæden over flisen er en af mange, og de løber alle ned mod den dybeste sal.`,`If the heroes take the mechanism apart, they find new springs, fresh grease and a small brass tag with the mark of {villain}’s workshop, a square inside a circle. The chain above the flagstone is one of many, and all of them run down toward the deepest hall.`)],checks:[n(`Dexterity (Sleight of Hand)`,`medium`,t(`Heltene afvæbner fælden og kiler vippeflisen fast, så den bliver liggende, når hjulet drejer.`,`The heroes disarm the trap and wedge the flagstone so it stays put when the wheel turns.`),t(`Flisen vipper, mens heltene arbejder; den nærmeste helt når at gribe fat i kanten, men taber værktøj eller lys ned i skakten.`,`The flagstone tips while the heroes are working; the nearest hero catches the edge but loses tools or a light down the shaft.`)),n(`Wisdom (Perception)`,`easy`,t(`Heltene ser kæderne i loftet og følger dem med øjnene: De løber alle samme vej, ned mod den dybeste sal.`,`The heroes notice the chains in the ceiling and follow them with their eyes: all of them run the same way, down toward the deepest hall.`),t(`Heltene lægger først mærke til kæderne, da fælden klikker på plads igen, og bruger ti minutter på at finde ud af hvorfor.`,`The heroes only notice the chains when the trap clicks back into place, and spend ten minutes working out why.`))],fight:!1,alternatives:[t(`Spring flisen over: Med et reb fra stilladset kan heltene svinge eller klatre forbi uden at røre fælden, men så er den stadig spændt, når rådet kommer.`,`Jump the flagstone: with a rope from the scaffold the heroes can swing or climb past without touching the trap, but then it is still armed when the council comes.`),t(`Følg kæden i stedet for at røre fælden: Den fører lige ned mod optrækskammeret, og den, der kiler hjulet fast, gør alle fælder sikre på én gang.`,`Follow the chain instead of touching the trap: it leads straight down toward the winding room, and whoever wedges the wheel makes every trap safe at once.`)],dmNotes:t(`Lad fælden klikke på plads igen lige så tydeligt, som den blev afvæbnet. Det øjeblik, hvor spillerne forstår, at noget styrer fælderne, er hele eventyrets omdrejningspunkt.`,`Let the trap click back into place as clearly as it was disarmed. The moment the players realise something is driving the traps is the turning point of the whole adventure.`)},{kind:`combat`,at:`site`,present:[],title:t(`Den åbne sidegang`,`The Opened Side Passage`),summary:t([`For enden af en sal er en gammel tilmuring brudt op, og den vej er {foe} kommet ind i {place}; {villain} åbnede den, så hver ulykke skulle ligne {npc1}s sjusk.`,`Her kæmper heltene mod {foe}, der har slået sig ned i sidegangen, og når der er gået tre timer, bevæger en lygte sig længere inde: {villain} er på vej ned mod optrækskammeret og spænder fælderne bag heltene igen.`,`I murbrokkerne ligger {villain}s lommebog med den sikre vej gennem hver sal.`],[`At the end of a hall an old bricked-up opening has been broken through, and {foe} have come into {place} that way; {villain} opened it so that every accident would look like {npc1}’s carelessness.`,`Here the heroes fight {foe} that have settled in the side passage, and once three hours have passed, a lantern moves deeper in: {villain} is heading down to the winding room, re-arming the traps behind the heroes.`,`In the rubble lies {villain}’s pocket book, with the safe way through every hall.`]),readAloud:t([`For enden af salen er en gammel tilmuring brudt op, og stenene ligger i en bunke under et lag frisk kalkstøv.`,`Bag hullet fortsætter en smal, ru gang, hvor gulvet er trådt op af mange fødder.`,`Længere inde lugter det af rådden mad og røg, og noget skraber mod sten.`],[`At the end of the hall an old bricked-up opening has been broken through, and the stones lie in a heap under a layer of fresh lime dust.`,`Beyond the hole a narrow, rough passage runs on, its floor trampled by many feet.`,`Further in it smells of rotten food and smoke, and something scrapes against stone.`]),details:[t(`Sidegangen er nu hjem for nogle {foe}, som {villain} lukkede ind for en måned siden. De forsvarer gangen, men følger ikke heltene ud i salene; de har lært, hvor fælderne sidder.`,`The side passage is now home to some {foe} that {villain} let in a month ago. They defend the passage but do not follow the heroes out into the halls; they have learned where the traps are.`),t(`I murbrokkerne ligger en lommebog, som {villain} har tabt, skrevet med {villain}s nydelige hånd: rækkefølgen for hver fælde og den sikre vej ned til optrækskammeret. Den er bevis på, hvem der trak fælderne op, og den gør resten af vejen langt lettere.`,`In the rubble lies a pocket book {villain} has dropped, written in {villain}’s neat hand: the sequence of every trap and the safe way down to the winding room. It proves who wound the traps, and it makes the rest of the way much easier.`),t(`Efter tre timer (andet tik) kommer {villain} ind ad sidegangen med en lygte på vej ned mod optrækskammeret og spænder fælderne bag heltene igen undervejs. Ser {villain} heltene, slukker {villain} lygten og forsvinder dybere ind; senere finder heltene frisk fedt på en fælde, de allerede er kommet forbi.`,`After three hours (the second tick) {villain} comes in through the side passage with a lantern, heading down to the winding room and re-arming the traps behind the heroes on the way. If {villain} sees the heroes, the lantern goes out and {villain} vanishes deeper in; later the heroes find fresh grease on a trap they have already passed.`)],checks:[n(`Intelligence (Investigation)`,`easy`,t(`Heltene finder lommebogen i murbrokkerne og har nu både den sikre vej og beviset.`,`The heroes find the pocket book in the rubble and now have both the safe path and the proof.`),t(`Heltene finder lommebogen, men først efter en halv times søgen mellem stenene.`,`The heroes find the pocket book, but only after half an hour of searching among the stones.`)),n(`Dexterity (Stealth)`,`medium`,t(`Kommer {villain} ind ad gangen, ser heltene lygten, før de selv bliver set, og kan følge efter på afstand helt ned til optrækskammeret.`,`If {villain} comes in through the passage, the heroes see the lantern before they are seen and can follow at a distance all the way down to the winding room.`),t(`{villain} hører dem og slukker lygten; et øjeblik efter klikker en fælde længere fremme på plads igen.`,`{villain} hears them and puts out the lantern; a moment later a trap further ahead clicks back into place.`))],fight:!0,alternatives:[t(`Mur hullet til igen med stenene fra bunken: Det tager en halv time, men så kan {foe} ikke slippe ud i salene, og {villain} må finde en anden vej ind.`,`Wall up the hole again with the stones from the heap: it takes half an hour, but then {foe} cannot get out into the halls, and {villain} must find another way in.`),t(`Snig jer hen til murbrokkerne, mens {foe} sover længere inde; lommebogen kan heltene nå uden kamp, hvis de er stille.`,`Creep up to the rubble while {foe} sleep further in; the heroes can reach the pocket book without a fight if they keep quiet.`)],dmNotes:t(`Sidegangen er stedet, hvor spillerne kan få fat i lommebogen. Gør den let at finde, hvis de har kæmpet godt, og lad {villain}s lygte vise, at skurken er tæt på.`,`The side passage is where the players can get hold of the pocket book. Make it easy to find if they fought well, and let {villain}’s lantern show that the villain is close.`)},{kind:`exploration`,at:`site`,present:[],title:t(`Salen med det andet klik`,`The Hall of the Second Click`),summary:t([`Trappen ned til den dybeste sal er plettet af frisk fedt og lugter af lampeolie, og salen nedenfor er den værste i {place}: Fælderne her er koblet sammen og går i en fast takt.`,`Med {villain}s lommebog kan heltene gå den sikre vej; uden den må de finde takten selv.`,`For enden af salen fører en smal trappe ned til en dør med en ny lås: optrækskammeret.`],[`The stair down to the deepest hall is spotted with fresh grease and smells of lamp oil, and the hall below is the worst in {place}: its traps are linked and fire in a steady beat.`,`With {villain}’s pocket book the heroes can walk the safe path; without it they must find the beat themselves.`,`At the far end of the hall a narrow stair leads down to a door with a new lock: the winding room.`]),readAloud:t([`Trinene er plettet af frisk, sort fedt, og luften lugter af lampeolie, selv om ingen har arbejdet hernede i en måned.`,`Salen nedenfor er lang og smal, og fra loftet hænger kæder, der strammes og slappes med et klik og så et klik til.`,`For enden fører en smal trappe længere ned, og derfra kommer en svag knirken, som af et stort hjul under spænding.`],[`The steps are spotted with fresh black grease, and the air smells of lamp oil, though nobody has worked down here for a month.`,`The hall below is long and narrow, and from the ceiling hang chains that tighten and slacken with a click, then another click.`,`At the far end a narrow stair leads further down, and from it comes a faint creaking, like a great wheel under strain.`]),details:[t(`Salens fælder er koblet sammen: Et forkert skridt udløser dem alle på række, fra døren og indad. Lommebogen siger: Vent på det andet klik, og gå så. Med den kommer heltene igennem uden terningslag.`,`The hall’s traps are linked: one wrong step sets them all off in a row, from the door inward. The pocket book says: wait for the second click, then go. With it the heroes get through without a roll.`),t(`Er der gået tre timer, er {villain} kommet herned før heltene og har smurt fælderne igen; fedtet på trappen er kun få minutter gammelt, og døren længere nede er lige blevet låst indefra.`,`If three hours have passed, {villain} has come down here ahead of the heroes and greased the traps again; the grease on the stair is only minutes old, and the door further down has just been locked from the inside.`),t(`Døren til optrækskammeret har en ny, svær lås fra {npc3}s smedje, og nøglen har kun {villain}. Låsen kan dirkes op, eller døren kan brydes op, men det sidste høres derinde.`,`The door to the winding room has a heavy new lock from {npc3}’s forge, and only {villain} has the key. The lock can be picked or the door broken down, but breaking it is heard inside.`)],checks:[n(`Wisdom (Perception)`,`medium`,t(`Heltene fanger takten: to klik, så stilhed. De kommer gennem salen uden at udløse noget.`,`The heroes catch the beat: two clicks, then silence. They get through the hall without setting anything off.`),t(`En helt træder for tidligt, og fælderne går af på række; heltene slipper igennem med skrammer, men larmen høres helt ned i optrækskammeret.`,`A hero steps too soon and the traps go off in a row; the heroes get through with cuts and bruises, but the noise carries all the way down to the winding room.`)),n(`Dexterity (Sleight of Hand)`,`hard`,t(`Låsen giver sig lydløst, og heltene står inde i optrækskammeret, før nogen derinde ved, at de kommer.`,`The lock gives way silently, and the heroes are inside the winding room before anyone in there knows they are coming.`),t(`Låsen giver sig til sidst med et smæld, og {boss} venter allerede bag døren.`,`The lock finally gives with a snap, and {boss} is already waiting behind the door.`))],fight:!1,alternatives:[t(`Udløs fælderne med vilje, én ad gangen, med sten eller en sæk fra stilladset, og løb igennem i de ti minutter, før hjulet spænder dem igen.`,`Set the traps off on purpose, one at a time, with stones or a sack from the scaffold, and run through in the ten minutes before the wheel re-arms them.`),t(`Vent ved døren i mørket: Når {villain} lukker op for at skynde sig op til inspektionen, står døren åben, og heltene kan gå ind.`,`Wait by the door in the dark: when {villain} opens it to hurry up to the inspection, the door stands open and the heroes can walk in.`)],dmNotes:t(`Tæl klikkene højt ved bordet: Bank to gange i bordpladen, og lad spillerne sige, hvornår de går. Har de lommebogen, så lad dem nyde, at de kender vejen.`,`Count the clicks out loud at the table: knock twice on the tabletop and let the players say when they go. If they have the pocket book, let them enjoy knowing the way.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:t(`Optrækskammeret`,`The Winding Room`),summary:t([`Under den dybeste sal står bygmestrenes store urværk, trukket op og nysmurt, og {villain} har lukket {boss} ind for at vogte det.`,`{villain} er her selv for at give det store hjul de sidste omgange og vil så skynde sig op ad en sidegang og gå med på inspektionen som gæst.`,`Heltene skal forbi {boss}, slå bremsestangen ned og kile det store hjul fast, før rådet går ind ved middagstid.`],[`Beneath the deepest hall stands the builders’ great clockwork, wound and freshly greased, and {villain} has let {boss} in to guard it.`,`{villain} is here in person to give the great wheel its last turns, meaning to hurry up a side passage afterwards and join the inspection as a guest.`,`The heroes must get past {boss}, throw the brake lever down and wedge the great wheel before the council walks in at noon.`]),readAloud:t([`Kammeret fyldes næsten af et hjul, der er dobbelt så højt som en mand, og fra det løber kæder op gennem loftet i alle retninger.`,`Tandhjul og lodder blinker af frisk fedt i skæret fra en lygte, og ved siden af hjulet står en lang jernstang med et slidt håndtag.`,`Ved hjulet står {villain} med et håndsving, og bag hjulet rører {boss} sig i mørket.`],[`A wheel twice the height of a man almost fills the chamber, and chains run from it up through the ceiling in every direction.`,`Cogs and weights glint with fresh grease in the light of a lantern, and beside the wheel stands a long iron lever with a worn grip.`,`At the wheel stands {villain} with a crank, and behind the wheel {boss} stirs in the dark.`]),details:[t(`{boss} og nogle {foe} fra sidegangene vogter kammeret for {villain}, der har lukket dem ind og betalt eller fodret dem i en måned. {villain} kæmper ikke selv, men holder sig bag hjulet og prøver at slippe op ad sidegangen, så {villain} kan stå ved porten som en uskyldig gæst ved middagstid.`,`{boss} and some {foe} from the side passages guard the room for {villain}, who let them in and has paid or fed them for a month. {villain} does not fight, but keeps behind the wheel and tries to slip away up the side passage, so as to stand at the gate as an innocent guest at noon.`),t(`Bremsestangen ned standser hjulet og låser alle fælder i {place}, men kun en kile i egerne holder det stille; uden den kan enhver slå stangen op igen, og det ved {villain}.`,`Throwing the brake lever down stops the wheel and locks every trap in {place}, but only a wedge through the spokes keeps it still; without one, anyone can throw the lever back up, and {villain} knows it.`),t(`Ved middagstid går inspektionen ind i {place} med {npc1} forrest. Slår heltene bremsestangen ned, før rådet når de værste sale, går alle sikkert igennem; ellers må en af dem løbe op og standse inspektionen ved porten.`,`At noon the inspection enters {place} with {npc1} in front. If the heroes throw the brake lever down before the council reaches the worst halls, everyone walks through safely; if not, one of them must run up and stop the inspection at the gate.`)],checks:[n(`Dexterity (Acrobatics)`,`hard`,t(`En helt slipper forbi {boss} og ind under kæderne til bremsestangen, mens de andre holder kampen i gang.`,`One hero slips past {boss} and in under the chains to the brake lever while the others keep the fight going.`),t(`{boss} spærrer vejen til stangen, og heltene må kæmpe sig frem til den.`,`{boss} blocks the way to the lever, and the heroes must fight their way to it.`)),n(`Strength (Athletics)`,`medium`,t(`Heltene slår bremsestangen ned og kiler hjulet fast med en jernstang gennem egerne; hver eneste fælde i {place} er låst.`,`The heroes throw the brake lever down and wedge the wheel with an iron bar through the spokes; every trap in {place} is locked.`),t(`Stangen går halvt ned og sidder fast; hjulet står stille, men kun så længe nogen hænger i stangen, og det binder én helt, til kilen er sat.`,`The lever goes halfway down and sticks; the wheel stops, but only while someone hangs on the lever, which ties up one hero until the wedge is in.`))],fight:!0,alternatives:[t(`Har heltene lommebogen, så vis {villain} den: Med beviset i deres hænder er der intet at vinde ved middagstid, og {villain} forhandler om at slippe for rådets dom.`,`If the heroes have the pocket book, show it to {villain}: with the proof in the heroes’ hands, {villain} has nothing left to win at noon and bargains to be spared the council’s judgement.`),t(`Spær sidegangen, før kampen begynder: Så kan {villain} ikke nå op og spille uskyldig gæst og overgiver sig hellere end at blive fundet i kammeret, når rådet kommer.`,`Block the side passage before the fight starts: then {villain} cannot get up to play the innocent guest, and would rather surrender than be found in the room when the council comes.`)],dmNotes:t(`Kammeret skal føles som et levende urværk: Kæderne rasler, når nogen rammer dem, og hvert slag mod hjulet kan få en fælde langt oppe til at gå af. Gør bremsestangen til et mål, alle ved bordet kan se.`,`The room should feel like living clockwork: the chains rattle when someone hits them, and every blow against the wheel may set off a trap far above. Make the brake lever a goal everyone at the table can see.`)}},"investigation-wrong-root":{opening:{kind:`opening`,at:`town`,present:[`npc1`],title:t(`Flasken ved sengen`,`The Bottle by the Bed`),summary:t([`Om morgenen tager {npc1}, der stadig bærer sorg, heltene med ind i kammeret, hvor {npc1}s ægtefælle døde, og beder dem finde ud af, hvad der i virkeligheden slog de tre ihjel, før de ældste dømmer {npc2} ved solnedgang.`,`Byen taler om en forbandelse fra {place} og har malet et afværgetegn på {npc2}s dør, men på natbordet står en halvtom flaske vintertonik fra {villain}s hånd.`,`Her finder heltene de første spor: flasken, bundfaldet i koppen og det, {npc1} så ved rendestenen.`],[`In the morning {npc1}, still in mourning, takes the heroes into the room where {npc1}’s spouse died and asks them to find out what really killed the three victims before the elders pass judgement on {npc2} at sunset.`,`The town talks of a curse from {place} and has painted a warding sign on {npc2}’s door, but on the bedside table stands a half-empty bottle of winter tonic from {villain}’s hand.`,`Here the heroes find the first clues: the bottle, the dregs in the cup, and what {npc1} saw by the gutter.`]),readAloud:t([`Kammeret er koldt, og sengen står, som den blev efterladt, for ingen har haft hjerte til at røre den.`,`På natbordet står en halvtom flaske med en pæn, håndskrevet etiket og en kop med en rødlig rand i bunden.`,`Gennem vinduet høres folk på gaden tale lavt om forbandelsen fra {place}.`],[`The room is cold, and the bed is as it was left, for nobody has had the heart to touch it.`,`On the bedside table stand a half-empty bottle with a neat handwritten label and a cup with a reddish ring at the bottom.`,`Through the window, people in the street can be heard talking in low voices about the curse from {place}.`]),details:[t(`Etiketten siger, at tonikken er brygget af {villain} på frostmånedens tredje dag. Samme flaske står i de to andre dødes hjem, og bundfaldet i koppen er rødligt og bittert.`,`The label says the tonic was brewed by {villain} on the third day of the frost month. The same bottle stands in the homes of the other two dead, and the dregs in the cup are reddish and bitter.`),t(`{npc1} så {villain} hælde en flaske ud i rendestenen dagen efter det første dødsfald, men har ikke turdet sige det højt; helbrederen er den, hele byen stoler på.`,`{npc1} saw {villain} pour a bottle into the gutter the day after the first death, but has not dared say it aloud; the healer is the one the whole town trusts.`),t(`De ældste afsiger dom ved solnedgang, om otte timer. Afværgetegnet på {npc2}s dør blev malet i nat, og {npc2} tør ikke vise sig i byen, men sidder i hytten ved {place}.`,`The elders pass judgement at sunset, eight hours from now. The warding sign on {npc2}’s door was painted in the night, and {npc2} dares not show up in town but keeps to the hut near {place}.`),t(`Flasken her overbeviser heltene, men ikke de ældste: {villain} har sagt, at forbandelsen sidder i alt, de døde har rørt ved, og en åbnet flaske fra et dødsleje bliver kaldt forbandet, ikke giftig. Kun en uåbnet flaske fra samme bryg kan få de ældste til at lytte.`,`The bottle here convinces the heroes but not the elders: {villain} has told them the curse clings to everything the dead touched, and an opened bottle from a deathbed will be called cursed, not poisoned. Only an unopened bottle from the same batch can make the elders listen.`)],checks:[n(`Wisdom (Medicine)`,`medium`,t(`Bundfaldet kommer fra en rod, ikke fra en sygdom: Den røde rod er giftig i store mål, og det ved enhver helbreder.`,`The dregs come from a root, not from any sickness: the red root is poisonous in large doses, and every healer knows it.`),t(`Heltene kan ikke sige, hvad bundfaldet er; en med forstand på urter må se på det, og den nærmeste er {villain}s lærling.`,`The heroes cannot tell what the dregs are; someone who knows herbs must look at them, and the nearest such person is {villain}’s apprentice.`)),n(`Charisma (Persuasion)`,`easy`,t(`{npc1} lader heltene tage flasken og koppen med som bevis og giver dem navnene på de to andre familier.`,`{npc1} lets the heroes take the bottle and the cup as evidence and gives them the names of the other two families.`),t(`{npc1} vil ikke af med det sidste, ægtefællen rørte ved; heltene må nøjes med at se flasken og huske etiketten.`,`{npc1} will not part with the last thing their spouse touched; the heroes must make do with looking at the bottle and remembering the label.`))],fight:!1,alternatives:[t(`Besøg de to andre dødes hjem: Det koster en halv time, men samme etiket og samme bundfald dér gør sagen svær at feje af bordet.`,`Visit the homes of the other two dead: it costs half an hour, but the same label and the same dregs there make the case hard to brush aside.`),t(`Gå direkte ud til {npc2}s hytte ved {place}: Samlerens egne rødder er blege, og {npc2} kender vejen ind i {place}.`,`Go straight out to {npc2}’s hut near {place}: the gatherer’s own roots are pale, and {npc2} knows the way into {place}.`)],dmNotes:t(`Lad flasken ligge på bordet resten af spillet; den er det første og vigtigste spor. Spillerne skal gå herfra med spørgsmålet: Hvorfor vil helbrederen af med sin egen tonik?`,`Keep the bottle on the table for the rest of the game; it is the first and most important clue. The players should leave with the question: why does the healer want to be rid of that tonic?`)},middle:[{kind:`investigation`,at:`town`,present:[`npc3`,`villain`],title:t(`Urtebogen med de tre navne`,`The Herb Book with Three Names`),summary:t([`I helbrederhuset står {villain} midt i en strøm af syge og bange naboer, og {npc3}, lærlingen, passer kedlerne.`,`Huset gemmer det meste af sandheden: urtebogen med de tre navne i margenen, en rød rod i haven og et halvbrændt papir i asken i ovnen.`,`Heltene må finde det uden at vække byens vrede, for {villain} er stadig den, hele {town} stoler på.`],[`In the healer’s house {villain} stands amid a stream of sick and frightened neighbours, and {npc3}, the apprentice, tends the kettles.`,`The house hides most of the truth: the herb book with three names in the margin, a red root in the garden and a half-burnt paper in the ashes of the stove.`,`The heroes must uncover it without stirring up the town’s anger, for {villain} is still the one all of {town} trusts.`]),readAloud:t([`Helbrederhuset dufter af kamille og varm honning, og bænken i forstuen er fuld af hostende naboer.`,`Bag disken står {villain} med rødrandede øjne og rækker en kop frem uden at se op.`,`Gennem bagdøren ses en have med pæne bede, og i det ene står en række kraftige planter med rødlige stængler.`],[`The healer’s house smells of camomile and warm honey, and the bench in the hall is full of coughing neighbours.`,`Behind the counter {villain} stands with red-rimmed eyes, holding out a cup without looking up.`,`Through the back door a garden of tidy beds can be seen, and in one of them stands a row of sturdy plants with reddish stems.`]),details:[t(`Urtebogen ligger på hylden over disken: Opskriften på vintertonikken er streget over med rystende hånd, og margenen er fuld af de tre dødes navne. Den røde rod i haven er den samme, som gav bundfaldet i koppen.`,`The herb book lies on the shelf above the counter: the winter tonic recipe is crossed out in a shaking hand, and the margin is full of the names of the three dead. The red root in the garden is the one that left the dregs in the cup.`),t(`{npc3} så {villain} køre ud med en kasse natten efter det første dødsfald og komme hjem uden den, med gråt støv på støvlerne, men tør ikke sige det, mens {villain} hører på. I asken i ovnen ligger et halvbrændt papir med {villain}s håndskrift om kassen i sidekammeret i {place}, og i gården står trækvognen med gråt støv i hjulene.`,`{npc3} saw {villain} wheel out a crate the night after the first death and come home without it, with grey dust on their boots, but dares not say so within {villain}’s hearing. In the ashes of the stove lies a half-burnt paper in {villain}’s hand about the crate in the side chamber at {place}, and in the yard stands the handcart with grey dust in its wheels.`),t(`Efter to timer (første tik) bærer naboer en fjerde patient ind med feber, og {villain} erklærer, at forbandelsen breder sig. Efter fem timer (andet tik) sender {villain} lærlingen af sted til en anden by og låser huset; trækvognen er væk fra gården, og {villain} er på vej mod {place} med en krukke lampeolie.`,`After two hours (the first tick) neighbours carry in a fourth patient with a fever, and {villain} declares that the curse is spreading. After five hours (the second tick) {villain} sends the apprentice off to another town and locks the house; the handcart is gone from the yard, and {villain} is on the way to {place} with a jar of lamp oil.`)],checks:[n(`Dexterity (Sleight of Hand)`,`medium`,t(`Heltene får fat i urtebogen eller det halvbrændte papir, mens {villain} har travlt med patienterne.`,`The heroes get hold of the herb book or the half-burnt paper while {villain} is busy with the patients.`),t(`{villain} ser dem ved hylden og tager bogen til sig; heltene har set siden, men har ikke beviset i hænderne.`,`{villain} sees them at the shelf and takes the book away; the heroes have seen the page but do not hold the proof.`)),n(`Charisma (Persuasion)`,`medium`,t(`Ude i haven fortæller {npc3} om kassen og den røde rod og lover at vidne, hvis nogen står ved lærlingens side bagefter.`,`Out in the garden {npc3} tells of the crate and the red root and promises to testify, if someone stands by the apprentice afterwards.`),t(`{npc3} er for bange til at tale, men kigger ud mod de røde stængler i haven, da heltene spørger til rødderne.`,`{npc3} is too frightened to talk, but glances out at the red stems in the garden when the heroes ask about roots.`))],fight:!1,alternatives:[t(`Spørg {villain} direkte om tonikken: {villain} lyver dårligt, taber en kop og beder heltene gå, og det siger mere end ord.`,`Ask {villain} straight out about the tonic: {villain} lies badly, drops a cup and asks the heroes to leave, and that says more than words.`),t(`Kom tilbage, når huset er låst efter den femte time: Så er der ingen hjemme, og heltene kan gennemsøge det i ro, men {villain} er allerede på vej mod {place}.`,`Come back once the house is locked after the fifth hour: then nobody is home and the heroes can search it in peace, but {villain} is already on the way to {place}.`)],dmNotes:t(`Spil {villain} som en, der er ved at gå i stykker, ikke som en skurk: venlig, træt og bange. Spillerne skal have lyst til at redde både {npc2} og {villain} fra det, der er ved at ske.`,`Play {villain} as someone falling apart, not as a villain: kind, exhausted and frightened. The players should want to save both {npc2} and {villain} from what is about to happen.`)},{kind:`social`,at:`town`,present:[],title:t(`Torvet med de brændende rødder`,`The Square of Burning Roots`),summary:t([`På torvet bærer folk {npc2}s rødder ud fra markedet for at brænde dem, og de ældste står på trappen ved brønden og ser til.`,`Her kan heltene vise, at {npc2}s rødder er blege, mens bundfaldet i de dødes kopper er rødt, og få de ældste til at love, at de vil se på beviserne, før de dømmer.`,`Scenen afgør, om byen er med heltene eller imod dem, når de kommer tilbage ved solnedgang.`],[`In the square people carry {npc2}’s roots out of the market to burn them, and the elders stand on the steps by the well, watching.`,`Here the heroes can show that {npc2}’s roots are pale while the dregs in the victims’ cups are red, and get the elders to promise to look at the proof before they judge.`,`The scene decides whether the town is with the heroes or against them when they come back at sunset.`]),readAloud:t([`Torvet er fuldt af mennesker, og midt på brostenene brænder et bål af rødder og kurve, der giver en sur, hvid røg.`,`En kvinde råber, at forbandelsen har ramt en fjerde, og flere stemmer svarer hende.`,`På trappen ved brønden står de ældste i deres mørke kapper og siger ingenting.`],[`The square is full of people, and in the middle of the cobbles a fire of roots and baskets burns with a sour white smoke.`,`A woman shouts that the curse has struck a fourth, and several voices answer her.`,`On the steps by the well the elders stand in their dark cloaks and say nothing.`]),details:[t(`Bålet bliver tændt ved det første tik, da {villain} erklærer, at forbandelsen breder sig. Kommer heltene tidligere, står {npc2}s bod endnu, og kurvene med blege rødder kan undersøges i ro.`,`The fire is lit at the first tick, when {villain} declares the curse is spreading. If the heroes come earlier, {npc2}’s stall still stands, and the baskets of pale roots can be examined in peace.`),t(`De ældste er ikke onde, men bange for at miste byens tillid. Viser heltene dem flasken med etiket og det røde bundfald, lover de at høre heltene ved solnedgang, men de dømmer ikke på mistanke alene: De vil se kassen og høre en, der kan udpege roden.`,`The elders are not cruel, only afraid of losing the town’s trust. If the heroes show them the labelled bottle and the red dregs, they promise to hear the heroes at sunset, but they will not judge on suspicion alone: they want to see the crate and hear someone who can name the root.`),t(`Efter fem timer (andet tik) ruller en vogn over torvet og ud ad byporten med {npc3} på bukken; {villain} har sendt lærlingen bort i et ærinde, der slet ikke haster. Standser heltene vognen, kan de få {npc3} med tilbage.`,`After five hours (the second tick) a cart rolls across the square and out of the town gate with {npc3} on the box; {villain} has sent the apprentice away on an errand that is not urgent at all. If the heroes stop the cart, they can bring {npc3} back.`)],checks:[n(`Charisma (Persuasion)`,`medium`,t(`De ældste lover at vente med dommen, til de har set heltenes beviser ved solnedgang, og mængden lader {npc2}s sidste kurve være.`,`The elders promise to hold back judgement until they have seen the heroes’ proof at sunset, and the crowd leaves {npc2}’s last baskets alone.`),t(`Mængden buher heltene ud som {npc2}s venner; de ældste vil kun se beviserne, hvis de bliver lagt frem på torvet foran alle.`,`The crowd boos the heroes as {npc2}’s friends; the elders will only look at the proof if it is laid out in the square in front of everyone.`)),n(`Intelligence (Nature)`,`easy`,t(`Heltene kan vise forskellen: {npc2}s rødder er blege og søde, mens den røde rod, der gav bundfaldet, gror i helbrederens egen have.`,`The heroes can show the difference: {npc2}’s roots are pale and sweet, while the red root that left the dregs grows in the healer’s own garden.`),t(`Rødderne ligner hinanden for et utrænet øje, og mængden er ligeglad; heltene skal bruge {npc3} eller kassen for at bevise det.`,`To an untrained eye the roots look alike, and the crowd does not care; the heroes need {npc3} or the crate to prove it.`))],fight:!1,alternatives:[t(`Red en kurv af {npc2}s rødder ud af bålet: Sammen med koppen fra {npc1}s hjem viser den forskellen for alle.`,`Pull a basket of {npc2}’s roots out of the fire: together with the cup from {npc1}’s home it shows the difference to everyone.`),t(`Lad torvet være, og brug tiden i {place}: Uden de ældstes løfte skal beviset lægges frem foran hele mængden ved solnedgang.`,`Leave the square alone and spend the time in {place}: without the elders’ promise, the proof must be laid out before the whole crowd at sunset.`)],dmNotes:t(`Mængden er ikke ond, men bange; giv den ansigter: en mor med et sygt barn, en bager, der købte rødder af {npc2} i forgårs. Den, der vinder én af dem, vinder flere.`,`The crowd is not wicked, only afraid; give it faces: a mother with a sick child, a baker who bought roots from {npc2} the day before yesterday. Win one of them over and others follow.`)},{kind:`exploration`,at:`site`,present:[`npc2`],title:t(`Sporet af anis og sirup`,`The Trail of Anise and Syrup`),summary:t([`Inde i {place} går hjulspor fra en trækvogn hen ad hovedgangen og drejer ind i en sidegang, og i det ene spor glimter et skår af brunt glas med en stump af {villain}s etiket.`,`Længere inde hænger en sødlig lugt af anis og sirup, og den bliver stærkere hen mod et sidekammer, hvor {foe} har slået sig ned.`,`Her ved heltene, at kassen er tæt på, og de kan vælge, hvordan de vil gå ind.`],[`Inside {place}, the ruts of a handcart run along the main passage and turn into a side passage, and in one of them glints a shard of brown glass with a scrap of {villain}’s label.`,`Further in hangs a sweet smell of anise and syrup, growing stronger toward a side chamber where {foe} have made their den.`,`Here the heroes know the crate is close and can choose how to go in.`]),readAloud:t([`Hovedgangen er støvet og grå, og i støvet løber to smalle hjulspor og aftryk af et par støvler.`,`Hvor sporene drejer ind i en sidegang, glimter noget i lyset: et skår af brunt glas med en revet etiket.`,`Fra sidegangen kommer en sødlig lugt af anis og sirup, så sød, at den næsten giver kvalme.`],[`The main passage is dusty and grey, and in the dust run two narrow wheel ruts and the prints of a pair of boots.`,`Where the ruts turn into a side passage, something glints in the light: a shard of brown glass with a torn label.`,`From the side passage comes a sweet smell of anise and syrup, so sweet it is almost sickening.`]),details:[t(`Det grå støv i gangen er det samme, som {npc3} så på {villain}s støvler natten efter det første dødsfald. Glasskåret bærer en stump af etiketten: "Vintertonik. Brygget af {villain}".`,`The grey dust in the passage is the same as the dust {npc3} saw on {villain}’s boots the night after the first death. The shard still carries a scrap of the label: "Winter tonic. Brewed by {villain}".`),t(`Sidekammeret er hulen for {boss} og nogle {foe}, der flyttede ind, efter at kassen blev sat der; nogle af flaskerne er gået i stykker, og den søde lugt har lokket dem til.`,`The side chamber is the den of {boss} and some {foe} that moved in after the crate was put there; some of the bottles have broken, and the sweet smell drew them in.`),t(`Er der gået fem timer, står {villain}s trækvogn tom ved indgangen til sidegangen, og {villain} venter allerede derinde. Ved {npc2}s hytte uden for {place} lyser afværgetegnet på døren; er {npc2} hjemme, kan samleren vise heltene den korteste vej ind.`,`If five hours have passed, {villain}’s handcart stands empty at the mouth of the side passage, and {villain} is already waiting inside. At {npc2}’s hut outside {place} the warding sign glares from the door; if {npc2} is at home, the gatherer can show the heroes the shortest way in.`)],checks:[n(`Wisdom (Survival)`,`easy`,t(`Heltene følger sporene lige til sidekammeret og ser, at nogen kørte noget tungt ind og kom ud med en tom vogn: Sporene er dybere på vejen ind.`,`The heroes follow the ruts straight to the side chamber and see that someone wheeled something heavy in and came out with an empty cart: the ruts are deeper going in.`),t(`Gangene deler sig, og heltene går forkert et stykke; det koster en halv time.`,`The passages fork and the heroes go the wrong way for a while; it costs half an hour.`)),n(`Dexterity (Stealth)`,`medium`,t(`Heltene når helt hen til sidekammerets åbning uden at blive hørt og kan se, hvem der er derinde, før nogen ser dem.`,`The heroes reach the mouth of the side chamber unheard and can see who is inside before anyone sees them.`),t(`Et glasskår knaser under en støvle, og derinde bliver der stille; hulen er vågen, når heltene går ind.`,`A shard crunches under a boot and the chamber goes quiet; the den is awake when the heroes go in.`))],fight:!1,alternatives:[t(`Få {npc2} til at vise vejen: Samleren kender gangene og kan føre heltene ind ad en sprække, der kommer ud bag sidekammeret.`,`Get {npc2} to show the way: the gatherer knows the passages and can lead the heroes in through a crack that comes out behind the side chamber.`),t(`Lok {foe} ud af hulen med larm eller lys længere nede ad gangen, og gå ind, mens de er væk.`,`Lure {foe} out of the den with noise or light further down the passage, and go in while they are away.`)],dmNotes:t(`Brug lugten som en tråd: Den bliver stærkere, hver gang heltene vælger rigtigt. Husk at sige, hvor længe der er til solnedgang; vejen tilbage til {town} tager en halv time.`,`Use the smell as a thread: it grows stronger each time the heroes choose the right way. Remember to say how long it is until sunset; the way back to {town} takes half an hour.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:t(`Kassen i sidekammeret`,`The Crate in the Side Chamber`),summary:t([`I sidekammeret står kassen med resten af vintertonikken midt i den hule, hvor {boss} og nogle {foe} har slået sig ned.`,`Siden eftermiddagen har {villain} ventet ved åbningen med en krukke lampeolie og en fakkel for at brænde kassen ved solnedgang, når røgen fra {npc2}s brændende hytte skjuler røgen herfra; hulen tjener ingen og angriber alle, der kommer ind.`,`Heltene skal redde mindst én flaske med etiket og bundfald og nå tilbage til de ældste før solnedgang.`],[`In the side chamber the crate with the rest of the winter tonic stands in the middle of the den where {boss} and some {foe} have settled.`,`Since the afternoon {villain} has been waiting at the opening with a jar of lamp oil and a torch, to burn the crate at sunset, when the smoke from {npc2}’s burning hut will hide the smoke from here; the den serves no one and attacks anyone who comes in.`,`The heroes must save at least one labelled bottle with its dregs and get back to the elders before sunset.`]),readAloud:t([`Den søde lugt er så tæt herinde, at den sætter sig i halsen.`,`I det bageste hjørne af sidekammeret står en trækasse under en revet sæk, omgivet af gnavede knogler, laset halm og knust glas, og noget trækker vejret i mørket omkring den.`,`Lige inden for åbningen sidder en skikkelse i en helbrederkappe på hug ved siden af en krukke lampeolie og en fakkel, der endnu ikke er tændt.`],[`The sweet smell is so thick in here that it sticks in the throat.`,`In the far corner of the side chamber a wooden crate stands under a torn sack, surrounded by gnawed bones, ragged straw and broken glass, and something is breathing in the dark around it.`,`Just inside the opening a figure in a healer’s coat crouches beside a jar of lamp oil and a torch that is not yet lit.`]),details:[t(`{boss} og nogle {foe} har deres hule her og tjener ikke {villain}; de forsvarer den mod alle, også mod helbrederen. Når kampen bryder løs, tænder {villain} faklen og prøver at kaste olien ind over kassen.`,`{boss} and some {foe} have their den here and do not serve {villain}; they defend it against everyone, the healer included. When the fight breaks out, {villain} lights the torch and tries to throw the oil over the crate.`),t(`Kommer heltene før eftermiddagen, er {villain} her ikke endnu, men dukker op med krukken og trækvognen, mens de er i hulen; {villain} har hørt, at de har taget vejen mod {place}. Kommer de ved solnedgang, brænder kassen allerede, og de har én runde til at redde de flasker, de kan nå.`,`If the heroes come before the afternoon, {villain} is not here yet but turns up with the jar and the handcart while they are in the den, having heard that they took the road to {place}. If they come at sunset, the crate is already burning, and they have one round to save the bottles they can reach.`),t(`Kassen rummer stadig en snes hele flasker med {villain}s etiket, og én med bundfald er bevis nok. Står {villain} over for flaskerne, eller kommer {npc2} i virkelig fare for øjnene af {villain}, brister facaden, og {villain} tilstår. Vejen tilbage til torvet i {town} tager en halv time.`,`The crate still holds a score of whole bottles with {villain}’s label, and one with its dregs is proof enough. When {villain} is faced with the bottles, or sees {npc2} in real danger, the mask cracks and {villain} confesses. The way back to the square in {town} takes half an hour.`)],checks:[n(`Dexterity (Acrobatics)`,`medium`,t(`En helt når {villain}, før krukken bliver kastet, og vrider den ud af hænderne på helbrederen; flaskerne er i sikkerhed.`,`A hero reaches {villain} before the jar is thrown and wrests it away; the bottles are safe.`),t(`Olien rammer halmen ved kassen, og ilden tager fat; heltene redder kun de flasker, de kan nå på én runde.`,`The oil splashes over the straw by the crate and the fire takes hold; the heroes save only the bottles they can reach in one round.`)),n(`Wisdom (Insight)`,`easy`,t(`Heltene ser, at {villain} ikke er nogen morder, kun en, der ikke har sovet, siden den første døde. Et roligt ord om de tre navne i urtebogen får {villain} til at sænke faklen.`,`The heroes see that {villain} is no murderer, only someone who has not slept since the first death. A quiet word about the three names in the herb book makes {villain} lower the torch.`),t(`Heltene ser kun en, der vil brænde beviserne, og {villain} løber mod udgangen, da {boss} angriber.`,`The heroes see only someone set on burning the proof, and {villain} runs for the way out when {boss} attacks.`))],fight:!0,alternatives:[t(`Er {npc2} fulgt med, kan samlerens fare være det, der knækker {villain}: Når hulen går løs på samleren, kaster {villain} faklen fra sig og råber sandheden ud.`,`If {npc2} came along, the gatherer’s danger may be what breaks {villain}: when the den turns on the gatherer, {villain} throws the torch aside and shouts out the truth.`),t(`Hent kassen, mens hulen sover, og kør den til torvet på {villain}s egen trækvogn: Så ser hele byen flaskerne og den vogn, de kom på.`,`Take the crate while the den sleeps and wheel it to the square on {villain}’s own handcart: then the whole town sees the bottles and the cart they came on.`)],dmNotes:t(`Husk uret: Kampen er ikke målet, flasken er. Sig, hvor længe der er til solnedgang, når heltene kommer ud, og lad sejren afhænge af, om de når torvet i tide.`,`Remember the clock: the fight is not the goal, the bottle is. Say how long it is until sunset when the heroes come out, and let the victory depend on reaching the square in time.`)}},"investigation-lead-silver":{opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`],title:t(`Tre mønter på bordet`,`Three Coins on the Table`),summary:t([`Ved skumring smækker {npc1}, kroejeren, tre falske mønter på bordet foran heltene og tilbyder dem gratis kost og logi et helt år, hvis de finder ud af, hvem der har præget dem, før møntinspektøren kommer.`,`Mønterne er smukke, men tunge af bly, og alle har den samme lille dobbeltprægning på kronen; imens sidder {npc2}, guldsmeden, spærret inde for det, og kongens møntinspektør er ventet ved daggry.`,`Kroen summer af sladder, og den rette snak kan pege heltene mod {place}.`],[`At dusk {npc1}, the innkeeper, slaps three false coins on the table in front of the heroes and offers them free board and lodging for a year if they find out who struck them before the assayer arrives.`,`The coins are handsome but heavy with lead, and all bear the same tiny double strike on the crown; meanwhile {npc2}, the goldsmith, is locked up for it, and the king’s assayer is expected at dawn.`,`The inn hums with gossip, and the right talk can point the heroes toward {place}.`]),readAloud:t([`Kroen er fuld af røg og stemmer, og på bordet foran heltene ligger tre sølvmønter, der skinner lidt for pænt.`,`Den ene er skåret over med en kniv, og under det tynde lag sølv er kernen grå og mat.`,`Ved vinduet sidder et par handlende og taler lavt om guldsmeden, som vagten har spærret inde.`],[`The inn is full of smoke and voices, and on the table in front of you lie three silver coins that shine a little too brightly.`,`One of them has been cut through with a knife, and beneath the thin layer of silver its heart is grey and dull.`,`By the window a couple of traders talk in low voices about the goldsmith the watch has locked up.`]),details:[t(`Alle tre mønter har en lille dobbeltprægning på kronen, den fejl, som byens gamle møntstempler altid har haft. Stemplerne ligger i byens pengeskab, og nøglen har kun vejermesteren, {villain}.`,`All three coins have a tiny double strike on the crown, the flaw the old town dies have always had. The dies are kept in the town strongbox, and only the weigh-master, {villain}, holds the key.`),t(`Sladderen i kroen: De første falske mønter dukkede op i boderne nærmest vejen fra {place}, og kulhandleren praler af, at vejermesterens karl købte tre sække trækul på én gang i sidste uge og kørte dem ud ad den vej.`,`The gossip in the inn: the first false coins turned up at the stalls nearest the road from {place}, and the charcoal seller boasts that the weigh-master’s hired man bought three sacks at once last week and carted them off down that road.`),t(`Flere spor venter i byen, og hvert koster en halv time: {npc3}, rådets skriver, fører nøglebogen over pengeskabet, og {villain}s kontor i vejerhuset er låst for natten. {npc2} sidder i vagtens arrest og ved kun, at anklagen kom fra {villain}, lige efter at guldsmeden havde solgt sølvtråd til byen.`,`More leads wait in town, and each costs half an hour: {npc3}, the council clerk, keeps the key book for the strongbox, and {villain}’s office in the weigh-house is locked for the night. {npc2} is held in the watch’s lock-up and knows only that the charge came from {villain}, just after the goldsmith had sold silver wire to the town.`)],checks:[n(`Intelligence (Investigation)`,`easy`,t(`Heltene ser dobbeltprægningen og ved, at mønterne er slået med byens egne stempler, ikke med en falskners hjemmelavede.`,`The heroes spot the double strike and know the coins were struck with the town’s own dies, not some forger’s home-made ones.`),t(`Heltene ser kun, at mønterne er falske; først da {npc1} lægger en ægte bymønt ved siden af, ser de den samme fejl på kronen.`,`The heroes only see that the coins are false; not until {npc1} lays a genuine town coin beside them do they see the same flaw on the crown.`)),n(`Charisma (Persuasion)`,`easy`,t(`Kulhandleren ved disken fortæller selv om de tre sække og om karlen, der kørte dem ud mod {place}.`,`The charcoal seller at the counter tells of the three sacks and of the hired man who carted them out toward {place}.`),t(`Kulhandleren vil først snakke, når heltene har givet en omgang; det koster tid og penge, men sladderen kommer.`,`The charcoal seller will only talk once the heroes stand a round; it costs time and coin, but the gossip comes.`))],fight:!1,alternatives:[t(`Gå direkte ud mod {place} ad vejen fra boderne: Heltene sparer tiden i byen, men ved intet om midnatsplanen.`,`Head straight out toward {place} along the road from the stalls: the heroes save the time in town but know nothing of the midnight plan.`),t(`Vis mønterne til {npc2} i arresten: Guldsmeden genkender straks byens gamle stempler og kan sige, hvem der har nøglen.`,`Show the coins to {npc2} in the lock-up: the goldsmith recognises the old town dies at once and can say who holds the key.`)],dmNotes:t(`Lad mønten gå rundt ved bordet. Når spillerne selv ser, at falskneriet er gjort med byens egne stempler, peger sagen af sig selv mod den, der har nøglen.`,`Pass the coin around the table. Once the players see for themselves that the forgery was done with the town’s own dies, the case points by itself to whoever holds the key.`)},middle:[{kind:`investigation`,at:`town`,present:[`npc3`],title:t(`Vægtskålen på vejerkontoret`,`The Scale Pan in the Weigh-House`),summary:t([`Vejerhuset ligger mørkt efter lukketid, men {npc3}, rådets skriver, arbejder sent i skriverstuen ved siden af og fører nøglebogen.`,`I {villain}s kontor ligger to ting, {villain} burde have brændt: et krøllet brev fra en pengeudlåner i hovedstaden og en seddel under vægtskålen med midnatsplanen.`,`Scenen giver heltene både motivet og tidspunktet.`],[`The weigh-house lies dark after hours, but {npc3}, the council clerk, is working late in the clerk’s room next door and keeps the key book.`,`In {villain}’s office lie two things {villain} should have burnt: a crumpled letter from a moneylender in the capital, and a slip under the scale pan with the midnight plan.`,`The scene gives the heroes both the motive and the hour.`]),readAloud:t([`Vejerkontoret lugter af messing og lampeolie, og på disken står en stor vægt med to blanke skåle.`,`Lodderne står på en lige række fra det største til det mindste, og papirerne på skrivepulten ligger i stakke med præcis samme afstand imellem.`,`Kun papirkurven under pulten er fuld, og øverst ligger et krøllet brev med et fremmed segl.`],[`The weigh-house office smells of brass and lamp oil, and on the counter stands a great balance with two bright pans.`,`The weights stand in a straight row from the largest to the smallest, and the papers on the desk lie in stacks exactly the same distance apart.`,`Only the wastepaper basket under the desk is full, and on top lies a crumpled letter with an unfamiliar seal.`]),details:[t(`Brevet er fra en pengeudlåner i hovedstaden: Hele beløbet forfalder ved nymåne, og ellers sender udlåneren nogen efter det. Under den ene vægtskål ligger en lille seddel med tal i {villain}s pertentlige håndskrift: bagkammeret i {place}, 400 præget, og ved midnat værkstedet, under gulvet ved essen.`,`The letter is from a moneylender in the capital: the full sum falls due at the new moon, or the lender will send someone for it. Under one scale pan lies a small slip of paper with figures in {villain}’s fussy hand: the back chamber in {place}, 400 struck, and at midnight the workshop, under the floor by the forge.`),t(`{npc3} ved, at {villain} kvitterede for nøglen til pengeskabet for tre måneder siden og aldrig har afleveret den, men er bange for at miste sin plads. Nøglebogen ligger i skriverstuen.`,`{npc3} knows that {villain} signed for the strongbox key three months ago and never returned it, but is afraid of losing their post. The key book lies in the clerk’s room.`),t(`Kommer heltene i løbet af de første to timer, er {villain} her selv og lukker kontoret: Ærmerne lugter af trækul og varmt bly, og fingerspidserne er fulde af små, friske brandsår. Bagefter går {villain} ud mod {place} for at smelte de sidste falske mønter om (første tik).`,`If the heroes come within the first two hours, {villain} is here in person, closing the office: their sleeves smell of charcoal and hot lead, and their fingertips are covered in small, fresh burns. Afterwards {villain} heads out to {place} to melt down the last false coins (the first tick).`)],checks:[n(`Charisma (Persuasion)`,`medium`,t(`{npc3} viser nøglebogen og lukker heltene ind på kontoret med rådets reservenøgle; skriveren vil vidne, hvis møntinspektøren spørger.`,`{npc3} shows the key book and lets the heroes into the office with the council’s spare key; the clerk will testify if the assayer asks.`),t(`{npc3} vil ikke blande sig, og heltene må dirke kontordøren op selv; det koster en halv time, og skriveren har set dem.`,`{npc3} will not get involved, and the heroes must pick the office lock themselves; it costs half an hour, and the clerk has seen them.`)),n(`Intelligence (Investigation)`,`medium`,t(`Heltene lægger mærke til, at den ene vægtskål ikke ligger helt plant, og finder sedlen under den.`,`The heroes notice that one scale pan does not sit quite level and find the slip beneath it.`),t(`Heltene finder kun brevet; sedlen dukker først op, da de har vendt hele kontoret, og så er der gået en halv time.`,`The heroes find only the letter; the slip turns up only after they have turned the whole office over, and by then half an hour has gone.`))],fight:!1,alternatives:[t(`Følg {villain}, når kontoret lukker: Vejen ud mod {place} er mørk, og {villain} ser sig ikke tilbage.`,`Follow {villain} when the office closes: the road out to {place} is dark, and {villain} does not look back.`),t(`Lad {npc1} holde {villain} hen med snak i kroen, mens heltene ransager kontoret.`,`Have {npc1} keep {villain} talking at the inn while the heroes search the office.`)],dmNotes:t(`Læg vægt på {villain}s orden: Alt på kontoret står lige, undtagen det, {villain} vil skjule. Spillere, der lægger mærke til det ene, der er i uorden, skal belønnes.`,`Play up {villain}’s tidiness: everything in the office stands straight except what {villain} wants hidden. Reward players who notice the one thing out of place.`)},{kind:`chase`,at:`town`,present:[`villain`],title:t(`Det forseglede værksted`,`The Sealed Workshop`),summary:t([`Ved midnat kommer {villain} med en blændlygte til {npc2}s værksted, bryder vagtens forsegling og gemmer det ene møntstempel under gulvbrædderne ved essen.`,`Heltene kan ligge på lur og se det ske, grave stemplet op bagefter eller følge {villain}s lygte gennem de mørke gader tilbage mod {place}.`,`Finder møntinspektøren stemplet dér ved daggry, og har heltene ingen presse at vise frem, bliver {npc2} dømt.`],[`At midnight {villain} comes to {npc2}’s workshop with a hooded lantern, breaks the watch’s seal and hides one of the dies under the floorboards by the forge.`,`The heroes can lie in wait and watch it happen, dig the die up afterwards, or follow {villain}’s lantern through the dark streets back toward {place}.`,`If the assayer finds the die there at dawn and the heroes have no press to show, {npc2} is condemned.`]),readAloud:t([`Gaden foran guldsmedens værksted er tom, og vagtens voksforsegling lyser rødt på døren i månelyset.`,`Skodderne er lukkede, og fra smøgen bag huset kommer lyden af forsigtige skridt.`,`En smal stribe lys glider hen over brostenene og slukker igen.`],[`The street in front of the goldsmith’s workshop is empty, and the watch’s wax seal shows red on the door in the moonlight.`,`The shutters are closed, and from the alley behind the house comes the sound of careful footsteps.`,`A thin strip of light slides across the cobbles and goes out again.`]),details:[t(`Kommer heltene efter midnat (andet tik), er forseglingen brudt, og der skinner lys gennem skodderne, eller også er {villain} netop gået. Stemplet ligger under et løst gulvbræt ved essen, pakket ind i en olieklud.`,`If the heroes come after midnight (the second tick), the seal is broken and light shows through the shutters, or {villain} has only just left. The die lies under a loose floorboard by the forge, wrapped in an oilcloth.`),t(`Viser heltene sig, mens {villain} er derinde, råber {villain} på vagten og anklager dem for at bryde forseglingen; i opstandelsen smutter {villain} ud ad bagvejen og mod {place}. En vejermester har byens ord, det har heltene ikke.`,`If the heroes show themselves while {villain} is inside, {villain} shouts for the watch and accuses them of breaking the seal; in the uproar {villain} slips out the back and away toward {place}. The town trusts a weigh-master’s word over the heroes’.`),t(`Fra værkstedet går {villain} direkte tilbage til {place} for at slå pressen i stykker før daggry. Den, der følger efter uset, ser vejen forbi vagterne ved indgangen og hen til døren til bagkammeret.`,`From the workshop {villain} goes straight back to {place} to break up the press before dawn. Whoever follows unseen learns the way past the guards at the entrance and on to the door of the back chamber.`)],checks:[n(`Dexterity (Stealth)`,`medium`,t(`Heltene følger {villain}s lygte gennem gaderne og ud ad vejen uden at blive set, helt til indgangen til {place}.`,`The heroes follow {villain}’s lantern through the streets and out along the road without being seen, all the way to the entrance of {place}.`),t(`{villain} hører noget og slukker lygten; heltene mister sporet i gaderne, men ved, at vejen fører mod {place}.`,`{villain} hears something and puts out the lantern; the heroes lose the trail in the streets, but know the road leads toward {place}.`)),n(`Intelligence (Investigation)`,`easy`,t(`Heltene finder det løse gulvbræt ved essen og stemplet i oliekluden under det.`,`The heroes find the loose floorboard by the forge and the die in its oilcloth beneath.`),t(`Heltene river halvdelen af gulvet op, før de finder stemplet; det tager en halv time, og larmen vækker naboerne.`,`The heroes tear up half the floor before they find the die; it takes half an hour, and the noise wakes the neighbours.`))],fight:!1,alternatives:[t(`Tag stemplet, og læg en sten i kluden i stedet: Ved daggry fører {villain} møntinspektøren hen til et gulvbræt med en sten under, foran hele byen.`,`Take the die and leave a stone in the cloth instead: at dawn {villain} leads the assayer to a floorboard with a stone under it, in front of the whole town.`),t(`Gå ikke til værkstedet, men til {place}: Ved midnat er {villain} væk fra pressen, og kun vagterne er tilbage.`,`Skip the workshop and go to {place}: at midnight {villain} is away from the press, and only the guards are left.`)],dmNotes:t(`Midnat er eventyrets drejepunkt. Spørg spillerne, hvor de er, når klokken slår tolv, og lad {villain}s plan ske dér, hvor de ikke er.`,`Midnight is the turning point of the adventure. Ask the players where they are when the clock strikes twelve, and let {villain}’s plan happen wherever they are not.`)},{kind:`combat`,at:`site`,present:[],title:t(`Blydråberne ved indgangen`,`Lead Drops at the Entrance`),summary:t([`Lige inden for indgangen til {place} er gulvet fuldt af små dråber størknet bly, og den sure lugt af varmt metal hænger i gangene.`,`Efter det første tik har {villain} sat {foe} til at vogte vejen ind, og de står mellem heltene og bagkammeret.`,`Dybere inde fører et spor af kulstøv og en tabt falsk mønt hen til en svær dør med en ny slå på indersiden.`],[`Just inside the entrance of {place} the floor is spattered with little drops of hardened lead, and the sour smell of hot metal hangs in the passages.`,`After the first tick {villain} has set {foe} to guard the way in, and they stand between the heroes and the back chamber.`,`Deeper in, a trail of charcoal dust and a dropped false coin lead to a heavy door with a new bolt on the inside.`]),readAloud:t([`Røgen fra {place} lugter surt af varmt bly og trækul og hænger lavt over jorden.`,`Lige inden for indgangen glimter små, grå dråber på gulvet som størknede tårer, og tre tomme kulsække ligger i en bunke.`,`Længere inde blafrer et lys, og noget bevæger sig foran det.`],[`The smoke from {place} has the sour smell of hot lead and charcoal and hangs low over the ground.`,`Just inside the entrance small grey drops glint on the floor like frozen tears, and three empty charcoal sacks lie in a heap.`,`Further in a light flickers, and something moves in front of it.`]),details:[t(`Vagterne her er {foe}, som {villain} har sat til at vogte vejen ind; de angriber alt, der kommer uden {villain}. Følger heltene lige i hælene på {villain}, tøver vagterne et øjeblik, fordi de tror, det er vejermesteren, der kommer tilbage.`,`The guards here are {foe} that {villain} has set to watch the way in; they attack anything that comes without {villain}. If the heroes follow close behind {villain}, the guards hesitate for a moment, thinking it is the weigh-master coming back.`),t(`De tomme kulsække er de tre, kulhandleren solgte til vejermesterens karl. Kulstøvet fører videre ind, og midt i det ligger en tabt falsk mønt med dobbeltprægning på kronen.`,`The empty charcoal sacks are the three the charcoal seller sold to the weigh-master’s hired man. The charcoal dust leads on inward, and in the middle of it lies a dropped false coin with the double strike on its crown.`),t(`Larm ved indgangen kan høres i bagkammeret. Er {villain} i {place} og hører kamp, begynder {villain} at pakke regnebogen og stemplerne sammen, og heltene har kun få minutter.`,`Noise at the entrance can be heard in the back chamber. If {villain} is in {place} and hears fighting, {villain} starts packing up the tally book and the dies, and the heroes have only minutes.`)],checks:[n(`Dexterity (Stealth)`,`medium`,t(`Heltene kommer tæt på vagterne uden at blive set og kan vælge, hvor kampen skal stå, eller smutte forbi.`,`The heroes get close to the guards unseen and can choose where the fight happens, or slip past.`),t(`En sten triller, og vagterne er klar; kampen begynder ved indgangen, og larmen bærer ind til bagkammeret.`,`A stone rolls and the guards are ready; the fight starts at the entrance, and the noise carries to the back chamber.`)),n(`Charisma (Deception)`,`hard`,t(`Heltene får vagterne til at tro, at de kommer med bud fra vejermesteren, og bliver lukket ind.`,`The heroes convince the guards that they bring word from the weigh-master and are let through.`),t(`Vagterne gennemskuer det og slår alarm; kampen begynder, og {boss} ved, at heltene kommer.`,`The guards see through it and raise the alarm; the fight starts, and {boss} knows the heroes are coming.`))],fight:!0,alternatives:[t(`Gå ind ad den vej, røgen kommer ud: Hvor røgen siver op mellem stenene, er der en sprække ned til bagkammeret, som en smidig helt kan kravle igennem og trække slåen fra indefra.`,`Go in the way the smoke comes out: where it seeps up between the stones there is a crack down to the back chamber that a nimble hero can crawl through, to draw the bolt from the inside.`),t(`Vent, til {villain} kommer tilbage fra værkstedet, og følg lige i hælene på {villain}: Vagterne tøver ved synet af vejermesterens lygte.`,`Wait until {villain} comes back from the workshop and follow close behind: the guards hesitate at the sight of the weigh-master’s lantern.`)],dmNotes:t(`Lad blydråberne og kulsækkene bekræfte det, spillerne har hørt i byen; det giver dem ro til at tage kampen. Husk, at {villain} kan høre larmen, hvis {villain} er derinde.`,`Let the lead drops and the charcoal sacks confirm what the players heard in town, so they go into the fight with confidence. Remember that {villain} can hear the noise if {villain} is inside.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:t(`Bagkammeret med møntpressen`,`The Back Chamber with the Coin Press`),summary:t([`I bagkammeret står {villain}s møntpresse ved en glødende smeltedigel, og på en bænk ligger regnebogen over hver eneste falsk mønt.`,`{boss} vogter kammeret for {villain}, og efter midnat er {villain} her selv igen for at slå pressen i stykker og køre den væk før daggry.`,`Heltene skal tage pressen eller begge stempler, og helst regnebogen, og nå frem til møntinspektøren ved daggry.`],[`In the back chamber {villain}’s coin press stands by a glowing melting pot, and on a bench lies the tally book of every false coin.`,`{boss} guards the chamber for {villain}, and after midnight {villain} is back in person to break up the press and cart it away before dawn.`,`The heroes must seize the press or both dies, and the tally book if they can, and bring them before the assayer at dawn.`]),readAloud:t([`Kammeret er varmt som en smedje, og en digel med flydende bly gløder rødt i en lille ovn af sten.`,`Møntpressen står halvt skilt ad, og dens tunge dele ligger på en vogn ved døren; på en bænk ligger en bog, opslået ved lange, pæne kolonner af tal.`,`Ved pressen står {villain} i skjorteærmer med en hammer i hånden, og bag diglen rører {boss} sig.`],[`The chamber is as hot as a forge, and a pot of molten lead glows red in a small stone furnace.`,`The coin press stands half taken apart, its heavy pieces loaded on a cart by the door; on a bench lies a book, open at long, neat columns of figures.`,`At the press stands {villain} in shirtsleeves, hammer in hand, and behind the melting pot {boss} stirs.`]),details:[t(`{boss} og nogle {foe} vogter kammeret for {villain}, der har betalt dem i det falske sølv. {villain} kæmper ikke selv, men prøver at redde regnebogen og stemplet og slippe ud, mens {boss} holder heltene hen.`,`{boss} and some {foe} guard the chamber for {villain}, who has paid them in the false silver. {villain} does not fight, but tries to save the tally book and the die and get out while {boss} holds the heroes off.`),t(`Døren har en ny slå på indersiden, så den, der vil ind, må få nogen derinde til at åbne, bryde døren op eller finde en anden vej. Efter midnat ligger det ene stempel under {npc2}s gulv, og det andet er her; før midnat er begge her, og {villain} er ved at pakke det ene ind i en olieklud.`,`The door has a new bolt on the inside, so anyone who wants in must get someone inside to open it, break the door down or find another way. After midnight one die lies under {npc2}’s floor and the other is here; before midnight both are here, and {villain} is wrapping one of them in an oilcloth.`),t(`Regnebogen er beviset på det hele: Hver mønt står i den med dato og vægt, og {villain} kan ikke få sig selv til at brænde den. Ved daggry skal heltene stå foran møntinspektøren med pressen eller begge stempler; ligger det ene stadig under {npc2}s gulv, bør de også grave det op før ransagningen.`,`The tally book proves everything: every coin is in it with date and weight, and {villain} cannot bear to burn it. At dawn the heroes must stand before the assayer with the press or both dies; if one still lies under {npc2}’s floor, they should dig it up before the search as well.`)],checks:[n(`Dexterity (Sleight of Hand)`,`medium`,t(`En helt snupper regnebogen og stemplet fra bænken, mens {boss} kæmper med de andre.`,`One hero snatches the tally book and the die from the bench while {boss} fights the others.`),t(`{villain} når at feje stemplet ned i diglen med flydende bly; det smelter ikke, men det koster en runde og en tang at fiske det op.`,`{villain} manages to sweep the die into the pot of molten lead; it does not melt, but it takes a round and a pair of tongs to fish it out.`)),n(`Charisma (Persuasion)`,`medium`,t(`Heltene minder {villain} om pengeudlåneren: I kongens fængsel er {villain} i sikkerhed, ude i verden er {villain} det ikke. {villain} giver op og prøver at kalde {boss} tilbage.`,`The heroes remind {villain} of the moneylender: in the king’s prison {villain} is safe, out in the world {villain} is not. {villain} gives up and tries to call {boss} off.`),t(`{villain} griber regnebogen og løber mod døren, mens {boss} spærrer vejen for heltene.`,`{villain} grabs the tally book and runs for the door while {boss} blocks the heroes’ way.`))],fight:!0,alternatives:[t(`Vis {boss}, at betalingen er bly: Kan {boss} overhovedet tales til rette, vender vagterne sig mod {villain}, der så beder heltene om beskyttelse.`,`Show {boss} that the pay is lead: if {boss} can be reasoned with at all, the guards turn on {villain}, who then begs the heroes for protection.`),t(`Kom ved midnat, mens {villain} er i byen: Så er der kun {boss} og vagterne at klare, men {villain} kommer tilbage før daggry og går lige ind i heltene ved pressen.`,`Come at midnight while {villain} is in town: then there are only {boss} and the guards to deal with, but {villain} comes back before dawn and walks straight into the heroes at the press.`)],dmNotes:t(`Daggry er målet, ikke kampen. Sig, hvor mange timer der er tilbage, når heltene står ved pressen, og lad dem mærke, at en jernpresse er tung at bære hjem; stemplerne og bogen kan være i en lomme.`,`Dawn is the goal, not the fight. Say how many hours are left when the heroes stand over the press, and let them feel how heavy an iron press is to carry home; the dies and the book fit in a pocket.`)}}},i=e=>Array.isArray(e)?e.join(` `):e,a=(e,t)=>({da:i(e),en:i(t)}),o=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),s={"rescue-child-for-child":{opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc3`],title:a(`Byfogeden ved midnat`,`The Reeve at Midnight`),summary:a([`Ved midnat kommer {npc1}, byfogeden, alene til heltene med et krav i hånden: {villain} har taget {npc1}s barn, {npc2}, og vil kun give {npc2} tilbage, hvis {villain}s eget barn bliver sat fri, før fangevognen kører ved daggry.`,`{npc1} vil ikke bøje loven, men beder heltene finde {npc2} i al hemmelighed. Scenen giver heltene skurken, fristen og de første spor.`],[`At midnight {npc1}, the reeve, comes to the heroes alone with a demand in hand: {villain} has taken {npc1}’s child, {npc2}, and will only give {npc2} back if {villain}’s own child is set free before the prison cart leaves at dawn.`,`{npc1} will not bend the law but asks the heroes to find {npc2} in secret. The scene gives the heroes the culprit, the deadline and their first leads.`]),readAloud:a([`Krostuen er tom, og ilden er brændt ned til gløder, da døren går op, og en skikkelse med en mørk kappe over nattøjet træder ind.`,`I den ene hånd holder skikkelsen et ark tykt papir, og rettens segl skinner igennem fra bagsiden.`,`Ude på gaden råber vægteren midnat.`],[`The taproom is empty and the fire has burned down to embers when the door opens and a figure in a dark cloak thrown over nightclothes steps inside.`,`In one hand the figure holds a sheet of heavy paper, the court’s seal showing through from the other side.`,`Out in the street, the watch calls midnight.`]),details:[a(`Kravet er skrevet på bagsiden af en udskrift af dommen over {villain}s barn, og den eneste anden udskrift fik den dømtes familie. {npc1} ved med det samme, hvem der har skrevet det, og har ikke fortalt det til nogen, heller ikke til vagten.`,`The demand is written on the back of a copy of the sentence passed on {villain}’s child, and the only other copy went to the convict’s family. {npc1} knows at once who wrote it and has told no one, not even the watch.`),a(`{npc3}, vægteren ved porten, har vagt i nat. {npc3} så {npc2} gå ud ved skumring sammen med {villain}, og {npc2} råbte, at de skulle hente en syg.`,`{npc3}, the gate watchman, is on duty tonight. {npc3} saw {npc2} leave at dusk with {villain}, and {npc2} called out that they were going to fetch someone who was sick.`),a(`Presset indrømmer {npc1}, at dommen hviler på ét eneste vidne. {npc1} sætter ingen fri ved daggry, men kan skrive et forseglet brev om at tage sagen op igen, hvis {npc2} kommer levende hjem, og {villain} melder sig.`,`Pressed, {npc1} admits that the sentence rests on a single witness. {npc1} will set no one free at dawn but can write a sealed letter promising a new hearing if {npc2} comes home alive and {villain} surrenders.`)],checks:[o(`Charisma (Persuasion)`,`medium`,a(`{npc1} skriver og forsegler brevet om en ny sag. Det er det stærkeste, heltene kan lægge foran {villain}.`,`{npc1} writes and seals the letter promising a new hearing. It is the strongest thing the heroes can lay before {villain}.`),a(`{npc1} vil ikke skrive noget under, mens loven bliver presset. Heltene har kun deres eget ord at forhandle med, når de møder {villain}.`,`{npc1} will not sign anything under duress. The heroes have only their own word to bargain with when they meet {villain}.`)),o(`Wisdom (Insight)`,`easy`,a(`Heltene ser, at kravet er skrevet af en desperat forælder og ikke af en morder: Der står vand og lys, og håndskriften ryster. {villain} kan tales til fornuft.`,`The heroes see that the demand was written by a desperate parent, not a killer: it promises water and light, and the handwriting is shaky. {villain} can be talked round.`),a(`Heltene læser kravet som en kold trussel. Når de møder {villain}, kommer de med trukne våben, og det gør {villain} mere bange end villig.`,`The heroes read the demand as a cold threat. When they meet {villain}, they come with weapons drawn, which leaves {villain} more frightened than willing.`))],fight:!1,alternatives:[a(`Gå direkte til porten, og få {npc3} til at vise stien, som {villain} og {npc2} tog mod {place}.`,`Go straight to the gate and have {npc3} point out the path {villain} and {npc2} took toward {place}.`),a(`Gå først til {villain}s hus: Det står tomt, og det, der ligger på bordet, siger mere, end {npc1} kan.`,`Go to {villain}’s house first: it stands empty, and what lies on the table says more than {npc1} can.`)],dmNotes:a(`Spil {npc1} som en, der er knust, men ikke vil vise det: Byfogeden taler om loven, men hænderne ryster. Jo bedre spillerne forstår begge forældre her, jo bedre virker forhandlingen ved jerndøren.`,`Play {npc1} as someone crushed but refusing to show it: the reeve talks about the law, but their hands shake. The better the players understand both parents here, the better the bargaining at the iron door will work.`)},middle:[{kind:`investigation`,at:`town`,present:[],title:a(`Den redte seng`,`The Made Bed`),summary:a([`{villain}s hus står tomt og koldt. I barnets kammer er sengen redt som til en hjemkomst, og på bordet ligger en plan over fangevognens rute og et brev, der aldrig blev sendt.`,`Her finder heltene ud af, hvor {npc2} sidder, og hvor {villain} vil være ved daggry.`],[`{villain}’s house stands empty and cold. In the child’s room the bed is made as if for a homecoming, and on the table lie a plan of the prison cart’s route and a letter that was never sent.`,`Here the heroes learn where {npc2} is held and where {villain} means to be at dawn.`]),readAloud:a([`Døren er ikke låst, og huset er koldt; ved det slukkede ildsted hænger en tom lampekrog.`,`I det lille kammer bagest er sengen redt med rene lagner, og en sammenfoldet skjorte ligger på hovedpuden.`,`På køkkenbordet ligger en tegning af landevejen og et brev, hvor blækket er løbet ud i runde pletter.`],[`The door is unlocked and the house is cold; by the dead hearth hangs an empty lamp hook.`,`In the small room at the back the bed is made with clean sheets, and a folded shirt lies on the pillow.`,`On the kitchen table lie a drawing of the high road and a letter whose ink has run in round blots.`]),details:[a(`Tegningen viser fangevognens rute med et kryds ved et sving, hvor vognen må sætte farten ned. Dér vil {villain} stå skjult ved daggry og se, om barnet sidder i vognen.`,`The drawing shows the prison cart’s route, with a cross at a bend where the cart must slow down. That is where {villain} means to hide at dawn and watch whether the child is on the cart.`),a(`Brevet til {npc1} siger, at {npc2} sidder i det gamle kammer bag jerndøren i {place}, tredje gang til venstre efter trappen, og hører op midt i en sætning. Den tomme lampekrog betyder, at {villain} har taget husets lampe med.`,`The letter to {npc1} says that {npc2} is in the old chamber behind the iron door in {place}, the third passage on the left after the stairs, and breaks off in the middle of a sentence. The empty lamp hook means {villain} has taken the house lamp along.`),a(`Jernkræmmeren over for huset vågner ved heltenes banken og husker, at {villain} i går købte en svær hængelås og en lampe og betalte med sin vielsesring. Ringen ligger stadig i kræmmerens skuffe.`,`The ironmonger across the lane wakes at the heroes’ knocking and remembers that yesterday {villain} bought a heavy padlock and a lamp and paid with a wedding ring. The ring is still in the ironmonger’s drawer.`)],checks:[o(`Intelligence (Investigation)`,`easy`,a(`Heltene finder brevet under tegningen og ved nu præcis, hvilken gang i {place} der fører til {npc2}. Inde i {place} slipper de for at lede.`,`The heroes find the letter under the drawing and now know exactly which passage in {place} leads to {npc2}. Inside {place} they will not have to search.`),a(`Heltene tager kun tegningen, og brevet glider ned bag bordet. De må finde vejen inde i {place} ad andre spor, og det koster tid.`,`The heroes take only the drawing, and the letter slips down behind the table. They must find the way inside {place} by other signs, and that costs time.`)),o(`Wisdom (Insight)`,`medium`,a(`Den redte seng, det afbrudte brev og den tomme lampekrog siger det samme: {villain} fortryder allerede halvt og vil tilbage til {npc2}, før natten er omme. Medfølelse vil virke bedre end trusler.`,`The made bed, the unfinished letter and the empty lamp hook all say the same thing: {villain} already half regrets it and means to go back to {npc2} before the night is out. Compassion will work better than threats.`),a(`Heltene ser kun en kidnappers forberedelser, og {villain}s lys inde i {place} kommer bag på dem.`,`The heroes see only a kidnapper’s preparations, and {villain}’s light inside {place} takes them by surprise.`))],fight:!1,alternatives:[a(`Spring huset over, og følg sporet fra porten: Det er hurtigere, men inde i {place} må heltene selv finde kammeret.`,`Skip the house and follow the trail from the gate: it is quicker, but inside {place} the heroes must find the chamber on their own.`),a(`Køb vielsesringen tilbage hos jernkræmmeren; lagt i {villain}s hånd siger den mere end noget løfte.`,`Buy the wedding ring back from the ironmonger; placed in {villain}’s hand, it says more than any promise.`)],dmNotes:a(`Lad den redte seng gøre arbejdet: {villain} er en forælder og ikke et uhyre. Spørger spillerne, hvorfor huset ikke er låst, så svar, at {villain} ikke regner med at komme tilbage.`,`Let the made bed do the work: {villain} is a parent, not a monster. If the players ask why the house is unlocked, answer that {villain} does not expect to come back.`)},{kind:`exploration`,at:`site`,present:[],title:a(`Tørklædet i indgangen`,`The Scarf at the Entrance`),summary:a([`Lige inden for indgangen til {place} går to sæt friske fodspor ind i støvet, men kun ét kommer ud igen, og på stenen ligger {npc2}s tørklæde.`,`Længere inde har {npc2} lagt trævler af det ved hver korsvej, mens {villain} gik forrest, og det spor fører lige mod kammeret.`],[`Just inside the entrance of {place}, two sets of fresh footprints go into the dust but only one comes back out, and {npc2}’s scarf lies on the stone.`,`Further in, {npc2} left threads from it at every crossing while {villain} led the way, and that trail leads straight toward the chamber.`]),readAloud:a([`Indgangen er en mørk åbning, og lige inden for ligger et tykt lag støv, fuldt af fodspor: store støvler og mindre, lettere fødder side om side.`,`På stenen ved væggen ligger et tørklæde krøllet sammen med en flænge i den ene ende.`,`Luften derinde er kold og lugter af våd sten og svagt af lampeolie.`],[`The entrance is a dark opening, and just inside lies a thick layer of dust full of footprints: big boots and smaller, lighter feet side by side.`,`On the stone by the wall lies a crumpled scarf with a tear at one end.`,`The air inside is cold and smells of wet stone and, faintly, of lamp oil.`]),details:[a(`To sæt spor går ind, og kun støvlesporene kommer ud igen. Efter 4 timer går et tredje sæt af de samme støvler ind oven i de andre og kommer ikke ud: {villain} er vendt tilbage med en ny lampe.`,`Two sets of prints go in, and only the boot prints come out again. After 4 hours a third set from the same boots goes in over the others and does not come out: {villain} has come back with a fresh lamp.`),a(`Ved hver korsvej ligger en trævl fra tørklædet, bundet om en sten eller fanget på et søm, så den peger den vej, {villain} gik. {npc2} er snarrådig og har ikke opgivet.`,`At every crossing lies a thread from the scarf, tied round a stone or caught on a nail, pointing the way {villain} went. {npc2} is quick-witted and has not given up.`),a(`Efter 2 timer lyder en fjern, regelmæssig dunken dybt inde fra {place}, hvor {boss} er gået i gang med døren til kammeret.`,`After 2 hours a distant, steady pounding sounds from deep inside {place}, where {boss} has started on the chamber door.`)],checks:[o(`Wisdom (Perception)`,`medium`,a(`Heltene ser trævlerne ved hver korsvej og følger dem uden at tøve. De når trappen hurtigt og uden omveje.`,`The heroes spot the threads at every crossing and follow them without hesitating. They reach the stairs quickly, with no detours.`),a(`En flok {foe} er gået hen over sporet, og trævlen ved den første korsvej er væk. Heltene går forkert og mister en halv time, før de finder sporet igen.`,`A pack of {foe} have passed over the trail, and the thread at the first crossing is gone. The heroes take a wrong turn and lose half an hour before they find the trail again.`)),o(`Wisdom (Survival)`,`easy`,a(`Sporene viser, at {npc2} gik frivilligt ved siden af {villain} og ikke blev slæbt. Er der et tredje sæt støvlespor, ved heltene, at {villain} er derinde nu.`,`The tracks show that {npc2} walked willingly beside {villain} and was not dragged. If there is a third set of boot prints, the heroes know that {villain} is inside now.`),a(`Støvet er for optrampet til at læse mere end antallet af spor. Heltene ved kun, at den ene af de to aldrig kom ud.`,`The dust is too trampled to read more than the number of tracks. The heroes know only that one of the two never came out.`))],fight:!1,alternatives:[a(`Har heltene brevet fra {villain}s bord, kan de gå efter beskrivelsen og lade trævlerne ligge.`,`If the heroes have the letter from {villain}’s table, they can follow its directions and leave the threads where they lie.`),a(`Efter 2 timer kan heltene gå efter den fjerne lyd; den fører lige til jerndøren, men også lige til {boss}.`,`After 2 hours the heroes can follow the distant sound; it leads straight to the iron door, but also straight to {boss}.`)],dmNotes:a(`Trævlerne er {npc2}s stemme, før heltene møder {npc2}: Beskriv hver enkelt, og lad sporet bryde én gang, så spillerne mærker, hvor tæt {npc2} var på at gå tabt.`,`The threads are {npc2}’s voice before the heroes meet {npc2}: describe each one, and let the trail break once, so the players feel how close {npc2} came to being lost.`)},{kind:`combat`,at:`site`,present:[],title:a(`Tredje gang til venstre`,`The Third Passage on the Left`),summary:a([`For foden af trappen deler gangene sig, og her strejfer en flok {foe} rundt. Heltene skal forbi dem og ind i tredje gang til venstre, hvor friske dryp af lampeolie fører hen mod jerndøren.`,`Hver kamp og hver omvej her tager tid fra {npc2}.`],[`At the foot of the stairs the passages divide, and a pack of {foe} roam here. The heroes must get past them into the third passage on the left, where fresh drips of lamp oil lead toward the iron door.`,`Every fight and every detour here takes time from {npc2}.`]),readAloud:a([`Trappen ender i en lav sal, hvor fem gange åbner sig som mørke munde.`,`Midt på gulvet ligger en væltet stabel sten, og støvet omkring den er fuldt af spor.`,`Fra gangene til højre kommer en lyd af bevægelse, og så bliver der pludselig helt stille.`],[`The stairs end in a low hall where five passages open like dark mouths.`,`In the middle of the floor lies a toppled pile of stones, and the dust around it is churned with tracks.`,`From the passages on the right comes a sound of movement, then sudden silence.`]),details:[a(`En flok {foe} holder til i gangene til højre. De hører til i {place} og tjener ingen; {villain} slap forbi dem ved skumring med lampe og held.`,`A pack of {foe} keep to the passages on the right. They belong to {place} and serve no one; {villain} got past them at dusk with a lamp and luck.`),a(`Efter 4 timer bærer {npc2}s råb gennem gangene, og flokken bliver urolig og søger mod lyden. Så står den mellem heltene og tredje gang til venstre, og kampen kan ikke undgås.`,`After 4 hours {npc2}’s shouts carry through the passages, and the pack grows restless and moves toward the sound. Then it stands between the heroes and the third passage on the left, and the fight cannot be avoided.`),a(`I tredje gang til venstre begynder friske dryp af lampeolie, der fører hen mod en gammel jerndør med en blank, ny hængelås. Efter 4 timer bevæger et andet lys sig derinde: {villain}s.`,`In the third passage on the left fresh drips of lamp oil begin, leading toward an old iron door with a shiny new padlock. After 4 hours a second light moves down there: {villain}’s.`)],checks:[o(`Dexterity (Stealth)`,`medium`,a(`Heltene glider langs væggen ind i tredje gang til venstre uden at blive set. Flokken er der stadig, når heltene skal ud igen med {npc2}.`,`The heroes slip along the wall into the third passage on the left unseen. The pack is still there when the heroes come back out with {npc2}.`),a(`En sten triller, og en flok {foe} vælter ud af gangene til højre. Kampen begynder midt i salen, og larmen bærer helt hen til jerndøren.`,`A stone rolls, and a pack of {foe} pour out of the passages on the right. The fight begins in the middle of the hall, and the noise carries all the way to the iron door.`)),o(`Wisdom (Perception)`,`easy`,a(`Heltene får øje på oliedryppene og ved, at de er på rette vej.`,`The heroes spot the oil drips and know they are on the right track.`),a(`I mørket tæller heltene galt og går ind i en anden gang. Det koster en halv time og måske et møde med {foe}, før de finder dryppene.`,`In the dark the heroes miscount and take another passage. It costs half an hour, and perhaps a run-in with {foe}, before they find the drips.`))],fight:!0,alternatives:[a(`Lok flokken væk med larm eller en kastet fakkel ned ad en af gangene til højre.`,`Lure the pack away with noise, or with a torch thrown down one of the passages on the right.`),a(`Vent på et stille øjeblik, og løb over salen samlet og på én gang.`,`Wait for a quiet moment and cross the hall together, all at once.`)],dmNotes:a(`Kampen her skal føles som en forsinkelse og ikke som et mål. Når den er ovre, så lad heltene høre slagene mod døren eller {npc2}s råb, så de ved, at de er tæt på.`,`The fight here should feel like a delay, not a destination. When it is over, let the heroes hear the blows on the door or {npc2}’s shouts, so they know they are close.`)}],climax:{kind:`climax`,at:`site`,present:[`npc2`,`villain`],title:a(`Jerndøren`,`The Iron Door`),summary:a([`For enden af tredje gang til venstre står jerndøren med {villain}s nye hængelås, og {boss} har fundet den.`,`I de sidste timer før daggry kunne {villain} ikke bære, at {npc2} sad i mørket, og kom tilbage med en ny lampe, men fandt {boss} ved døren og har gemt sig i en niche lige ved siden af.`,`{boss} og en flok {foe} hører til i {place} og tjener ingen; de er lige så farlige for {villain} som for {npc2}.`],[`At the end of the third passage on the left stands the iron door with {villain}’s new padlock, and {boss} has found it.`,`In the last hours before dawn {villain} could not bear to leave {npc2} in the dark and came back with a fresh lamp, only to find {boss} at the door, and is now hiding in a niche close by.`,`{boss} and a pack of {foe} belong to {place} and serve no one; they are as dangerous to {villain} as to {npc2}.`]),readAloud:a([`Gangen ender ved en gammel jerndør med en blank, ny hængelås, og jernet omkring den er fuldt af friske ridser og buler.`,`Luften stinker af spildt lampeolie, og i en niche ved siden af står en skikkelse med en tildækket lampe, trykket ind mod stenen uden at røre sig.`,`Længere henne i mørket er noget tungt på vej tilbage.`],[`The passage ends at an old iron door with a shiny new padlock, the iron around it covered in fresh scratches and dents.`,`The air reeks of spilled lamp oil, and in a niche to one side a figure holding a shuttered lamp presses back against the stone and does not move.`,`Further along, in the dark, something heavy is coming back.`]),details:[a(`{villain} har nøglen i en snor om halsen og kan låse op på et øjeblik. Kommer heltene til døren før 4 timer, er {villain} her ikke endnu, men {villain}s lys dukker op i gangen bag dem, mens de arbejder.`,`{villain} has the key on a cord around their neck and can open the lock in a moment. If the heroes reach the door before 4 hours have passed, {villain} is not here yet, but {villain}’s light appears in the passage behind them while they work.`),a(`Bag døren sidder {npc2} med en spand vand og en lampe, der brænder ned. Efter 4 timer er lampen gået ud, og {npc2} råber i mørket; ved daggry giver døren efter for {boss}.`,`Behind the door sits {npc2} with a bucket of water and a lamp that is burning down. After 4 hours the lamp is out and {npc2} is shouting in the dark; at dawn the door gives way to {boss}.`),a(`Viser heltene {villain}, hvor tæt {boss} er på at komme igennem, eller lægger de {npc1}s forseglede brev eller vielsesringen i {villain}s hånd, giver {villain} dem nøglen og holder lampen for dem.`,`If the heroes show {villain} how close {boss} is to breaking through, or put {npc1}’s sealed letter or the wedding ring in {villain}’s hand, {villain} gives them the key and holds the lamp for them.`)],checks:[o(`Charisma (Persuasion)`,`medium`,a(`{villain} rækker nøglen frem med rystende hånd og hjælper med at få {npc2} ud. Med {villain}s tilståelse kan sagen mod {villain}s barn tages op igen.`,`{villain} holds out the key with a shaking hand and helps get {npc2} out. With {villain}’s confession, the case against {villain}’s child can be reopened.`),a(`{villain} klamrer sig til nøglen og prøver at slippe forbi heltene mod udgangen. Heltene må tage nøglen med magt eller bryde låsen op.`,`{villain} clutches the key and tries to slip past the heroes toward the way out. The heroes must take the key by force or break the lock.`)),o(`Strength (Athletics)`,`hard`,a(`Hængelåsens bøjle springer, og døren går op. {npc2} er fri, uanset hvad {villain} gør.`,`The padlock’s shackle snaps and the door swings open. {npc2} is free, whatever {villain} does.`),a(`Låsen holder, og larmen trækker en flok {foe} til fra de nærmeste gange. Heltene kan prøve igen, men nu midt i en kamp.`,`The lock holds, and the noise draws a pack of {foe} from the nearby passages. The heroes can try again, but now in the middle of a fight.`))],fight:!0,alternatives:[a(`Lok {boss} væk fra døren med {villain}s lampeolie: Et brændende spor ned ad en sidegang køber nogle minutter.`,`Lure {boss} away from the door with {villain}’s lamp oil: a burning trail down a side passage buys a few minutes.`),a(`Hold {boss} tilbage, mens {villain} låser op; {villain} kender vejen ud i mørket bedre end nogen anden.`,`Hold {boss} off while {villain} unlocks the door; {villain} knows the way out in the dark better than anyone.`)],dmNotes:a(`Gør {villain}s valg til scenens hjerte: {villain} kan løbe med nøglen eller låse døren op, og heltenes ord afgør det. Går kampen dårligt, så lad {villain} kaste nøglen til heltene; det er øjeblikket, hvor {villain} holder op med at være skurken.`,`Make {villain}’s choice the heart of the scene: {villain} can run with the key or open the door, and the heroes’ words decide which. If the fight goes badly, let {villain} throw the key to the heroes; that is the moment {villain} stops being the villain.`)}},"rescue-debt-diggers":{opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc3`],title:a(`Lænken om anklen`,`The Fetter on the Ankle`),summary:a([`Sen aften ved ildstedet hos {npc1}, {npc2}s nærmeste familie: {npc3} er sluppet ud af {place} med lænken stadig om anklen og fortæller, at skyldnerne arbejder i lænker under et loft, der slår revner, og at den sidste dør bliver brudt løs ved daggry.`,`{npc1} beder heltene bringe {npc2} hjem, og {npc3} tegner vejen ned i asken. Scenen giver heltene skurken, fristen og en vej ind.`],[`Late evening by the hearth of {npc1}, {npc2}’s next of kin: {npc3} has escaped from {place} with the fetter still on one ankle and tells how the debtors work in chains under a cracking ceiling, and that the last door will be torn loose at dawn.`,`{npc1} asks the heroes to bring {npc2} home, and {npc3} sketches the way down in the ashes. The scene gives the heroes the villain, the deadline and a way in.`]),readAloud:a([`Køkkenet er lille og varmt, og over ilden damper en gryde tynd suppe.`,`Ved ildstedet sidder en mager skikkelse svøbt i et tæppe og spiser, som om skålen kunne blive taget fra den; om den ene ankel sidder en jernlænke med et stykke knækket kæde.`,`På bordet ligger et sammenfoldet papir, tæt beskrevet med små, omhyggelige bogstaver.`],[`The kitchen is small and warm, and a pot of thin soup steams over the fire.`,`By the hearth sits a gaunt figure wrapped in a blanket, eating as if the bowl might be taken away; round one ankle is an iron fetter with a length of broken chain.`,`On the table lies a folded paper, closely covered in small, careful writing.`]),details:[a(`Papiret er {npc1}s afskrift af {npc2}s gældsbevis: 40 sølv med renter, og kost og logi trækkes fra lønnen. {npc1} har betalt renter i to måneder, og gælden er kun vokset.`,`The paper is {npc1}’s copy of {npc2}’s bond: 40 silver with interest, with board and lodging deducted from wages. {npc1} has paid interest for two months, and the debt has only grown.`),a(`Lænken om {npc3}s ankel er stemplet med {villain}s mærke, et lille vægtlod. {npc3} tegner trappen, de tre sale og den gamle afløbsgang, som vagterne har glemt, og som {npc3} selv kravlede ud ad.`,`The fetter on {npc3}’s ankle is stamped with {villain}’s mark, a small weight. {npc3} sketches the stair, the three halls and the old drain passage the guards have forgotten, the one {npc3} crawled out through.`),a(`Byen gemmer mere for den, der leder: På kroen praler en af {villain}s opsynsmænd af, at "dørene er solgt, og folkene er gratis", og på {villain}s kontor ligger køberens brev.`,`The town holds more for anyone who looks: at the inn one of {villain}’s overseers is boasting that "the doors are sold, and the workers come for free", and in {villain}’s office lies the buyer’s letter.`)],checks:[o(`Charisma (Persuasion)`,`medium`,a(`{npc3} tager med helt hen til indgangen og venter dér med tæpper og vand til dem, der kommer ud. Undervejs husker {npc3}, at afløbsgangen begynder under et jerngitter i et siderum før den indre trappe.`,`{npc3} comes along as far as the entrance and waits there with blankets and water for those who come out. On the way {npc3} remembers that the drain passage begins under an iron grating in a side room before the inner stair.`),a(`{npc3} er for bange til at forlade ildstedet. Skitsen i asken er alt, hvad heltene får, og afløbsgangens munding må de selv finde derinde.`,`{npc3} is too frightened to leave the hearth. The sketch in the ashes is all the heroes get, and they must find the mouth of the drain passage themselves.`)),o(`Intelligence (Investigation)`,`easy`,a(`Heltene ser gældsbeviset for det, det er: en fælde, hvor gælden aldrig kan betales af. Uden de underskrevne beviser har {villain} intet krav på nogen, og {npc3} har set {villain} bære dem i en taske.`,`The heroes see the bond for what it is: a trap, a debt that can never be paid off. Without the signed bonds {villain} has no claim on anyone, and {npc3} has seen {villain} carry them in a satchel.`),a(`Heltene ser kun en gæld, der skal betales. At beviserne er værd at tage, går først op for dem, når de ser {villain}s taske.`,`The heroes see only a debt that must be paid. That the bonds are worth taking only dawns on them when they see {villain}’s satchel.`))],fight:!1,alternatives:[a(`Kig ind på kroen på vejen ud: Et par krus til den pralende opsynsmand giver vagtskifterne og antallet af vagter ved trappen.`,`Stop at the inn on the way out: a few mugs for the boasting overseer buy the times of the guard changes and the number of guards on the stair.`),a(`Bryd ind på {villain}s kontor efter køberens brev; det beviser, at dørene er solgt på forhånd, og hjælper, når sagen kommer for retten.`,`Break into {villain}’s office for the buyer’s letter; it proves the doors were sold in advance and helps when the matter comes to court.`)],dmNotes:a(`Lad {npc3} give skyldnerne et ansigt: en gammel graver, der hoster, og den sang, holdet synger for at holde takten. Jo mere virkelige folkene dernede er, jo sværere bliver valget, hvis heltene ikke kan nå at få alle med.`,`Let {npc3} give the debtors a face: an old digger with a cough, the song the gang sings to keep time. The more real the people down there are, the harder the choice will be if the heroes cannot get everyone out.`)},middle:[{kind:`social`,at:`town`,present:[`villain`],title:a(`Teltet ved indgangen`,`The Tent at the Entrance`),summary:a([`Ved indgangen til {place} står {villain}s telt med en jernbeslået kiste og en lang række tomme lænker, og fakler brænder ved åbningen.`,`Her sidder {villain} over regnskabet med tasken på skødet, og her kan heltene lære vagterne at kende, høre, hvad der skal ske ved daggry, og komme ind, før vagten bliver fordoblet.`],[`At the entrance of {place} stands {villain}’s tent with an iron-bound chest and a long row of empty fetters, and torches burn at the opening.`,`Here {villain} sits over the accounts with the satchel on their lap, and here the heroes can size up the guards, learn what is to happen at dawn and get inside before the guard is doubled.`]),readAloud:a([`Fakler brænder på stænger foran en mørk åbning, og ved siden af står et stort telt, hvor lampelyset skinner gennem lærredet.`,`Langs teltvæggen ligger en række tomme lænker, lagt pænt ud som værktøj i en butik.`,`Fra åbningen kommer en svag, jævn hamren langt nede, og den holder aldrig op.`],[`Torches burn on poles before a dark opening, and beside it stands a large tent with lamplight glowing through the canvas.`,`Along the tent wall lies a row of empty fetters, laid out neatly like tools in a shop.`,`From the opening comes a faint, steady hammering far below, and it never stops.`]),details:[a(`Vagten ved teltet er en af {villain}s folk og keder sig. Lidt snak eller en mønt får vagten til at fortælle, at {villain} vil tage nøglerne og gældsbeviserne med ned, når den sidste dør skal brydes løs.`,`The guard at the tent is one of {villain}’s people and is bored. A little talk or a coin gets the guard to reveal that {villain} means to take the keys and the bonds down when the last door is torn loose.`),a(`{villain} går aldrig fra tasken med nøglerne og gældsbeviserne og har aldrig sat sine ben i salene. Efter 5 timer, når loftet styrter ned, går {villain} ned for første gang, bandende og med tasken under armen.`,`{villain} never lets go of the satchel with the keys and the bonds and has never set foot in the halls. After 5 hours, when the ceiling comes down, {villain} goes down for the first time, cursing, with the satchel under one arm.`),a(`Efter 2 timer opdager {villain}, at {npc3} er væk, og fordobler vagten ved trappen. Derefter brænder der flere fakler ved åbningen, og der bliver råbt ved hvert vagtskifte.`,`After 2 hours {villain} discovers that {npc3} is gone and doubles the guard on the stair. From then on more torches burn at the opening, and there is shouting at every change of guard.`)],checks:[o(`Charisma (Deception)`,`medium`,a(`Heltene bliver taget for køberens folk, der er kommet tidligt for at se på den store dør, og bliver vinket ind med en lygte og en opsynsmand som fører.`,`The heroes are taken for the buyer’s people, come early to look at the great door, and are waved inside with a lantern and an overseer to guide them.`),a(`{villain} vil se køberens brev, før nogen går ned. Heltene må trække sig og finde en anden vej ind, og vagten holder nu øje med fremmede.`,`{villain} wants to see the buyer’s letter before anyone goes down. The heroes must withdraw and find another way in, and the guard now watches for strangers.`)),o(`Dexterity (Stealth)`,`medium`,a(`Heltene glider forbi faklerne ved et vagtskifte og er inde, før nogen ser dem.`,`The heroes slip past the torches at a change of guard and are inside before anyone sees them.`),a(`En vagt får øje på en skygge og råber op. Heltene kommer ind, men vagten ved trappen er advaret og venter dem.`,`A guard glimpses a shadow and shouts. The heroes get inside, but the guard on the stair is warned and waiting.`))],fight:!1,alternatives:[a(`Vis {villain} et hvilket som helst papir med et segl: {villain} stoler mere på papir end på mennesker og læser det ikke grundigt i lampelyset.`,`Show {villain} any paper with a seal on it: {villain} trusts paper more than people and will not read it closely by lamplight.`),a(`Stjæl tasken nu, mens {villain} døser over regnskabet. Lykkes det, har heltene nøglerne og beviserne, men {villain} vækker hele lejren, så snart tabet bliver opdaget, og går alligevel ned for at redde døren.`,`Steal the satchel now, while {villain} dozes over the accounts. If it works, the heroes have the keys and the bonds, but {villain} rouses the whole camp the moment the loss is noticed and goes down all the same to save the door.`)],dmNotes:a(`{villain} er ingen kriger: Lad {villain} være let at narre med papir og svær at narre med ord. Det, heltene ser her, får de brug for senere: tasken, vagtskifterne og {villain}s skræk for mørket nedenunder.`,`{villain} is no fighter: let {villain} be easy to fool with paper and hard to fool with words. What the heroes see here they will need later: the satchel, the changes of guard and {villain}’s dread of the dark below.`)},{kind:`combat`,at:`site`,present:[],title:a(`Den indre trappe`,`The Inner Stair`),summary:a([`Inde i {place} løber et bredt, blankslidt slæbespor fra indgangen hen til en trappe, der fører ned mod den nederste sal, og trinene er ridset dybt af de tunge døre.`,`Øverst på trappen holder en opsynsmand vagt med nogle af {villain}s {foe}, og i opsynsmandens lomme ligger den arbejdsordre, der sætter alle skyldnerne ved den store dør. Her kommer det til kamp, hvis heltene ikke slipper forbi.`],[`Inside {place} a broad track worn smooth by dragging runs from the entrance to a stair leading down toward the lowest hall, its steps deeply scored by the heavy doors.`,`At the top of the stair an overseer keeps watch with some of {villain}’s {foe}, and in the overseer’s pocket is the work order that puts every debtor at the great door. This is where it comes to a fight, unless the heroes slip past.`]),readAloud:a([`Hallen inden for indgangen er bar, og hen over gulvet løber et bredt, blankslidt spor, hvor noget tungt er blevet slæbt ud.`,`Sporet begynder ved en bred trappe, der fører ned i mørket, og trinene er ridset dybt af noget kæmpestort.`,`Nedefra stiger lyden af kæder og hamre, og fint støv drysser fra en revne i loftet.`],[`The hall inside the entrance is bare, and across the floor runs a broad track worn smooth where something heavy has been dragged out.`,`The track begins at a broad stair leading down into darkness, its steps deeply scored by something huge.`,`From below rises the sound of chains and hammers, and fine dust sifts from a crack in the ceiling.`]),details:[a(`En opsynsmand og nogle af {villain}s {foe} holder vagt øverst på trappen, og efter 2 timer er vagten fordoblet. Opsynsmanden er bange for loftet og har kun taget arbejdet for pengenes skyld.`,`An overseer and some of {villain}’s {foe} hold the top of the stair, and after 2 hours the guard is doubled. The overseer is afraid of the ceiling and only took the job for the money.`),a(`I opsynsmandens lomme ligger arbejdsordren med {villain}s håndskrift: Alle hold er ved den store dør i den nederste sal, også om natten, og revnerne i loftet må ikke nævnes for folkene.`,`In the overseer’s pocket is the work order in {villain}’s hand: every gang is at the great door in the lowest hall, nights included, and the cracks in the ceiling are not to be mentioned to the workers.`),a(`Afløbsgangens munding ligger under et jerngitter i et siderum lige før trappen, halvt skjult af murbrokker. Herfra kan heltene komme ned i den nederste sal uden om både vagterne og {boss}.`,`The mouth of the drain passage lies under an iron grating in a side room just before the stair, half hidden by rubble. From here the heroes can reach the lowest hall without passing either the guards or {boss}.`)],checks:[o(`Dexterity (Stealth)`,`medium`,a(`Heltene når siderummet og gitteret uden at blive set; vagterne på trappen aner ikke, at nogen er gået forbi.`,`The heroes reach the side room and the grating unseen; the guards on the stair have no idea anyone has passed.`),a(`Opsynsmanden får øje på dem og råber om hjælp. Kampen begynder på trappens øverste trin, og larmen bærer ned til den nederste sal.`,`The overseer spots them and shouts for help. The fight begins on the top steps, and the noise carries down to the lowest hall.`)),o(`Charisma (Intimidation)`,`easy`,a(`Den bange opsynsmand giver op, så snart kampen vender, og rækker arbejdsordren frem. Opsynsmanden fortæller også, at {boss} står for foden af trappen og aldrig går fra den.`,`The frightened overseer gives up as soon as the fight turns and hands over the work order. The overseer also tells them that {boss} stands at the foot of the stair and never leaves it.`),a(`Opsynsmanden flygter ned ad trappen for at advare de andre. Heltene får kun ordren, hvis de indhenter opsynsmanden, og nedenunder ved man nu, at nogen kommer.`,`The overseer flees down the stair to warn the others. The heroes get the order only if they catch the overseer, and below they now know someone is coming.`))],fight:!0,alternatives:[a(`Bluf forbi vagterne som køberens folk, hvis {villain} allerede har vinket heltene ind ved teltet.`,`Bluff past the guards as the buyer’s people, if {villain} already waved the heroes in at the tent.`),a(`Lad trappen være, og tag afløbsgangen: Vagterne har glemt den, og den kommer ud i den nederste sal uden om {boss}.`,`Leave the stair alone and take the drain passage: the guards have forgotten it, and it comes out in the lowest hall, avoiding {boss}.`)],dmNotes:a(`Hold kampen kort og larmende, og lad loftet minde om sig selv: Hvert slag får støv til at drysse. Spillerne skal mærke, at salen dernede ikke holder ret meget længere.`,`Keep the fight short and loud, and let the ceiling make itself felt: every blow sends dust sifting down. The players should feel that the hall below will not hold much longer.`)},{kind:`exploration`,at:`site`,present:[],title:a(`Afløbsgangen`,`The Drain Passage`),summary:a([`Under jerngitteret begynder den gamle afløbsgang, som {npc3} kravlede ud ad: smal, våd og lav, men den går uden om trappen og {boss} og kommer ud bag stilladset ved den store dør.`,`Det er heltenes vej ind, og den kan blive skyldnernes vej ud, hvis {boss} holder trappen.`],[`Under the iron grating begins the old drain passage that {npc3} crawled out through: narrow, wet and low, but it goes round the stair and {boss} and comes out behind the scaffolding at the great door.`,`It is the heroes’ way in, and it may become the debtors’ way out if {boss} holds the stair.`]),readAloud:a([`Under gitteret falder en skakt ned i en lav, muret gang, hvor iskoldt vand står til anklerne.`,`I mudderet langs væggen ses aftryk af bare fødder, der alle går samme vej: ud.`,`Længere fremme bliver hamringen højere, og gennem en sprække skinner et gult lys.`],[`Below the grating a shaft drops into a low, bricked passage where ice-cold water stands ankle-deep.`,`In the mud along the wall are the prints of bare feet, all going the same way: out.`,`Further on the hammering grows louder, and yellow light shows through a crack.`]),details:[a(`Gangen er så lav, at heltene må gå krumbøjede, og ét sted er den halvt spærret af nedfaldne sten fra den revnede sal ovenover. Dér kan skyldnerne kun komme forbi én ad gangen.`,`The passage is so low that the heroes must go bent double, and in one place it is half blocked by stones fallen from the cracked hall above. There the debtors can only pass one at a time.`),a(`Gangen kommer ud bag stilladset ved den store dør, lige dér, hvor holdene arbejder, og langt fra trappen, hvor {boss} står.`,`The passage comes out behind the scaffolding at the great door, right where the gangs are working, and far from the stair where {boss} stands.`),a(`Efter 5 timer, når loftet styrter ned, fosser støv og vand gennem gangen, og stenene ved det smalle sted skrider. Kommer heltene senere, må de grave sig igennem først.`,`After 5 hours, when the ceiling comes down, dust and water surge through the passage and the stones at the narrow place shift. If the heroes come later, they must dig their way through first.`)],checks:[o(`Strength (Athletics)`,`medium`,a(`Heltene flytter de nedfaldne sten og gør det smalle sted bredt nok til, at to kan komme forbi ad gangen. Vejen ud bliver dobbelt så hurtig.`,`The heroes shift the fallen stones and make the narrow place wide enough for two to pass at once. The way out becomes twice as fast.`),a(`Stenene sidder fast, og et par af dem skrider med et brag. Heltene kommer igennem, men skyldnerne må ud én ad gangen, og larmen kan høres i salen.`,`The stones are stuck, and a few slide with a crash. The heroes get through, but the debtors will have to go out one at a time, and the noise can be heard in the hall.`)),o(`Wisdom (Survival)`,`easy`,a(`Heltene følger vandet nedstrøms og kommer lige frem til sprækken bag stilladset.`,`The heroes follow the water downstream and come straight to the crack behind the scaffolding.`),a(`Gangen deler sig, og heltene tager den forkerte gren. Det koster en halv time i mørket og det kolde vand, før de finder tilbage.`,`The passage forks, and the heroes take the wrong branch. It costs half an hour in the dark and the cold water before they find their way back.`))],fight:!1,alternatives:[a(`Send én helt tilbage op gennem gangen for at stå klar ved gitteret og hjælpe skyldnerne op, efterhånden som de kommer.`,`Send one hero back up the passage to wait at the grating and help the debtors up as they come.`)],dmNotes:a(`Gør gangen trang og kold, men ikke farlig i sig selv: Den er en prøve på tålmodighed. Tæl tiden højt, og lad hamringen blive højere for hvert skridt.`,`Make the passage cramped and cold but not dangerous in itself: it is a test of patience. Count the time out loud, and let the hammering grow louder with every step.`)}],climax:{kind:`climax`,at:`site`,present:[`npc2`,`villain`],title:a(`Den sidste dør`,`The Last Door`),summary:a([`I den nederste sal står skyldnerne, {npc2} iblandt dem, lænket i hold ved den store bronzedør, hvis karm holder loftet oppe; {villain}s {foe} driver dem frem, og {boss} vogter foden af den eneste trappe op.`,`Efter 5 timer, eller så snart arbejdet går i stå, kommer {villain} selv ned for første gang med nøglerne og gældsbeviserne i en taske for at se døren blive brudt løs.`,`Heltene skal have lænkerne op og alle ud, ad trappen eller afløbsgangen, før loftet falder.`],[`In the lowest hall the debtors, {npc2} among them, stand chained in gangs at the great bronze door whose frame holds the ceiling up; {villain}’s {foe} drive them on, and {boss} guards the foot of the only stair up.`,`After 5 hours, or as soon as the work stops, {villain} comes down in person for the first time, the keys and the bonds in a satchel, to see the door torn loose.`,`The heroes must get the chains open and everyone out, by the stair or the drain passage, before the ceiling falls.`]),readAloud:a([`Salen er enorm og lav, og i den fjerne væg står en dør af grønsort bronze, højere end tre mennesker, med kæder og reb spændt fast i kanterne.`,`Et par dusin lænkede mennesker arbejder ved karmen med mejsler og jernstænger, og hvert slag får fint grus til at drysse fra en lang revne i loftet.`,`Revnen løber lige hen over døren, og gruset falder fra den som sand i et timeglas.`],[`The hall is vast and low, and in the far wall stands a door of greenish-black bronze, taller than three people, with chains and ropes made fast to its edges.`,`A couple of dozen people in fetters work at the frame with chisels and iron bars, and every blow sends fine grit trickling from a long crack in the ceiling.`,`The crack runs right across the top of the door, and the grit falls from it like sand in an hourglass.`]),details:[a(`{boss} og {villain}s {foe} er betalt for at vogte holdene og trappen og tjener {villain}, så længe betalingen kommer. Den, der kommer ned ad trappen, møder {boss} først; den, der kommer ud af afløbsgangen, står midt blandt skyldnerne.`,`{boss} and {villain}’s {foe} are paid to guard the gangs and the stair and serve {villain} as long as the pay comes. Whoever comes down the stair meets {boss} first; whoever comes out of the drain passage stands among the debtors.`),a(`Før 5 timer løber en opsynsmand op efter {villain}, så snart arbejdet går i stå, og {villain} kommer ned få minutter senere, rædselsslagen og med et lommetørklæde for munden. Efter 5 timer er en del af loftet allerede faldet, to arbejdere ligger under murbrokkerne, og de nærmeste hold vil ikke gå uden dem.`,`Before 5 hours have passed, an overseer runs up to fetch {villain} as soon as the work stops, and {villain} comes down a few minutes later, terrified, a handkerchief over their mouth. After 5 hours part of the ceiling has already fallen, two workers lie under the rubble, and the nearest gangs will not leave without them.`),a(`Med nøglerne fra tasken er holdene låst op på et øjeblik, og uden gældsbeviserne har {villain} intet krav på nogen af dem. Ved daggry trækker køberens heste i kæderne, døren rives løs, og loftet falder.`,`With the keys from the satchel the gangs are unlocked in moments, and without the bonds {villain} has no claim on any of them. At dawn the buyer’s horses haul on the chains, the door is torn loose and the ceiling falls.`)],checks:[o(`Charisma (Intimidation)`,`medium`,a(`{villain} er rædselsslagen hernede og rækker tasken frem for at få lov at gå op igen. Uden beviserne og betalingen trækker opsynsmændene sig, men {boss} må heltene stadig klare.`,`{villain} is terrified down here and holds out the satchel to be let back up. Without the bonds and the pay the overseers back off, but the heroes must still deal with {boss}.`),a(`{villain} flygter op ad trappen med tasken og råber til {boss} om at holde heltene tilbage. Heltene må bryde lænkerne op med magt eller komme forbi {boss} efter {villain}.`,`{villain} flees up the stair with the satchel, shouting to {boss} to hold the heroes back. The heroes must break the chains by force or get past {boss} after {villain}.`)),o(`Charisma (Persuasion)`,`medium`,a(`{npc2} og de ældste skyldnere får holdene til at gå i ro og orden mod afløbsgangen eller trappen. Ingen går i panik, og ingen bliver glemt.`,`{npc2} and the oldest debtors get the gangs moving in good order toward the drain passage or the stair. Nobody panics, and nobody is forgotten.`),a(`Panikken bryder ud, da loftet knager, og der opstår trængsel ved afløbsgangen. Et hold bliver tilbage, og heltene må vende om efter det.`,`Panic breaks out when the ceiling creaks, and there is a crush at the drain passage. One gang is left behind, and the heroes must go back for it.`))],fight:!0,alternatives:[a(`Løsn kæderne fra døren: Så kan køberens heste ikke rive den løs ved daggry, og loftet holder lidt endnu.`,`Unhook the chains from the door: then the buyer’s horses cannot tear it loose at dawn, and the ceiling holds a little longer.`),a(`Tilbyd {villain} en vej ud: trappen op, alene og i live, i bytte for tasken.`,`Offer {villain} a way out: up the stair, alone and alive, in exchange for the satchel.`)],dmNotes:a(`Tæl skyldnerne højt, efterhånden som de kommer forbi heltene, og lad loftet knage mellem hvert hold. Bliver tiden knap, så lad spillerne høre revnen vokse og selv bestemme, hvem der skal ud først.`,`Count the debtors out loud as they pass the heroes, and let the ceiling creak after each gang. If time runs short, let the players hear the crack widen and decide for themselves who goes first.`)}},"heist-pawned-chain":{opening:{kind:`opening`,at:`town`,present:[`npc1`],title:a(`Borgmesterens tilståelse`,`The Mayor’s Confession`),summary:a([`{npc1}, borgmester i {town}, har opsøgt heltene i al hemmelighed og taget dem med ind i den tomme rådssal. Her tilstår {npc1}, at byens borgmesterkæde blev pantsat hos {villain} i det sultne forår for at købe korn, at {villain} snød {npc1} for indløsningen, og at en udenlandsk køber henter kæden ved daggry.`,`{npc1} giver heltene en skitse af {villain}s hus og beder dem bringe både kæden og pantesedlen tilbage, så ingen nogensinde behøver at få det at vide.`],[`{npc1}, the mayor of {town}, has sought the heroes out in secret and brought them into the empty council chamber. Here {npc1} confesses that the town’s chain of office was pawned to {villain} in the hungry spring to buy grain, that {villain} cheated {npc1} out of redeeming it, and that a foreign buyer collects it at dawn.`,`{npc1} gives the heroes a sketch of {villain}’s house and begs them to bring back both the chain and the pawn note, so that no one need ever know.`]),readAloud:a([`Rådssalen er mørk bortset fra en enkelt lampe på det lange bord.`,`På væggen bag borgmesterens stol hænger byens malede våben, og under det sidder en jernkrog, hvor der ikke hænger noget.`,`Ude fra torvet lyder skridt, der kommer nærmere og så går forbi.`],[`The council chamber is dark except for a single lamp on the long table.`,`On the wall behind the mayor’s chair hangs the town’s painted coat of arms, and beneath it an iron hook with nothing on it.`,`From the square outside come footsteps, drawing closer, then passing by.`]),details:[a(`Skitsen viser gården, kontoret og soveværelset, men ikke skatkammeret; det har {npc1} aldrig set. {npc1} husker, at butikken var lukket netop den dag, {npc1} kom med pengene, for første gang i tyve år, og det husker naboerne også.`,`The sketch shows the yard, the office and the bedchamber, but not the strongroom, which {npc1} has never seen. {npc1} remembers that the shop was shut on the very day {npc1} came with the money, for the first time in twenty years, and the neighbours remember it too.`),a(`Byens udråber drikker på kroen over for rådhuset og praler med, at {villain} har betalt ekstra for "en stor nyhed om borgmesteren" på torvet i morgen tidlig.`,`The town crier is drinking at the inn across from the town hall, boasting that {villain} has paid extra for "big news about the mayor" in the square tomorrow morning.`),a(`{villain} har hadet {npc1}, siden {npc1} holdt {villain} ude af rådet. Ingen må vide noget: {npc1} kan hverken bruge vagten eller rådet, kun heltene.`,`{villain} has hated {npc1} ever since {npc1} kept {villain} off the council. No one may know: {npc1} can use neither the watch nor the council, only the heroes.`)],checks:[o(`Wisdom (Insight)`,`easy`,a(`{npc1} skammer sig, men taler sandt: Kornet reddede byen. Presset nævner {npc1}, at {npc3}, en tjener i {villain}s hus, engang bad om hjælp, og at {npc3} hver aften henter urter til {villain}s sovemiddel hos urtekræmmeren.`,`{npc1} is ashamed but speaks the truth: the grain saved the town. Pressed, {npc1} mentions that {npc3}, a servant in {villain}’s house, once asked for help, and that {npc3} fetches herbs for {villain}’s sleeping draught from the herbalist every evening.`),a(`{npc1} husker først {npc3}s navn, da heltene er på vej ud ad døren. De når frem til {npc3} med kun få minutter til overs, før klokken slår ti.`,`{npc1} only remembers {npc3}’s name as the heroes are on their way out. They reach {npc3} with only minutes to spare before the bell strikes ten.`)),o(`Charisma (Persuasion)`,`medium`,a(`{npc1} åbner byens kiste: nok sølv til at købe murermesterens tegning og bestikke den, der skal bestikkes.`,`{npc1} opens the town chest: enough silver to buy the mason’s plan and bribe whoever needs bribing.`),a(`{npc1} har intet andet at give end skitsen og et løfte. Murermesteren og alle andre må heltene selv betale.`,`{npc1} has nothing more to give than the sketch and a promise. The heroes must pay the mason and everyone else themselves.`))],fight:!1,alternatives:[a(`Gå direkte mod {villain}s hus med skitsen alene: Det går hurtigt, men skitsen viser hverken skatkammeret eller den anden nøgle.`,`Head straight for {villain}’s house with only the sketch: it is quick, but the sketch shows neither the strongroom nor the second key.`),a(`Lad {npc1} tilstå selv på torvet ved daggry, før {villain} når det: Så mister pantesedlen sin brod, men kæden skal stadig hentes tilbage.`,`Have {npc1} confess in the square at dawn, before {villain} can: the pawn note loses its sting, but the chain must still be recovered.`)],dmNotes:a(`Gør {npc1} sympatisk: Kæden blev pantsat for at give byen brød, ikke for at nogen skulle blive rig. Spillerne skal føle, at de stjæler byens ære tilbage og ikke bare et smykke.`,`Make {npc1} sympathetic: the chain was pawned to give the town bread, not to make anyone rich. The players should feel they are stealing back the town’s honour, not just a trinket.`)},middle:[{kind:`social`,at:`town`,present:[`npc3`],title:a(`Sovemidlet`,`The Sleeping Draught`),summary:a([`Før klokken slår ti, står {npc3}, tjeneren i {villain}s hus, hos urtekræmmeren og køber urter til det sovemiddel, {npc3} selv blander til {villain}.`,`{npc3} hader {villain} og kan gøre drikken stærkere, lade køkkendøren stå ulåst eller fortælle, hvordan huset sover, hvis heltene når frem i tide og kan stoles på.`],[`Before the bell strikes ten, {npc3}, the servant in {villain}’s house, stands at the herbalist’s counter buying herbs for the sleeping draught {npc3} mixes for {villain}.`,`{npc3} hates {villain} and can make the draught stronger, leave the kitchen door unbarred or explain how the household sleeps, if the heroes get there in time and can be trusted.`]),readAloud:a([`Urtekræmmerens butik er smal og lugter af kamfer og tørrede blomster.`,`En tjener i et gråt forklæde tæller mønter op for et lille kræmmerhus med urter og kigger mod døren, hver gang den går op.`,`Fra tårnet slår klokken trekvart.`],[`The herbalist’s shop is narrow and smells of camphor and dried flowers.`,`A servant in a grey apron counts out coins for a small paper twist of herbs, glancing at the door each time it opens.`,`From the tower the bell strikes the three-quarter hour.`]),details:[a(`{villain} drikker sovemidlet, når klokken slår ti, og sover tungt i fem timer. {npc3} kan gøre det stærkere, så {villain} sover en time længere, men vil ikke give {villain} noget, der kan slå ihjel.`,`{villain} drinks the draught when the bell strikes ten and sleeps like a stone for five hours. {npc3} can make it stronger, so that {villain} sleeps an hour longer, but will not give {villain} anything that could kill.`),a(`{npc3} hader {villain} med god grund: {villain} har haft {npc3}s mors ring i pant i tre år og trækker renterne fra {npc3}s løn. Ringen ligger i skatkammeret med et nummereret mærke.`,`{npc3} hates {villain} with good reason: {villain} has held {npc3}’s mother’s ring in pawn for three years and takes the interest out of {npc3}’s wages. The ring lies in the strongroom with a numbered tag.`),a(`{npc3} ved, at {villain}s {foe} går runder om huset, at {boss} holder sig til gangen nedenunder, og at {villain} sover med en nøgle i en snor om halsen. Efter klokken ti er {npc3} tilbage i huset og sætter en tom kop ud på trappen, når {villain} sover.`,`{npc3} knows that {villain}’s {foe} walk rounds of the house, that {boss} keeps to the passage below, and that {villain} sleeps with a key on a cord around their neck. After ten {npc3} is back in the house and sets an empty cup out on the stair once {villain} is asleep.`)],checks:[o(`Charisma (Persuasion)`,`medium`,a(`{npc3} går med til at gøre drikken stærkere og lade køkkendøren stå ulåst. {villain} vågner først efter 7 timer i stedet for 6.`,`{npc3} agrees to make the draught stronger and leave the kitchen door unbarred. {villain} wakes only after 7 hours instead of 6.`),a(`{npc3} tør ikke røre ved drikken, men lover at lade køkkendøren stå ulåst. Uret går som før.`,`{npc3} dares not touch the draught but promises to leave the kitchen door unbarred. The clock runs as before.`)),o(`Wisdom (Insight)`,`easy`,a(`Heltene ser, at {npc3}s had er ægte, og at {npc3} hellere vil miste pladsen end forråde dem. Et løfte om moderens ring binder {npc3} til planen.`,`The heroes see that {npc3}’s hatred is real and that {npc3} would rather lose their position than betray them. A promise to get {npc3}’s mother’s ring back binds {npc3} to the plan.`),a(`Heltene er usikre på {npc3} og siger for meget eller for lidt. {npc3} hjælper, men er så nervøs, at husets andre tjenere lægger mærke til det.`,`The heroes are unsure of {npc3} and say too much or too little. {npc3} helps, but is so nervous that the other servants in the house notice.`))],fight:!1,alternatives:[a(`Kommer heltene for sent til urtekræmmeren, kan de holde øje med trappen fra gaden: Den tomme kop fortæller, at {villain} sover.`,`If the heroes reach the herbalist too late, they can watch the stair from the street: the empty cup tells them {villain} is asleep.`),a(`Køb {npc3} fri: Penge nok til at forlade byen i morgen er et bedre løfte end hævn.`,`Buy {npc3} out: enough money to leave town tomorrow is a better promise than revenge.`)],dmNotes:a(`Brug et rigtigt ur: Klokken slår ti, når scenen har varet en bestemt tid, og så er {npc3} væk. {npc3}s frygt er scenen; ét forkert ord, og {npc3} skynder sig ud ad døren.`,`Use a real clock: the bell strikes ten once the scene has run a set time, and then {npc3} is gone. {npc3}’s fear is the scene; one wrong word and {npc3} hurries out of the door.`)},{kind:`investigation`,at:`town`,present:[],title:a(`Pantebogen`,`The Pledge Book`),summary:a([`{villain}s pantelånerbutik i {town} står mørk for natten, og pantebogen derinde viser, at dagen for indløsningen af pant nr. 113 er rettet med friskere blæk. I skuffen ligger en genpart af salgsaftalen med køberen.`,`Over for butikken bor murermesteren, der byggede skatkammeret, og som gerne sælger sin tegning af det for en god pris.`],[`{villain}’s pawnshop in {town} stands dark for the night, and the pledge book inside shows that the redemption day for pledge no. 113 has been corrected in fresher ink. In the drawer lies a copy of the bill of sale to the buyer.`,`Across the lane lives the mason who built the strongroom and will gladly sell the plan of it for a good price.`]),readAloud:a([`Pantelånerbutikkens skodder er lukket og låst, og et skilt i vinduet siger "Lukket" med pæne bogstaver.`,`Gennem en sprække mellem brædderne falder månelyset på hylder med andre folks ting: støvler, en violin, en vugge.`,`Over for butikken brænder der stadig lys i et værksted fuldt af stenstøv og mejsler.`],[`The pawnshop’s shutters are closed and locked, and a sign in the window says "Shut" in neat letters.`,`Through a crack between the boards, moonlight falls on shelves of other people’s things: boots, a fiddle, a cradle.`,`Across the lane a light still burns in a workshop full of stone dust and chisels.`]),details:[a(`I pantebogen er dagen for indløsningen af pant nr. 113 rettet fra den 9. til den 8. med friskere blæk end resten af siden. Det er beviset på, at {villain} snød {npc1}.`,`In the pledge book, the redemption day for pledge no. 113 has been changed from the 9th to the 8th in fresher ink than the rest of the page. It is the proof that {villain} cheated {npc1}.`),a(`I skuffen under disken ligger genparten af salgsaftalen: Kæden afhentes ved daggry i {place}, og {villain} indestår for, at ingen i {town} gør krav på den. Butikkens lås er enkel, men vægteren går forbi hvert kvarter.`,`In the drawer under the counter lies the copy of the bill of sale: the chain is to be collected at dawn at {place}, and {villain} warrants that no one in {town} has any claim on it. The shop’s lock is simple, but the watchman passes every quarter of an hour.`),a(`Murermesteren husker, at butikken var lukket den dag, borgmesteren kom med pengene, og har stadig tegningen af skatkammeret: trappen bag panelet i kontoret, luftskakten fra gården, kisten med de to låse og nøglen i kontorets ur.`,`The mason remembers that the shop was shut on the day the mayor came with the money, and still has the plan of the strongroom: the stair behind the panel in the office, the air shaft from the yard, the chest with two locks and the key in the office clock.`)],checks:[o(`Dexterity (Stealth)`,`easy`,a(`Heltene er inde og ude igen mellem vægterens runder, og ingen ved, at pantebogen har været åbnet.`,`The heroes are in and out between the watchman’s rounds, and nobody knows the pledge book has been opened.`),a(`Vægteren ser lys i butikken og begynder at stille spørgsmål. Heltene mister en halv time på at snakke sig fri, eller {npc1}s navn klarer det, men så ved vægteren, at borgmesteren er indblandet.`,`The watchman sees a light in the shop and starts asking questions. The heroes lose half an hour talking their way out, or {npc1}’s name settles it, but then the watchman knows the mayor is involved.`)),o(`Charisma (Persuasion)`,`medium`,a(`Murermesteren sælger tegningen til en rimelig pris og fortæller, at nøglen i uret hænger bag pendulet.`,`The mason sells the plan at a fair price and adds that the key in the clock hangs behind the pendulum.`),a(`Murermesteren vil have mere, end heltene har. De kan betale med et løfte fra {npc1}, men købslåningen koster en halv time.`,`The mason wants more than the heroes have. They can pay with a promise from {npc1}, but the haggling costs half an hour.`))],fight:!1,alternatives:[a(`Spring tegningen over: Lugten ved panelet og det slidte gulv viser vejen ned, men den anden nøgle må heltene så lede efter i kontoret.`,`Skip the plan: the smell at the panel and the worn floor show the way down, but the heroes must then search the office for the second key.`),a(`Tag pantebogen med: Står heltene ansigt til ansigt med {villain} i skatkammeret, er den et bedre våben end noget sværd.`,`Take the pledge book along: if the heroes end up face to face with {villain} in the strongroom, it is a better weapon than any sword.`)],dmNotes:a(`Det er her, spillerne planlægger: Giv dem murermesterens tegning som et rigtigt stykke papir, og lad dem skændes om den. Skriv deres plan ned, så du ved, hvor den kan gå galt.`,`This is where the players plan: give them the mason’s plan as a real piece of paper and let them argue over it. Write their plan down so you know where it can go wrong.`)},{kind:`exploration`,at:`site`,present:[],title:a(`Uret i kontoret`,`The Office Clock`),summary:a([`Heltene krydser gården mellem runderne af {villain}s {foe} og glider ind i kontoret, hvor panelet skjuler trappen ned, og hvor det høje ur gemmer nøglen til den ene lås.`,`Patruljerne holder sig fra gangen nedenunder, hvor kun {boss} færdes, så heroppe er faren at blive set; dernede er det {boss}, og larmer det i gangen, kommer patruljerne til inden for to runder.`],[`The heroes cross the yard between the rounds of {villain}’s {foe} and slip into the office, where the panel hides the stair down and the tall clock hides the key to one of the locks.`,`The patrols keep away from the passage below, where only {boss} goes, so up here the danger is being seen; down there it is {boss}, and if there is noise in the passage, the patrols arrive within two rounds.`]),readAloud:a([`Gården er brolagt og fejet, og en lygte hænger over køkkendøren.`,`Skridt krydser gården og forsvinder om hjørnet af huset; lidt efter kommer de igen.`,`Inde i kontoret tikker et højt ur ved siden af et mørkt træpanel, og gulvet foran panelet er slidt blankt.`],[`The yard is paved and swept clean, and a lantern hangs over the kitchen door.`,`Footsteps cross the yard and fade round the corner of the house; a little later they come back.`,`Inside the office a tall clock ticks beside a dark wooden panel, and the floor in front of the panel is worn smooth.`]),details:[a(`{villain}s {foe} går runder om huset to og to og holder sig fra gangen foran skatkammeret. Før klokken ti er {villain} vågen; når lyset i soveværelset går ud, og {npc3} sætter en tom kop ud på trappen, sover {villain}.`,`{villain}’s {foe} walk rounds of the house in pairs and keep away from the passage outside the strongroom. Before ten {villain} is awake; once the light in the bedchamber goes out and {npc3} sets an empty cup on the stair, {villain} is asleep.`),a(`Ved panelet hænger en svag lugt af lampeolie og jern, og gulvet foran er slidt blankt. Bag panelet går en smal trappe ned til gangen, hvor {boss} holder vagt.`,`A faint smell of lamp oil and iron hangs by the panel, and the floor before it is worn smooth. Behind the panel a narrow stair goes down to the passage where {boss} keeps watch.`),a(`Nøglen til den ene lås hænger bag urets pendul. Standser pendulet, holder uret op med at tikke, og den stilhed er det første, {villain} lægger mærke til, når {villain} kommer gennem kontoret efter 6 timer.`,`The key to one lock hangs behind the clock’s pendulum. If the pendulum stops, the clock stops ticking, and that silence is the first thing {villain} notices when coming through the office after 6 hours.`)],checks:[o(`Dexterity (Stealth)`,`medium`,a(`Heltene krydser gården i hullet mellem to runder og er inde i kontoret uden en lyd.`,`The heroes cross the yard in the gap between two rounds and are in the office without a sound.`),a(`En patrulje får øje på en skygge og kommer for at se efter. Heltene må gemme sig eller tage kampen, og den skal være stille, ellers vågner husstanden.`,`A patrol glimpses a shadow and comes to look. The heroes must hide or fight, and the fight must be quiet, or the household wakes.`)),o(`Dexterity (Sleight of Hand)`,`medium`,a(`Nøglen kommer fri, uden at pendulet går i stå, og uret tikker videre, som om intet var hændt.`,`The key comes free without stopping the pendulum, and the clock ticks on as if nothing had happened.`),a(`Pendulet går i stå, og uret tier. Når {villain} kommer gennem kontoret efter 6 timer (7, hvis {npc3} gjorde drikken stærkere), hører {villain} stilheden og går ned og råber på {boss}.`,`The pendulum stops and the clock falls silent. When {villain} comes through the office after 6 hours (7 if {npc3} made the draught stronger), {villain} hears the silence and goes down shouting for {boss}.`))],fight:!0,alternatives:[a(`Har {npc3} ladet køkkendøren stå ulåst, kan heltene gå ind gennem huset i stedet for over den åbne gård.`,`If {npc3} left the kitchen door unbarred, the heroes can go in through the house instead of across the open yard.`),a(`Lad én helt holde vagt i gården og give tegn ved hver runde, mens de andre arbejder i kontoret.`,`Have one hero keep watch in the yard and signal at every round while the others work in the office.`)],dmNotes:a(`Gør patruljernes mønster synligt: Beskriv det to gange, så spillerne kan time det. En plan, der virker, fordi spillerne har holdt øje, er hele fornøjelsen ved et kup.`,`Make the patrol pattern visible: describe it twice so the players can time it. A plan that works because the players paid attention is the whole joy of a heist.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:a(`Jernkisten`,`The Iron Chest`),summary:a([`Under {villain}s soveværelse ligger skatkammeret, hvor kæden og pantesedlen ligger i en jernkiste, der er boltet til gulvet og har to låse; {boss} holder vagt i gangen udenfor og tjener {villain} ligesom patruljerne.`,`Før daggry kan {villain} ikke lade være med at gå ned og se på kæden en sidste gang, med lampe og nøglen om halsen: efter 6 timer (7, hvis {npc3} gjorde drikken stærkere), eller før, hvis kamp eller larm ved kisten trænger op gennem gulvet.`,`Heltene skal have begge låse op og komme ud med kæde og seddel, før køberen kommer.`],[`Beneath {villain}’s bedchamber lies the strongroom, where the chain and the pawn note rest in an iron chest bolted to the floor, with two locks; {boss} keeps watch in the passage outside and serves {villain}, like the patrols.`,`Before dawn {villain} cannot resist going down to look at the chain one last time, with a lamp and the key around their neck: after 6 hours (7 if {npc3} made the draught stronger), or sooner if a fight or noise at the chest carries up through the floor.`,`The heroes must open both locks and get out with the chain and the note before the buyer arrives.`]),readAloud:a([`Trappen bag panelet lugter af lampeolie og jern og ender i en kort stengang, hvor nogen eller noget rører sig i mørket foran en tung, jernbeslået dør.`,`Bag døren ligger et lavt rum med hylder fulde af pantsatte ting: lysestager, sølvbægre og en dåbspokal, hver med sit nummererede mærke.`,`Midt på gulvet står en jernkiste med to nøglehuller, boltet fast til stenen.`],[`The stair behind the panel smells of lamp oil and iron and ends in a short stone passage where someone or something shifts in the dark before a heavy, iron-bound door.`,`Beyond the door lies a low room with shelves full of pledges: candlesticks, silver cups and a christening cup, each with its numbered tag.`,`In the middle of the floor stands an iron chest with two keyholes, bolted to the stone.`]),details:[a(`Den ene lås åbnes med nøglen fra kontorets ur, den anden med nøglen om {villain}s hals. Heltene kan løfte den fra den sovende {villain}, tage den, når {villain} kommer ned, eller dirke låsen op.`,`One lock opens with the key from the office clock, the other with the key round {villain}’s neck. The heroes can lift it from the sleeping {villain}, take it when {villain} comes down, or pick the lock.`),a(`Efter 6 timer (7, hvis {npc3} gjorde drikken stærkere), eller når larm fra kamp eller kiste vækker {villain}, kommer {villain} ned ad trappen i nattøj med en lampe, truer med at råbe på tyve og kalder sig en ærlig pantelåner, men er bange og vil hellere forhandle end komme til skade.`,`After 6 hours (7 if {npc3} made the draught stronger), or when noise from a fight or the chest wakes {villain}, {villain} comes down the stair in nightclothes with a lamp, threatening to cry thief and claiming to be an honest pawnbroker, but is afraid and would rather bargain than be hurt.`),a(`I kisten ligger kæden svøbt i fløjl og pantesedlen med {npc1}s underskrift. Er heltene væk, før {villain} vågner (6 timer, 7 med den stærkere drik), finder {villain} kisten tom og kan ikke anmelde tyveriet uden at afsløre bedrageriet i pantebogen.`,`In the chest lie the chain, wrapped in velvet, and the pawn note with {npc1}’s signature. If the heroes are gone before {villain} wakes (6 hours, 7 with the stronger draught), {villain} finds the chest empty and cannot report the theft without revealing the fraud in the pledge book.`)],checks:[o(`Dexterity (Sleight of Hand)`,`hard`,a(`Den anden lås giver sig med et lille klik, og kisten går op uden en lyd.`,`The second lock gives with a small click, and the chest opens without a sound.`),a(`Dirken knækker i låsen med et skarpt smæld, der trænger op gennem gulvet. {villain} vågner, og {boss} kommer hen til døren.`,`The pick snaps in the lock with a sharp crack that carries up through the floor. {villain} wakes, and {boss} comes to the door.`)),o(`Charisma (Intimidation)`,`medium`,a(`{villain} rækker nøglen frem og lover tavshed: {villain} kan ikke anmelde tyveriet uden at afsløre bedrageriet, og det ved {villain}.`,`{villain} hands over the key and promises silence: {villain} cannot report the theft without revealing the fraud, and knows it.`),a(`{villain} skriger på husstanden. Flugten bliver en jagt gennem huset, og {villain} vil påstå, at kæden blev stjålet fra en ærlig pantelåner.`,`{villain} screams for the household. The escape becomes a chase through the house, and {villain} will claim the chain was stolen from an honest pawnbroker.`))],fight:!0,alternatives:[a(`Læg pantebogens rettede side frem for {villain}: Bliver tyveriet anmeldt, kommer bedrageriet frem, og {villain} lader heltene gå.`,`Lay the corrected page of the pledge book before {villain}: if the theft is reported, the fraud comes out, and {villain} lets the heroes go.`),a(`Vent i mørket i skatkammeret, til {villain} kommer ned med nøglen efter 6 timer (7, hvis {npc3} gjorde drikken stærkere), og tag den i døren.`,`Wait in the dark strongroom until {villain} comes down with the key after 6 hours (7 if {npc3} made the draught stronger), and take it at the door.`)],dmNotes:a(`Lad rummet fortælle historien: Hver hylde er en andens skat, og et af mærkerne hører til {npc3}s mors ring. Lad {villain}s første ord være en løgn om at være ærlig, og lad heltene svare med pantebogen.`,`Let the room tell the story: every shelf holds someone else’s treasure, and one of the tags belongs to {npc3}’s mother’s ring. Let {villain}’s first words be a lie about honesty, and let the heroes answer with the pledge book.`)}},"heist-midwinter-masks":{opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc3`],title:a(`Tolv tomme pløkke`,`Twelve Empty Pegs`),summary:a([`Midvinternat hos {npc1}, den gamle maskevogter: Langs væggen hænger tolv tomme pløkke, hvor maskerne har hængt i generationer.`,`{npc1} lægger bedstefaderens tegning af hvælvingen og slægtens sidste sølv på bordet og beder heltene stjæle maskerne tilbage før daggry. Ved kakkelovnen sidder gamle {npc3}, der dansede ved siden af {villain}s bror den nat, han døde, og ved, hvad der virkelig skete.`],[`Midwinter night at the house of {npc1}, the old mask keeper: along the wall hang twelve empty pegs where the masks have hung for generations.`,`{npc1} lays their grandfather’s drawing of the vault and the family’s last silver on the table and asks the heroes to steal the masks back before dawn. By the stove sits old {npc3}, who danced beside {villain}’s brother the night he died and knows what really happened.`]),readAloud:a([`Langs den ene væg i den lave stue sidder en række på tolv træpløkke, hver især slidt mørk og glat af tre hundrede vintre, og alle er tomme.`,`I hjørnet knitrer ilden i kakkelovnen, og på bordet ligger en gulnet tegning, holdt flad af en lysestage og en lille, slidt pung.`,`Gennem de frosne ruder ses bålet på torvet som en sort stabel mod himlen.`],[`Along one wall of the low room runs a row of twelve wooden pegs, each worn dark and smooth by three hundred winters, and every one of them empty.`,`In the corner a fire crackles in the stove, and on the table lies a yellowed drawing, held flat by a candlestick and a small, worn purse.`,`Through the frosted panes the pyre in the square shows as a black stack against the sky.`]),details:[a(`Ordren om beslaglæggelsen, som {npc1} fik i hånden, er formuleret af {villain} og kun underskrevet af to rådsmedlemmer, ikke de fem, loven kræver. Beslaglæggelsen holder ikke for loven, men ingen tør sige det højt i nat.`,`The seizure order handed to {npc1} was worded by {villain} and signed by only two councillors, not the five the law requires. The seizure would not stand up in law, but nobody dares say so aloud tonight.`),a(`Bedstefaderens tegning viser hvælvingens ene jernbeslåede dør og den gamle kulskakt fra køkkenet ovenover, muret til med kun ét lag sten. Kisterne står tørrest ved den nordre væg, og dér kommer skakten ud.`,`The grandfather’s drawing shows the vault’s single iron-bound door and the old coal chute from the kitchen above, bricked up only one course thick. The chests keep driest by the north wall, and that is where the chute comes out.`),a(`{npc3} fortæller, at {villain}s bror døde, fordi en rådden bjælke knækkede under dansen, men at {villain} aldrig ville høre det. {npc3} husker også, hvilken maske broderen bar: den gamle hare med det revnede øre.`,`{npc3} says that {villain}’s brother died because a rotten beam broke during the dance, but that {villain} would never hear of it. {npc3} also remembers which mask the brother wore: the old hare with the cracked ear.`)],checks:[o(`Charisma (Persuasion)`,`medium`,a(`{npc3} går med til at sige {villain} sandheden ansigt til ansigt, enten i hvælvingen eller ved bålet ved daggry. Gamle ben går langsomt, men {npc3} går.`,`{npc3} agrees to tell {villain} the truth face to face, either in the vault or at the pyre at dawn. Old legs go slowly, but {npc3} goes.`),a(`{npc3} har prøvet før og tror ikke, at {villain} vil høre efter. Heltene må selv bære {npc3}s fortælling ned i hvælvingen, og den vejer mindre, når den kommer fra dem.`,`{npc3} has tried before and does not believe {villain} will listen. The heroes must carry {npc3}’s story into the vault themselves, and it weighs less coming from them.`)),o(`Intelligence (Investigation)`,`easy`,a(`Heltene læser tegningen rigtigt: Kulskakten kommer ud lige ved kisterne, så vejen uden om døren og gangene er også den korteste vej til maskerne.`,`The heroes read the drawing correctly: the coal chute comes out right by the chests, so the way that avoids the door and the passages is also the shortest way to the masks.`),a(`Heltene kan ikke se, hvor i køkkenet skakten sidder, og må lede efter den derude. Det koster en halv time.`,`The heroes cannot tell where in the kitchen the chute lies and must search for it on the spot. That costs half an hour.`))],fight:!1,alternatives:[a(`Væk de rådsmedlemmer, der ikke skrev under, og få ordren erklæret ugyldig. Det tager hele natten og vinder måske kun en udsættelse, for {villain}s prædikener har skræmt dem.`,`Wake the councillors who did not sign and have the order declared void. It takes all night and may only win a delay, for {villain}’s sermons have frightened them.`),a(`Vent ved vejen, og tag kisterne fra vognen ved første lys; det er den sidste chance, hvis hvælvingen ikke kan nås.`,`Wait by the road and take the chests from the cart at first light; it is the last chance if the vault cannot be reached.`)],dmNotes:a(`Lad {npc1} røre ved de tomme pløkke, mens {npc1} taler, og giv tegningen til spillerne som et rigtigt stykke papir. Denne nat handler om sorg på begge sider: {npc1}s og {villain}s.`,`Let {npc1} touch the empty pegs while speaking, and give the drawing to the players as a real piece of paper. This night is about grief on both sides: {npc1}’s and {villain}’s.`)},middle:[{kind:`investigation`,at:`town`,present:[],title:a(`Den gamle salmebog`,`The Old Hymnal`),summary:a([`{villain}s hus ved torvet står mørkt, mens {villain} leder salmesangen ved bålet og senere går til {place}. I stuen hænger et portræt af en ung mand i dansedragt med et sørgebånd over rammen, og på bordet ligger den gamle salmebog med noget skrevet med blyant.`,`Her finder heltene nøglens gemmested og forstår, hvad der driver {villain}.`],[`{villain}’s house by the square stands dark while {villain} leads the hymns at the pyre and later goes to {place}. In the parlour hangs a portrait of a young man in dance costume with a mourning ribbon across the frame, and on the table lies the old hymnal with something written in pencil.`,`Here the heroes find out where the key is hidden and understand what drives {villain}.`]),readAloud:a([`Huset er koldt og ryddeligt, og der lugter af tællelys og sæbe.`,`Over kaminen i stuen hænger et lille portræt af en ung mand i dansedragt, og et sort sørgebånd er bundet over det ene hjørne af rammen.`,`På bordet under det ligger en gammel salmebog med slidt ryg og en blyant mellem siderne.`],[`The house is cold and tidy and smells of tallow and soap.`,`Over the parlour fireplace hangs a small portrait of a young man in dance costume, a black mourning ribbon tied across one corner of the frame.`,`On the table beneath it lies an old hymnal with a worn spine and a pencil between the pages.`]),details:[a(`Inde i salmebogens omslag står med blyant, at nøglen ligger under tærsklen øverst på trappen til hvælvingen, og at intet må blive tilbage: tre kister, tolv masker. Efter 2 timer ligger nøglen der ikke længere, for så har {villain} taget den med ind i hvælvingen.`,`Inside the hymnal’s cover it says in pencil that the key lies under the threshold at the top of the vault stair, and that nothing must be left behind: three chests, twelve masks. After 2 hours the key is no longer there, for by then {villain} has taken it into the vault.`),a(`Portrættet er af {villain}s bror. I skrivebordsskuffen ligger tyve års prædikener mod dansen, og den ældste er skrevet natten efter begravelsen.`,`The portrait is of {villain}’s brother. In the desk drawer lie twenty years of sermons against the dance, the oldest written the night after the funeral.`),a(`På kroen over for huset drikker nogle af de bærere, der bar kisterne til {place} i sidste uge. {villain} betalte dem af egen pung, og de fortæller gerne om det og om de lyde, de hørte i gangene derude.`,`At the inn across the way some of the bearers who carried the chests to {place} last week are drinking. {villain} paid them out of {villain}’s own purse, and they will happily tell of it, and of the sounds they heard in the passages out there.`)],checks:[o(`Dexterity (Stealth)`,`easy`,a(`Heltene er inde og ude, før nogen på torvet ser dem, og intet i huset er flyttet.`,`The heroes are in and out before anyone in the square sees them, and nothing in the house is out of place.`),a(`En nabo ser lys i {villain}s vinduer og råber på vægteren. Heltene slipper væk, men rygtet når {villain}, og bærerne får besked på at holde vagt øverst på trappen til hvælvingen hele natten.`,`A neighbour sees a light in {villain}’s windows and calls the watch. The heroes get away, but word reaches {villain}, and the bearers are told to keep watch at the top of the vault stair all night.`)),o(`Wisdom (Insight)`,`medium`,a(`Portrættet og prædikenerne siger det samme: {villain} hader ikke dansen, men den nat. Den, der fortæller {villain} sandheden om bjælken, rammer dér, hvor det gør ondt.`,`The portrait and the sermons say the same thing: {villain} does not hate the dance, only that night. Whoever tells {villain} the truth about the beam strikes where it hurts.`),a(`Heltene ser kun en fanatiker. I hvælvingen møder de {villain} med trusler, og det gør kun {villain} mere sikker på, at maskerne er onde.`,`The heroes see only a fanatic. In the vault they meet {villain} with threats, which only makes {villain} surer that the masks are evil.`))],fight:!1,alternatives:[a(`Køb bærerne en omgang på kroen: De fortæller, at kisterne står ved den nordre væg, og at nøglen ligger ved trappen.`,`Buy the bearers a round at the inn: they let slip that the chests stand by the north wall and that the key lies by the stair.`)],dmNotes:a(`Lad portrættet blive hængende i spillernes hoveder: Når de møder {villain} i hvælvingen, skal de huske den unge mand i dansedragt. Det gør klimaks til en samtale og ikke kun et kup.`,`Let the portrait stay in the players’ minds: when they meet {villain} in the vault, they should remember the young man in dance costume. That makes the climax a conversation, not just a heist.`)},{kind:`combat`,at:`site`,present:[],title:a(`Trappen til hvælvingen`,`The Vault Stair`),summary:a([`Inde i {place} fører et spor af halmstrå og splinter af rødmalet træ hen til en stentrappe, der går ned mod hvælvingen.`,`Under tærsklen øverst ligger nøglen, indtil {villain} tager den med ned efter 2 timer, og for foden af trappen venter gangen, hvor en flok {foe} og {boss} holder til, og døren med {villain}s kridtskrift.`,`Det er den direkte vej og den farlige.`],[`Inside {place} a trail of straw and splinters of red-painted wood leads to a stone stair going down toward the vault.`,`Under the threshold at the top lies the key, until {villain} takes it down after 2 hours. At the foot of the stair lies the passage where a pack of {foe} and {boss} lurk, and in it the door with {villain}’s chalked words.`,`This is the direct way, and the dangerous one.`]),readAloud:a([`Hallen inden for indgangen er bar og iskold, og rimfrost glitrer på væggene.`,`Hen over fliserne løber et spor af gyldne halmstrå og små røde splinter, og det ender ved en stentrappe, der forsvinder ned i mørket.`,`Et sted dernede lyder en lang, blød skraben, og så er der stille.`],[`The hall inside the entrance is bare and freezing, and hoarfrost glitters on the walls.`,`Across the flagstones runs a trail of golden straw and small red splinters, ending at a stone stair that drops away into darkness.`,`From somewhere below comes a long, soft scraping, then silence.`]),details:[a(`Under tærsklen øverst på trappen ligger nøglen til hvælvingen. Efter 2 timer er den væk: {villain} er kommet med to bærere og holder vagt ved kisterne inde i hvælvingen, mens bærerne venter øverst på trappen ved et fyrfad og synger for at holde modet oppe.`,`Under the threshold at the top of the stair lies the key to the vault. After 2 hours it is gone: {villain} has come with two bearers and keeps vigil over the chests inside the vault, while the bearers wait at the top of the stair by a brazier, singing to keep their courage up.`),a(`For foden af trappen løber gangen forbi hvælvingens jernbeslåede dør, hvor {villain} med kridt har skrevet, at ingen må åbne, før vognen kommer. En flok {foe} holder til i sidegangene og kommer frem, når nogen bliver for længe i gangen.`,`At the foot of the stair the passage runs past the vault’s iron-bound door, where {villain} has chalked that no one is to open it before the cart comes. A pack of {foe} lurk in the side passages and come out when anyone lingers in the passage too long.`),a(`Både {boss} og flokken af {foe} hører til i {place} og tjener ingen; {villain} og bærerne slap kun forbi, fordi de gik hurtigt, med fakler og salmesang. Bærerne er folk fra byen og flygter hellere end at slås.`,`Both {boss} and the pack of {foe} belong to {place} and serve no one; {villain} and the bearers got past only because they went quickly, with torches and hymns. The bearers are townsfolk and would rather run than fight.`)],checks:[o(`Wisdom (Perception)`,`easy`,a(`Heltene ser, at én sten i tærsklen sidder løst, og finder nøglen, hvis {villain} ikke allerede har taget den.`,`The heroes see that one stone of the threshold is loose and find the key, if {villain} has not already taken it.`),a(`Heltene leder længe, før de finder den løse sten. Det koster ti minutter, og efter 2 timer finder de kun et tomt hul.`,`The heroes search a long time before they find the loose stone. It costs ten minutes, and after 2 hours they find only an empty hollow.`)),o(`Dexterity (Stealth)`,`medium`,a(`Heltene glider ned ad trappen og forbi sidegangene uden at vække noget og står ved døren med kridtskriften.`,`The heroes slip down the stair and past the side passages without waking anything and stand at the door with the chalked words.`),a(`En flok {foe} vælter ud af sidegangene. Kampen begynder i gangen foran døren, og larmen når både hvælvingen og {boss}.`,`A pack of {foe} pour out of the side passages. The fight begins in the passage before the door, and the noise reaches both the vault and {boss}.`))],fight:!0,alternatives:[a(`Tal med bærerne efter 2 timer: De er bange, kolde og dårligt betalte, og for en mønt eller et godt ord går de hjem.`,`Talk to the bearers after 2 hours: they are frightened, cold and poorly paid, and for a coin or a kind word they will go home.`),a(`Lad trappen være, og gå op i køkkenet til kulskakten; den fører ind i hvælvingen uden om gangen og {boss}.`,`Leave the stair alone and go up to the kitchen and the coal chute; it leads into the vault without passing the passage and {boss}.`)],dmNotes:a(`Lad halmsporet være heltenes første sejr: Nu ved de, at de er på rette vej. Gangen dernede skal føles som et sted, hvor ingen bliver stående.`,`Let the straw trail be the heroes’ first win: now they know they are on the right track. The passage below should feel like a place where nobody stands still.`)},{kind:`puzzle`,at:`site`,present:[],title:a(`Kulskakten`,`The Coal Chute`),summary:a([`I det tagløse køkken over hvælvingen sidder den gamle kulskakt, muret til med kun ét lag sten, som bedstefaderens tegning viser.`,`At åbne den stille, mens {boss} og en flok {foe} holder til i gangene nedenunder, er en prøve på tålmodighed: sten for sten, og hver lyd bærer ned i hvælvingen.`,`Skakten går uden om døren og {boss}, men den er smal: Kisterne kan ikke komme op ad den, kun maskerne, én ad gangen.`],[`In the roofless kitchen above the vault is the old coal chute, bricked up only one course thick, just as the grandfather’s drawing shows.`,`Opening it quietly, with {boss} and a pack of {foe} in the passages below, is a test of patience: brick by brick, with every sound carrying down into the vault.`,`The chute avoids the door and {boss}, but it is narrow: the chests cannot come up it, only the masks, one at a time.`]),readAloud:a([`Køkkenet er en tagløs skal med et koldt ildsted, der er stort nok til at stå i, og rimfrost på fliserne.`,`Lavt på den ene væg sidder en firkant af nyere mursten i den gamle sten, og mørtlen er bleg og smuldrer.`,`Gennem sprækkerne kommer kold luft med en svag lugt af halm og gammel maling.`],[`The kitchen is a roofless shell with a cold hearth big enough to stand in and hoarfrost on the flagstones.`,`Low on one wall a square of newer brick is set into the old stone, its mortar pale and crumbling.`,`Through the cracks breathes cold air with a faint smell of straw and old paint.`]),details:[a(`Murstenene kan pilles ud én ad gangen med en kniv i den smuldrende mørtel. Falder en sten ned ad skakten, kan det høres i hele hvælvingen og i gangen udenfor.`,`The bricks can be worked out one at a time with a knife in the crumbling mortar. If a brick falls down the chute, it can be heard throughout the vault and in the passage outside.`),a(`Efter 2 timer stiger {villain}s stemme op gennem sprækkerne, hæs af bønner og salmer: {villain} holder vagt lige under skakten, ved kisterne.`,`After 2 hours {villain}’s voice rises through the cracks, hoarse with prayers and hymns: {villain} is keeping vigil right below the chute, by the chests.`),a(`Skakten er for smal til kisterne. Maskerne kan rækkes op én ad gangen af en helt nedenunder og en heroppe, og det tager tid, mens {boss} og en flok {foe} er på den anden side af døren.`,`The chute is too narrow for the chests. The masks can be passed up one at a time by a hero below and a hero up here, and that takes time while {boss} and a pack of {foe} are on the other side of the door.`)],checks:[o(`Dexterity (Sleight of Hand)`,`medium`,a(`Stenene kommer ud uden en lyd, og skakten står åben, før nogen nedenunder aner noget.`,`The bricks come out without a sound, and the chute stands open before anyone below suspects a thing.`),a(`En mursten glider og rumler ned ad skakten. Alt nedenunder er advaret: Er {villain} kommet (efter 2 timer), rejser {villain} sig med lampen, og under alle omstændigheder kommer noget i gangen hen til døren.`,`A brick slips and rumbles down the chute. Everything below is warned: if {villain} has come (after 2 hours), {villain} rises with the lamp, and either way something in the passage comes to the door.`)),o(`Intelligence (Investigation)`,`easy`,a(`Heltene genkender firkanten fra bedstefaderens tegning med det samme og går i gang uden at spilde tid.`,`The heroes recognise the square from the grandfather’s drawing at once and set to work without wasting time.`),a(`Køkkenet har to tilmurede huller, og heltene åbner det forkerte, en gammel bageovn. Det koster ti minutter og noget larm.`,`The kitchen has two bricked-up openings, and the heroes open the wrong one, an old bread oven. That costs ten minutes and some noise.`))],fight:!1,alternatives:[a(`Fir en helt ned i et reb, og lad de andre danne en kæde op gennem køkkenet: Tolv masker går hurtigt, når alle hænder er med.`,`Lower a hero on a rope and have the others form a chain up through the kitchen: twelve masks go quickly when every hand helps.`),a(`Brug kun skakten til at komme ind, og bær kisterne ud ad døren med nøglen; det går hurtigere, men vejen går forbi {boss}.`,`Use the chute only to get in and carry the chests out by the door with the key; it is quicker, but the way leads past {boss}.`)],dmNotes:a(`Tæl stenene højt: Hver mursten, der kommer ud, er et lille øjebliks spænding. Har heltene hørt {villain}s stemme gennem sprækkerne, ved de, hvem der venter dernede.`,`Count the bricks out loud: every brick that comes free is a small moment of tension. If the heroes have heard {villain}’s voice through the cracks, they know who is waiting below.`)}],climax:{kind:`climax`,at:`site`,present:[`villain`],title:a(`Tolv masker`,`Twelve Masks`),summary:a([`I hvælvingen under {place} står de tre kister ved den nordre væg, og fra 2 timer til daggry holder {villain} vagt ved dem med lampe og salmebog, med døren låst og nøglen i lommen.`,`{boss} og en flok {foe} hører til i gangene udenfor og tjener ingen; døren holder dem ude og dermed også væk fra {villain}.`,`Heltene skal have maskerne ud, op ad skakten én ad gangen eller i kisterne forbi {boss}, mens {villain} hellere vil sætte ild til halmen end lade maskerne gå.`],[`In the vault beneath {place} the three chests stand by the north wall, and from the 2-hour mark until dawn {villain} keeps vigil over them with lamp and hymnal, the door locked and the key in their pocket.`,`{boss} and a pack of {foe} belong to the passages outside and serve no one; the door keeps them out, and so away from {villain} too.`,`The heroes must get the masks out, up the chute one at a time or in their chests past {boss}, while {villain} would rather set the straw alight than let the masks go.`]),readAloud:a([`Hvælvingen er lav og så kold, at ånden står som røg.`,`Tre kister står åbne langs den nordre væg, og i lyset fra en enkelt lampe ser udskårne ansigter af harer, hjorte og leende mænd op af halmen.`,`Foran dem knæler en skikkelse i sort med én maske i begge hænder, og en hæs stemme går i stå midt i en bøn.`],[`The vault is low and so cold that breath hangs like smoke.`,`Three chests stand open along the north wall, and in the light of a single lamp carved faces of hares, stags and laughing men look up out of the straw.`,`Before them kneels a figure in black holding one mask in both hands, and a hoarse voice stops in the middle of a prayer.`]),details:[a(`Masken i {villain}s hænder er den gamle hare med det revnede øre, broderens maske. Kommer heltene før 2 timer, er hvælvingen mørk og tom, og de har til 2 timer; så kommer {villain} ned ad trappen med lampe og salmesang, og er de derinde endnu, står {villain} i døren. Bærerne bliver oppe ved trappen.`,`The mask in {villain}’s hands is the old hare with the cracked ear, the brother’s mask. If the heroes come before 2 hours have passed, the vault is dark and empty; when the 2 hours are up, {villain} comes down the stair with lamp and hymn, and if they are still inside, {villain} stands in the doorway. The bearers stay up at the top of the stair.`),a(`Larm trækker {boss} og en flok {foe} hen til døren, og åbner nogen den, kommer de ind og går lige så gerne efter {villain} som efter heltene. Gennem skakten kan to helte, der ikke laver andet, få to masker op hver runde.`,`Noise draws {boss} and a pack of {foe} to the door, and if anyone opens it, they come in and go for {villain} as readily as for the heroes. Through the chute, two heroes who do nothing else can get two masks up each round.`),a(`Truer heltene med at tage maskerne, holder {villain} lampen over halmen. Hører {villain} sandheden om den rådne bjælke fra {npc3}, eller fra heltene med {npc3}s egne ord, sænker {villain} lampen. Efter 4 timer er vognen på vej, og når den kommer, låser {villain} op for bærerne.`,`If the heroes threaten to take the masks, {villain} holds the lamp over the straw. If {villain} hears the truth about the rotten beam from {npc3}, or from the heroes in {npc3}’s own words, {villain} lowers the lamp. After 4 hours the cart is on its way, and when it comes, {villain} unlocks the door for the bearers.`)],checks:[o(`Charisma (Persuasion)`,`hard`,a(`{villain} sænker lampen og sidder længe med haren i hænderne. Så rækker {villain} den frem og hjælper selv med at bære maskerne ud.`,`{villain} lowers the lamp and sits a long while with the hare in both hands. Then {villain} holds it out and helps carry the masks out.`),a(`{villain} kaster lampen i halmen. Én kiste fænger, og heltene har en runde til at slå flammerne ud, før dens fire masker brænder.`,`{villain} throws the lamp into the straw. One chest catches, and the heroes have one round to beat out the flames before its four masks burn.`)),o(`Dexterity (Acrobatics)`,`medium`,a(`En helt når {villain} i ét spring og har lampen, før den rammer halmen.`,`A hero reaches {villain} in a single bound and has the lamp before it touches the straw.`),a(`Lampen glider ud af hænderne, og halmen fænger i én kiste. Flammerne kan slås ud, men det koster en runde, og røgen trækker ud under døren til gangen.`,`The lamp slips away, and the straw in one chest catches. The flames can be beaten out, but it costs a round, and the smoke drifts under the door into the passage.`))],fight:!0,alternatives:[a(`Lad {villain} selv bære harens maske ud: Det er begyndelsen på den samtale, {npc3} har ventet tyve år på.`,`Let {villain} carry the hare mask out in person: it is the beginning of the conversation {npc3} has waited twenty years for.`),a(`Tag kisterne ud ad døren med nøglen fra {villain}s lomme: Alle tolv masker kommer ud på én gang, men vejen går forbi {boss}.`,`Take the chests out by the door with the key from {villain}’s pocket: all twelve masks go at once, but the way leads past {boss}.`)],dmNotes:a(`Hjertet i scenen er {villain}s sorg: Lad {villain} sige broderens navn. Er {npc3} med, så giv fordel på at overtale {villain}; trusler gør kun {villain} mere sikker på, at maskerne er onde.`,`The heart of the scene is {villain}’s grief: let {villain} speak the brother’s name. If {npc3} is there, give advantage on persuading {villain}; threats only make {villain} surer that the masks are evil.`)}}},c=e=>Array.isArray(e)?e.join(` `):e,l=(e,t)=>({da:c(e),en:c(t)}),u=(e,t,n,r)=>({skill:e,level:t,success:n,failure:r}),d={"escort-last-will":{opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`,`npc3`],title:l(`Vognen ved købmandens dør`,`The Coach at the Merchant’s Door`),summary:l([`Om morgenen står vognen klar ved {npc2}s hus, og {npc1}, forstander for fattighuset i {town}, beder heltene følge {npc2} til notaren før solnedgang; fattighuset kan ikke betale, men lover dem husly, så længe det står.`,`{npc2} er syg, stædig og langsom og har det nye testamente i inderlommen, og kusken {npc3} har allerede spændt for.`,`Her overtager heltene ansvaret for den gamle købmand og får de første tegn på, at nogen ikke ønsker, at de når frem.`],[`In the morning the coach stands ready at {npc2}’s house, and {npc1}, warden of the poorhouse in {town}, asks the heroes to see {npc2} to the notary before sunset; the poorhouse cannot pay, but promises them shelter for as long as it stands.`,`{npc2} is ill, stubborn and slow, with the new will in an inside pocket, and {npc3}, the coachman, already has the horses in harness.`,`Here the heroes take the old merchant into their care and see the first signs that someone does not want them to arrive.`]),readAloud:l([`En lukket vogn holder i den frosne gård, og hestenes ånde damper i den kolde luft.`,`I døren står en gammel købmand i en tung pelskappe, støttet til en stok, og klapper sig på brystet, som for at mærke efter, at noget stadig ligger i inderlommen.`,`Kusken sidder allerede på bukken og stirrer ned i tøjlerne.`],[`A closed coach stands in the frozen yard, and the horses’ breath steams in the cold air.`,`In the doorway stands an old merchant in a heavy fur cloak, leaning on a stick and patting their chest, as if to make sure something is still in the inside pocket.`,`The coachman already sits on the box, staring down at the reins.`]),details:[l(`{npc2} fortæller gerne, at {villain} blev rasende, da testamentet blev nævnt ved middagen i går, og red bort samme aften. {npc2} vil ikke skifte mening, men vil gerne se sit barn i øjnene én gang til, før alt er afgjort.`,`{npc2} readily tells how {villain} flew into a rage when the will was mentioned at dinner yesterday and rode off the same evening. {npc2} will not change their mind, but would like to look their child in the eye once more before everything is settled.`),l(`I inderlommen har {npc2} også notarens brev: Kontoret i {town} lukker ved solnedgang og åbner først igen til foråret, og testamentet skal underskrives dér for notaren og to vidner. Der er ti timer til solnedgang, og vejen går forbi {place}.`,`In the inside pocket {npc2} also keeps the notary’s letter: the office in {town} closes at sunset and does not open again until spring, and the will must be signed there before the notary and two witnesses. There are ten hours until sunset, and the road runs past {place}.`),l(`{npc1} er urolig: Forstanderen har i månedsvis talt med {npc2} om testamentet og frygter, at {villain} vil kalde det at udnytte en syg gammel købmand. {npc3} har kørt for {npc2} i tyve år, og den venstre forsko sidder løst, men det ser kun den, der kigger efter.`,`{npc1} is uneasy: the warden has talked with {npc2} about the will for months and fears {villain} will call it preying on a sick old merchant. {npc3} has driven for {npc2} for twenty years, and the left forefoot shoe is loose, but only someone who looks closely will notice.`)],checks:[u(`Wisdom (Animal Handling)`,`medium`,l(`Heltene ser, at den venstre forsko sidder løst, og at sømmene er trukket halvt ud med en tang, ikke slidt løse.`,`The heroes notice that the left forefoot shoe is loose, its nails drawn halfway out with pincers, not worn loose.`),l(`Heltene ser intet; to timer ude ad vejen falder skoen af.`,`The heroes notice nothing; two hours down the road the shoe comes off.`)),u(`Wisdom (Insight)`,`medium`,l(`Kusken er bange og skyldbevidst og kan ikke se den gamle købmand i øjnene; noget tynger {npc3}.`,`The coachman is frightened and guilty and cannot look the old merchant in the eye; something weighs on {npc3}.`),l(`{npc3} virker bare tavs og træt, som kuske plejer at være før en lang tur.`,`{npc3} just seems quiet and tired, as coachmen often are before a long drive.`))],fight:!1,alternatives:[l(`Sko hesten om, før I kører: Det koster en halv time nu, men vognen holder farten hele vejen.`,`Reshoe the horse before setting out: it costs half an hour now, but the coach keeps its pace all the way.`),l(`Kør selv, og sæt {npc3} ind i vognen: Kusken protesterer, men kan ikke længere vælge vej eller tempo.`,`The heroes drive the coach themselves and put {npc3} inside: the coachman protests, but can no longer choose the road or the pace.`)],dmNotes:l(`Lad spillerne mærke, hvor skrøbelig {npc2} er: Trappen ned til vognen tager lang tid, og hvert bump på vejen koster et host. Det er ikke en vagt, de skal stå, men en gammel, de skal have frem.`,`Let the players feel how frail {npc2} is: the steps down to the coach take a long time, and every bump in the road costs a cough. This is not guard duty; it is an old life they must carry through.`)},middle:[{kind:`rest`,at:`town`,present:[`npc2`,`npc3`],title:l(`Kroen ved vejen`,`The Roadside Inn`),summary:l([`To timer ude ad vejen falder den løse hestesko af, og vognen humper ind i gården ved kroen ved vejen, hvor en smed kan sko hesten om på en halv time.`,`Mens {npc2} får varmen ved ilden, ligger tre spor klar: en lap papir med {villain}s segl i kuskens jakke, et gammelt vejkort over skænken og notarens skriver ved et af bordene.`,`Scenen samler mistanken om {villain} og giver heltene et valg om vejen forbi {place}.`],[`Two hours down the road the loose horseshoe comes off, and the coach limps into the yard of the roadside inn, where a smith can reshoe the horse in half an hour.`,`While {npc2} warms up by the fire, three clues lie ready: a slip of paper with {villain}’s seal in the coachman’s jacket, an old road map above the bar, and the notary’s clerk at one of the tables.`,`The scene focuses suspicion on {villain} and gives the heroes a choice about the road past {place}.`]),readAloud:l([`Kroen er lav og røget, og ilden knitrer i en stor, åben pejs.`,`Over skænken hænger et falmet vejkort med kongevejen tegnet med rødt og en tynd, stiplet sti, der bøjer syd om {place}.`,`Ude fra gården lyder hammerslag fra smedjen, og ved ilden damper kuskens våde jakke.`],[`The inn is low and smoky, and a fire crackles in a big open hearth.`,`Above the bar hangs a faded road map, the king’s road drawn in red and a thin dotted path bending south around {place}.`,`From the yard come the hammer blows of the forge, and by the fire the coachman’s wet jacket steams.`]),details:[l(`I kuskens jakke ligger en lap papir med {villain}s segl, der betaler {npc3} for at tage vejen forbi {place} og lade hesteskoen sidde løst; resten af pengene kommer først, når den gamle er hjemme igen efter solnedgang. Stillet over for papiret tilstår {npc3} alt og beder om tilgivelse.`,`In the coachman’s jacket lies a slip of paper with {villain}’s seal, instructing {npc3} to take the road past {place} and leave the horseshoe loose; the rest of the money comes only once the old merchant is home again after sunset. Faced with the paper, {npc3} confesses everything and asks for forgiveness.`),l(`Vejkortet viser gangstien syd om {place}: stejl og ikke for vogne, men den sparer en time. {npc2} kan ikke gå langt, så stien kræver, at den gamle bliver båret eller sidder på en hest, der føres i skridt.`,`The road map shows the footpath south of {place}: steep and no good for wagons, but it saves an hour. {npc2} cannot walk far, so the path means carrying the old merchant or leading a horse at a walk.`),l(`Ved et af bordene sidder notarens skriver på vej hjem til {town} og fortæller gerne, at {villain} kom forbi kontoret i går og spurgte, hvornår det lukker for vinteren.`,`At one of the tables sits the notary’s clerk, on the way home to {town}, who readily says that {villain} came by the office yesterday asking when it closes for the winter.`)],checks:[u(`Dexterity (Sleight of Hand)`,`easy`,l(`Heltene får papiret op af jakkelommen, uden at nogen ser det.`,`The heroes get the paper out of the jacket pocket without anyone seeing.`),l(`{npc3} kommer ind fra gården, mens heltene står ved jakken; kusken bliver bleg og må nu enten tilstå eller flygte ud i kulden.`,`{npc3} comes in from the yard while the heroes stand by the jacket; the coachman goes pale and must now either confess or flee into the cold.`)),u(`Charisma (Persuasion)`,`easy`,l(`Skriveren rider i forvejen til {town} og vil gerne stå klar som det ene af de to vidner.`,`The clerk rides ahead to {town} and gladly agrees to stand ready as one of the two witnesses.`),l(`Skriveren har travlt og rider videre; heltene må selv finde to vidner, når de når {town}.`,`The clerk is in a hurry and rides on; the heroes must find two witnesses themselves when they reach {town}.`))],fight:!1,alternatives:[l(`Lad {npc2} selv bede kusken tømme lommerne: {npc3} kan ikke sige nej til en gammel arbejdsgiver efter tyve år.`,`Let {npc2} ask the coachman to empty their pockets: {npc3} cannot refuse an old employer of twenty years.`),l(`Spring kroen over, og kør videre med den halte hest: Heltene sparer tiden her, men vognen kryber frem mod {place}.`,`Skip the inn and drive on with the lame horse: the heroes save the time here, but the coach crawls on toward {place}.`)],dmNotes:l(`Kroen er et åndehul: Lad {npc2} få varmen og fortælle om {villain} som barn, så spillerne forstår, at det er en familie, der går i stykker, ikke kun en arv.`,`The inn is a breathing space: let {npc2} warm up and talk about {villain} as a child, so the players understand that this is about a family breaking apart, not just an inheritance.`)},{kind:`combat`,at:`site`,present:[`npc2`,`npc3`],title:l(`Rebet i vejkanten`,`The Rope by the Roadside`),summary:l([`Lige inde i {place} ligger vejen fuld af friske stenskår, og i vejkanten ligger et reb rullet sammen, klar til at blive trukket over vejen i hestehøjde.`,`Der er blevet helt stille, og nogle {foe} holder udkig fra skrænten, klar til at blæse i et horn, når vognen kommer.`,`Tager heltene udkigsposterne i stilhed, mister bagholdet længere inde sin fordel.`],[`Just inside {place} the road is littered with fresh stone chips, and a coil of rope lies at the roadside, ready to be pulled across the road at horse height.`,`Everything has gone very quiet, and some {foe} keep watch from the slope, ready to blow a horn when the coach comes.`,`If the heroes deal with the lookouts quietly, the ambush further in loses its edge.`]),readAloud:l([`Vejen snævrer ind mellem to skrænter, og under hjulene knaser friske stenskår.`,`Ingen fugle synger, og ved vejkanten ligger et tykt reb rullet sammen med den ene ende bundet om en træstub.`,`Højt oppe på skrænten bevæger noget sig og er væk igen.`],[`The road narrows between two slopes, and fresh stone chips crunch under the wheels.`,`No birds sing, and at the roadside lies a thick coil of rope, one end tied round a tree stump.`,`High up on the slope something moves and is gone again.`]),details:[l(`Stenskårene stammer fra de sten, der er væltet ned for at spærre vejen længere inde, og rebet skal trækkes over vejen i hestehøjde bag vognen, så den ikke kan vende om. Bagholdet venter dér, hvor vejen er smallest.`,`The stone chips come from the rocks rolled down to block the road further in, and the rope is to be pulled across the road at horse height behind the coach, so that it cannot turn back. The ambush waits where the road is narrowest.`),l(`Udkigsposterne er nogle {foe}, som {villain} har lejet sammen med resten af bagholdet. Bliver de tavse, før de får blæst i hornet, ved {boss} ikke, at vognen er her, før den ruller ind i snævringen.`,`The lookouts are some {foe} that {villain} hired along with the rest of the ambush. If they are silenced before they can blow the horn, {boss} does not know the coach is here until it rolls into the narrows.`),l(`Vognen når hertil efter omkring fem timer, og bagholdet springer, så snart den er inde i snævringen (andet tik). Notaren rejser ved solnedgang, fem timer senere.`,`The coach gets here after about five hours, and the ambush springs as soon as it is in the narrows (the second tick). The notary leaves at sunset, five hours later.`)],checks:[u(`Dexterity (Stealth)`,`medium`,l(`Heltene kommer op ad skrænten bag udkigsposterne og tager dem, før hornet bliver blæst.`,`The heroes climb the slope behind the lookouts and take them before the horn is blown.`),l(`Hornet lyder hult mellem skrænterne; bagholdet længere inde er klar, når vognen kommer.`,`The horn sounds hollow between the slopes; the ambush further in is ready when the coach comes.`)),u(`Wisdom (Survival)`,`easy`,l(`Sporene viser, at mange har ventet længere inde siden daggry, og at én kom til hest og bandt dyret i skjul.`,`The tracks show that many have waited further in since dawn, and that one came on horseback and tied the animal out of sight.`),l(`Heltene ser kun stenskårene og rebet; resten må de møde, når de kommer derind.`,`The heroes see only the stone chips and the rope; they will meet the rest when they get there.`))],fight:!0,alternatives:[l(`Skær rebet over: Så kan bagholdet ikke lukke vejen bag vognen, og heltene kan vende om, hvis det går galt.`,`Cut the rope: then the ambush cannot close the road behind the coach, and the heroes can turn back if things go wrong.`),l(`Bluf udkigsposterne: Med {villain}s segl fra kuskens papir kan heltene påstå, at de har bud fra den, der betaler.`,`Bluff the lookouts: with {villain}’s seal from the coachman’s paper, the heroes can claim to bring word from whoever is paying.`)],dmNotes:l(`Stilheden er en advarsel; beskriv den. Har spillerne fundet gangstien på kroen, så mind dem om, at den findes, men at vognen ikke kan tage den.`,`The silence is a warning; describe it. If the players found the footpath at the inn, remind them that it exists, but that the coach cannot take it.`)},{kind:`exploration`,at:`site`,present:[`villain`],title:l(`Den tøjrede hest`,`The Tethered Horse`),summary:l([`Går heltene i forvejen til fods, finder de snævringen, hvor vejen er spærret med sten, og jorden er trampet op af mange fødder.`,`I krattet over vejen står en sadlet hest tøjret i skjul, og ved en kold bålplads ligger en tom pung med {villain}s monogram; her har nogen ventet længe.`,`Scenen lader heltene se bagholdet, før det ser dem, og afgøre, hvordan vognen skal ind i snævringen.`],[`If the heroes go ahead on foot, they find the narrows, where the road is blocked with stones and the ground is trampled by many feet.`,`In the thicket above the road a saddled horse stands tethered out of sight, and by a cold fire pit lies an empty purse with {villain}’s monogram; someone has waited here a long time.`,`The scene lets the heroes see the ambush before it sees them, and decide how the coach is to enter the narrows.`]),readAloud:l([`Bag et sving er vejen spærret af en mur af væltede sten, og gruset foran den er trampet op af mange fødder.`,`Oppe i krattet står en sadlet hest tøjret til en birk og tygger utålmodigt på bidslet.`,`Ved en kold bålplads lige ved siden af ligger en tom læderpung med et broderet monogram.`],[`Beyond a bend the road is blocked by a wall of tumbled stones, and the gravel before it is trampled by many feet.`,`Up in the thicket a saddled horse stands tethered to a birch, champing impatiently at the bit.`,`By a cold fire pit right next to it lies an empty leather purse with an embroidered monogram.`]),details:[l(`Bagholdet ligger på begge skrænter over snævringen og venter på vognen; helte, der kommer til fods og i stilhed, bliver ikke set, med mindre de går ned på vejen.`,`The ambush lies on both slopes above the narrows, waiting for the coach; heroes who come quietly on foot are not seen unless they step down onto the road.`),l(`Hesten er {villain}s, og pungen er den, {villain} betalte bagholdet med. {villain} selv ligger på lur et stykke højere oppe for at se det ske og ride frem som "redningsmand", når vognen holder.`,`The horse is {villain}’s, and the purse is the one {villain} paid the ambush from. {villain} lies in wait a little higher up, to watch it happen and ride out as the "rescuer" once the coach stops.`),l(`Tager heltene hesten, kan {villain} ikke ride frem som redningsmand, og hesten kan senere spændes for vognen i stedet for den halte. Men en hest, der forsvinder, bliver opdaget, og så ved {villain}, at nogen er på sporet.`,`If the heroes take the horse, {villain} cannot ride out as the rescuer, and the horse can later be harnessed in place of the lame one. But a vanished horse is noticed, and then {villain} knows someone is on the trail.`)],checks:[u(`Dexterity (Stealth)`,`medium`,l(`Heltene ser, hvor mange der ligger på skrænterne, og hvor {villain} har sit skjul, uden selv at blive set.`,`The heroes see how many lie on the slopes and where {villain} is hiding, without being seen themselves.`),l(`En sten triller ned på vejen; bagholdet er nu på vagt, og {villain} trækker sig længere op i krattet.`,`A stone rolls down onto the road; the ambush is now on guard, and {villain} pulls back higher into the thicket.`)),u(`Wisdom (Animal Handling)`,`easy`,l(`Heltene får hesten løs uden en lyd, og den følger villigt med.`,`The heroes untie the horse without a sound, and it follows willingly.`),l(`Hesten vrinsker højt; bagholdet kigger op, og heltene må trække sig i en fart.`,`The horse whinnies loudly; the ambush looks up, and the heroes must pull back in a hurry.`))],fight:!1,alternatives:[l(`Lad vognen vente uden for snævringen, og tag {npc2} ad gangstien syd om {place}, mens bagholdet venter forgæves; det er hårdt for den gamle, men sparer en time.`,`Leave the coach outside the narrows and take {npc2} along the footpath south of {place} while the ambush waits in vain; it is hard on the old merchant, but saves an hour.`),l(`Vend fælden om: Når vognen ruller ind, ligger heltene allerede på skrænterne bag bagholdet.`,`Turn the trap around: when the coach rolls in, the heroes are already on the slopes behind the ambush.`)],dmNotes:l(`Lad spillerne planlægge her; det er den bedste chance for at vende bagholdet. Jo mere de ved, jo kortere og lettere bliver kampen ved stenene.`,`Let the players plan here; it is their best chance to turn the ambush around. The more they know, the shorter and easier the fight at the stones.`)}],climax:{kind:`climax`,at:`site`,present:[`npc2`,`npc3`,`villain`],title:l(`Redningsmanden i snævringen`,`The Rescuer in the Narrows`),summary:l([`Hvor vejen gennem {place} er smallest, er den spærret med sten, og {boss} og nogle af {villain}s lejede {foe} angriber vognen fra begge skrænter.`,`{villain} venter i skjul med en tøjret hest, og når vognen holder, rider {villain} frem som "redningsmand" for at køre den syge gamle hjem, mens solen går ned over notarens kontor.`,`Heltene skal holde bagholdet stangen, nægte at udlevere {npc2} og få den gamle videre mod {town} i tide.`],[`Where the road through {place} is narrowest it is blocked with stones, and {boss} and some of {villain}’s hired {foe} attack the coach from both slopes.`,`{villain} waits out of sight with a tethered horse, and once the coach stops, {villain} rides out as the "rescuer" to drive the invalid home while the sun sets on the notary’s office.`,`The heroes must hold off the ambush, refuse to hand {npc2} over and get the old merchant on toward {town} in time.`]),readAloud:l([`Vejen ender blindt ved en mur af væltede sten, og hestene stejler.`,`Fra begge skrænter kommer skikkelser løbende ned mod vognen.`,`Inde i vognen griber {npc2} om inderlommen og hoster.`],[`The road ends blind at a wall of tumbled stones, and the horses rear.`,`From both slopes figures come running down toward the coach.`,`Inside the coach {npc2} clutches their inside pocket and coughs.`]),details:[l(`{boss} og resten af bagholdet er lejet af {villain} til at standse vognen og skræmme den gamle, ikke til at slå nogen ihjel; når {villain} rider frem, trækker de sig som aftalt. Møder de hård modstand, glemmer de aftalen.`,`{boss} and the rest of the ambush are hired by {villain} to stop the coach and frighten the old merchant, not to kill anyone; when {villain} rides out, they fall back as agreed. Against hard resistance, they forget the agreement.`),l(`Når vognen holder, rider {villain} frem fra krattet, råber, at angriberne flygter, og insisterer på at køre {npc2} hjem "for at hvile". Bliver {villain} stillet ansigt til ansigt med {npc2}, kan {villain} ikke lyve, og papiret fra kuskens lomme er nok til at gøre {villain} arveløs. Har heltene taget hesten, må {villain} komme til fods.`,`Once the coach stops, {villain} rides out of the thicket, shouts that the attackers are fleeing and insists on driving {npc2} home "to rest". Brought face to face with {npc2}, {villain} cannot lie, and the paper from the coachman’s pocket is enough to have {villain} disinherited. If the heroes took the horse, {villain} has to come on foot.`),l(`Stenene skal ryddes, før vognen kommer forbi, og det tager en halv time; {villain}s hest kan spændes for i stedet for den halte. Har heltene taget gangstien syd om {place}, rider {villain} dem i møde, hvor stien når vejen igen, og bagholdet følger efter.`,`The stones must be cleared before the coach can pass, which takes half an hour; {villain}’s horse can be harnessed in place of the lame one. If the heroes took the footpath south of {place}, {villain} rides to meet them where the path rejoins the road, and the ambush follows.`)],checks:[u(`Wisdom (Perception)`,`medium`,l(`Heltene får øje på {villain} i krattet, før {villain} rider frem, og ved, hvem "redningsmanden" er.`,`The heroes spot {villain} in the thicket before {villain} rides out, and know who the "rescuer" is.`),l(`{villain} rider frem uden varsel og står ved vognsdøren, før heltene forstår, hvad der sker.`,`{villain} rides out without warning and is at the coach door before the heroes understand what is happening.`)),u(`Charisma (Persuasion)`,`medium`,l(`Heltene stiller {villain} ansigt til ansigt med {npc2} med papiret fra kuskens lomme i hånden; {villain} kan ikke lyve sin gamle forælder op i ansigtet, kalder bagholdet af og bryder sammen.`,`The heroes bring {villain} face to face with {npc2}, the paper from the coachman’s pocket in hand; {villain} cannot lie to the old parent’s face, calls off the ambush and breaks down.`),l(`{villain} vender hesten og rider mod {town} for at nå notaren først med sin egen udgave af sagen, mens {boss} angriber.`,`{villain} turns the horse and rides for {town} to reach the notary first with another version of events, while {boss} attacks.`))],fight:!0,alternatives:[l(`Lad {npc2} selv tale: Når den gamle står i vognsdøren og ser sit barn i øjnene, kan {villain} hverken lyve eller give ordre til at angribe.`,`Let {npc2} speak: when the old merchant stands in the coach door and looks their child in the eye, {villain} can neither lie nor order an attack.`),l(`Byd mere end {villain}: Bagholdet er lejet for penge, ikke af troskab, og en tykkere pung får {boss} og resten til at forsvinde op ad skrænten.`,`Outbid {villain}: the ambush is hired for coin, not loyalty, and a fatter purse sends {boss} and the rest back up the slope.`)],dmNotes:l(`Det her er en familietragedie, ikke kun en kamp: {npc2} lovede engang {villain} hele forretningen, og det ved de begge. Hold kampen kort og hård, og giv mødet mellem dem tid; det er det, spillerne vil huske.`,`This is a family tragedy, not just a fight: {npc2} once promised {villain} the whole business, and both of them know it. Keep the fight short and hard, and give their meeting time; that is what the players will remember.`)}},"escort-forged-war":{opening:{kind:`opening`,at:`town`,present:[`npc1`,`npc2`,`villain`],title:l(`Grænsestenen ved første lys`,`The Border Stone at First Light`),summary:l([`Ved første lys står heltene ved grænsestenen sammen med {npc1}, et rådsmedlem i {town}, der vil have fred og har hyret dem til at bringe våbenhvilen til rådet før solnedgang.`,`{npc2}, en ung tolk, kommer udmattet over grænsen med klanernes underskrevne våbenhvile syet ind i kappen, og kort efter ruller en venlig købmand, {villain}, op ad vejen med en tung vogn og beder om at måtte slutte sig til følget.`,`{npc1} må tilbage og holde rådet samlet, så her overtager heltene ansvaret for tolken og for alt, der følger med på vejen.`],[`At first light the heroes stand at the border stone with {npc1}, a councillor of {town} who wants peace and has hired them to bring the truce to the council before sunset.`,`{npc2}, a young interpreter, comes across the border exhausted, the clans’ signed truce sewn into {npc2}’s cloak, and soon after a friendly merchant, {villain}, rolls up with a heavy wagon and asks to join the party.`,`{npc1} must ride back to hold the council together, so here the heroes take charge of the interpreter and of everything that travels with them.`]),readAloud:l([`Grænsestenen står skæv og mosgroet i det grå morgenlys, og ned ad stien fra den anden side kommer en ung skikkelse vaklende med kappen trukket tæt om sig.`,`Bag heltene knirker et par hjul: En tung vogn med en rød presenning kommer op ad vejen, og købmanden på bukken vinker muntert.`,`Langt borte ligger {place} som et mørkt bånd under morgentågen.`],[`The border stone stands crooked and mossy in the grey morning light, and down the path from the far side a young figure comes stumbling, cloak pulled tight.`,`Behind you wheels creak: a heavy wagon with a red tarpaulin comes up the road, and the merchant on the box waves cheerfully.`,`Far off, {place} lies like a dark band under the morning mist.`]),details:[l(`Våbenhvilen er syet ind i {npc2}s kappe. Tolken kender {villain} som en venlig handelsmand fra klanernes side af grænsen og har allerede fortalt købmanden, hvor dokumentet er gemt; det siger {npc2} kun, hvis nogen spørger.`,`The truce is sewn into {npc2}’s cloak. The interpreter knows {villain} as a friendly trader from the clans’ side of the border and has already told the merchant where the document is hidden; {npc2} only admits this if someone asks.`),l(`{npc2} har en lille skitse af vejen, som klanernes høvding har lavet: Følg den gamle vej uden om {place}, og tag aldrig vejen gennem {place}. Rådet i {town} stemmer om krig ved solnedgang, om tolv timer.`,`{npc2} carries a little sketch of the road made by the clans’ chief: follow the old road around {place}, and never take the way through {place}. The council of {town} votes on war at sunset, twelve hours from now.`),l(`{npc1} kender {villain} som byens våbenleverandør og hilser lidt for hurtigt; rådsmedlemmet købte selv pile af {villain} sidste forår og vil helst ikke have handlerne gennemgået.`,`{npc1} knows {villain} as the town’s arms supplier and greets the merchant a little too quickly; the councillor bought arrows from {villain} last spring and would rather the dealings were not looked into.`)],checks:[u(`Wisdom (Insight)`,`medium`,l(`Købmandens venlighed virker ægte nok, men blikket søger hele tiden hen mod {npc2}s kappe.`,`The merchant seems genuinely friendly, but their eyes keep drifting to {npc2}’s cloak.`),l(`{villain} virker som en rar handelsmand, der bare er glad for selskab på en farlig vej.`,`{villain} seems a pleasant trader, simply glad of company on a dangerous road.`)),u(`Charisma (Persuasion)`,`easy`,l(`{npc2} fortæller frit om rejsen, om skitsen fra høvdingen og om den halvdel af familien, der bor hos klanerne; fra nu af stoler tolken på heltene.`,`{npc2} talks freely about the journey, the chief’s sketch and the half of their family that lives among the clans; from now on the interpreter trusts the heroes.`),l(`{npc2} er for træt til at tale og holder sig tæt til den venlige købmand, der byder på brød og en plads på vognen.`,`{npc2} is too tired to talk and keeps close to the friendly merchant, who offers bread and a seat on the wagon.`))],fight:!1,alternatives:[l(`Afvis købmanden høfligt: {villain} følger alligevel efter på afstand og indhenter følget ved vejkorset med en god undskyldning.`,`Turn the merchant away politely: {villain} follows at a distance anyway and catches up with the party at the crossroads with a good excuse.`),l(`Flyt våbenhvilen: Sprættes dokumentet ud af kappen og gemmes hos en af heltene, griber {villain} senere efter den forkerte kappe.`,`Move the truce: if the document is unpicked from the cloak and hidden on one of the heroes, {villain} later grabs for the wrong cloak.`)],dmNotes:l(`Spil {villain} som den rareste person på hele vejen: hjælpsom, morsom og gavmild. Spillerne skal kunne lide købmanden, før de begynder at tvivle.`,`Play {villain} as the nicest person on the whole road: helpful, funny and generous. The players should like the merchant before they begin to doubt.`)},middle:[{kind:`social`,at:`town`,present:[`npc2`,`npc3`,`villain`],title:l(`Klanspejderen ved vejkorset`,`The Clan Scout at the Crossroads`),summary:l([`To timer ude ad vejen når følget et vejkors, hvor en genvej drejer ind mod {place}, og {villain} foreslår ivrigt at tage den, fordi den "sparer tre timer", og byder {npc2} en plads på vognen.`,`Ved vejkorset træder {npc3}, en klanspejder, frem fra sit skjul og genkender købmanden, og samtidig kommer rådets bud ridende fra {town}.`,`Her skal heltene vælge vej, og her kan de for første gang se, hvem {villain} i virkeligheden er.`],[`Two hours down the road the party reaches a crossroads where a short cut turns off toward {place}, and {villain} eagerly suggests taking it because it "saves three hours", offering {npc2} a seat on the wagon.`,`At the crossroads {npc3}, a clan scout, steps out of hiding and recognises the merchant, and at the same time the council’s runner comes riding from {town}.`,`Here the heroes must choose their road, and here they get their first glimpse of who {villain} really is.`]),readAloud:l([`Ved vejkorset står en gammel vejviser, og den ene arm peger ind mod {place} ad et smalt hjulspor.`,`Købmanden har allerede drejet vognen halvt ind på genvejen, og presenningen over lasten er bundet ekstra stramt.`,`Bag et stendige rejser en skikkelse i en grå kappe sig med hånden løftet til tegn på fred.`],[`At the crossroads stands an old signpost, one arm pointing toward {place} along a narrow cart track.`,`The merchant has already turned the wagon halfway onto the short cut, and the tarpaulin over the load is lashed down extra tight.`,`Behind a stone wall a figure in a grey cloak rises, one hand lifted in a sign of peace.`]),details:[l(`{npc3} har fulgt tolken et stykke af vejen og genkender {villain}: Købmanden har solgt våben til begge sider af krigen. Spejderen vil se {villain} stå til regnskab over for begge sider, men vil ikke med ind i {town}; {npc3} var selv med i det sidste overfald på byens udkant og er bange for at blive genkendt.`,`{npc3} has followed the interpreter part of the way and recognises {villain}: the merchant has sold weapons to both sides of the war. The scout wants to see {villain} answer to both sides, but will not come into {town}; {npc3} took part in the last raid on the edge of town and is afraid of being recognised.`),l(`Rådets bud fortæller, at {villain} har bedt om ordet som den første ved aftenens rådsmøde. {npc2}s skitse fra høvdingen siger det modsatte af købmanden: Tag aldrig vejen gennem {place}.`,`The council’s runner says {villain} has asked to speak first at the evening session. {npc2}’s sketch from the chief says the opposite of the merchant: never take the way through {place}.`),l(`Under den stramme presenning ligger ikke klæde og salt, men bundter af nye spyd med byens stempel. I vognens kasse ligger {villain}s regnskabsbog, og på bukken hænger {villain}s taske med et brev med klanernes røde segl, skåret i træ og ikke i ben. Det kræver, at nogen kigger, mens {villain} hjælper {npc2} op på vognen.`,`Under the tight tarpaulin there is no cloth or salt, only bundles of new spears stamped with the town’s mark. In the wagon’s box lies {villain}’s account book, and {villain}’s satchel, hanging from the driving seat, holds a letter bearing the clans’ red seal, cut in wood, not bone. Someone has to look while {villain} is helping {npc2} up onto the wagon.`)],checks:[u(`Charisma (Persuasion)`,`medium`,l(`{npc3} fortæller i enrum, hvad spejderen ved: {villain} solgte spyd til klanerne i foråret, og ingen klan sender et brev uden et segl skåret i ben.`,`{npc3} tells the heroes in private what the scout knows: {villain} sold spears to the clans in the spring, and no clan sends a letter without a seal cut in bone.`),l(`{npc3} stoler ikke på folk fra {town} og forsvinder igen, men råber en advarsel: Gå ikke gennem {place}.`,`{npc3} does not trust people from {town} and slips away again, but shouts a warning: do not go through {place}.`)),u(`Dexterity (Sleight of Hand)`,`medium`,l(`Mens {villain} hjælper {npc2} op på vognen, får heltene et kig under presenningen og ned i tasken uden at blive set.`,`While {villain} helps {npc2} up onto the wagon, the heroes get a look under the tarpaulin and into the satchel without being seen.`),l(`{villain} ser dem ved presenningen, ler og siger, at salt skal holdes tørt; købmanden er venlig som før, men holder nu øje med heltene.`,`{villain} sees them at the tarpaulin, laughs and says salt must be kept dry; the merchant is as friendly as before, but now keeps an eye on the heroes.`))],fight:!1,alternatives:[l(`Tag den gamle vej uden om {place}, som høvdingens skitse siger: Den er længere, men bagholdet venter forgæves, og {villain} må finde på noget andet.`,`Take the old road around {place}, as the chief’s sketch says: it is longer, but the ambush waits in vain, and {villain} must think of something else.`),l(`Lad {npc2} gå eller ride sammen med heltene i stedet for på vognen: {villain} insisterer høfligt, og jo mere {villain} insisterer, jo tydeligere bliver det.`,`Keep {npc2} walking or riding with the heroes instead of on the wagon: {villain} insists politely, and the more {villain} insists, the more suspicious it looks.`)],dmNotes:l(`Vejkorset er eventyrets valg. Lad spillerne høre både {villain}s gode grunde og spejderens advarsel, og lad dem selv beslutte, hvem de tror på.`,`The crossroads is the choice of the adventure. Let the players hear both {villain}’s good reasons and the scout’s warning, and let them decide for themselves whom to believe.`)},{kind:`exploration`,at:`town`,present:[`npc2`,`villain`],title:l(`Vognen i vadestedet`,`The Wagon in the Ford`),summary:l([`Ved det sidste vadested før {place} synker købmandens tunge vogn i til akslerne, og lasten må af, før den kan komme fri.`,`Glider presenningen af, ligger der ikke klæde og salt, men bundter af nye spyd med byens stempel, og {villain} har straks en god forklaring.`,`Scenen koster tid og tvinger {villain} til at vælge mellem vognen og {npc2}, og det valg siger meget.`],[`At the last ford before {place} the merchant’s heavy wagon sinks to its axles, and the load must come off before it can get free.`,`If the tarpaulin slips off, there is no cloth or salt underneath, only bundles of new spears stamped with the town’s mark, and {villain} has a good explanation ready at once.`,`The scene costs time and forces {villain} to choose between the wagon and {npc2}, and that choice says a lot.`]),readAloud:l([`Vandet er brunt og strømmer hurtigt, og vognen står skævt midt i vadestedet med hjulene begravet i mudder.`,`Hestene stamper og pruster, og under den røde presenning skramler noget af metal, hver gang vognen rykker.`,`Købmanden smiler stadig, men knoerne er hvide om tøjlerne.`],[`The water is brown and running fast, and the wagon stands askew in the middle of the ford, its wheels buried in mud.`,`The horses stamp and snort, and under the red tarpaulin something metal rattles each time the wagon jerks.`,`The merchant is still smiling, but their knuckles are white on the reins.`]),details:[l(`Vognen kommer kun fri, hvis lasten bliver båret i land, og det tager en time med alle hænder. {villain} siger, at spydene skal til byens rustkammer, og at snakken om klæde og salt var for at holde røvere væk, men regnskabsbogen i vognens kasse viser, at byen først betaler, den dag krigen bliver erklæret.`,`The wagon only comes free if the load is carried ashore, which takes an hour with every pair of hands. {villain} says the spears are bound for the town armoury and the talk of cloth and salt was to keep robbers away, but the account book in the wagon’s box shows the town pays only on the day war is declared.`),l(`Foreslår heltene at lade vognen stå, vælger {villain} uden at blinke at følge {npc2} og lade lasten blive; en købmand, der efterlader en formue i spyd for at følge en tolk, har en anden forretning end spyd.`,`If the heroes suggest leaving the wagon, {villain} chooses without blinking to follow {npc2} and leave the load behind; a merchant who abandons a fortune in spears to follow an interpreter has business other than spears.`),l(`Mens alle bærer, hænger {villain}s taske uden opsyn på bukken: Brevet med klanernes røde segl ligger øverst, og seglet er skåret i træ.`,`While everyone is carrying, {villain}’s satchel hangs unwatched from the driving seat: the letter with the clans’ red seal lies on top, and the seal is cut in wood.`)],checks:[u(`Strength (Athletics)`,`medium`,l(`Heltene får vognen fri på en halv time uden at bære hele lasten i land.`,`The heroes get the wagon free in half an hour without carrying the whole load ashore.`),l(`Vognen sidder fast, og lasten må af; det koster en hel time, og alle ser, hvad der ligger under presenningen.`,`The wagon is stuck fast and the load must come off; it costs a full hour, and everyone sees what lies under the tarpaulin.`)),u(`Wisdom (Insight)`,`medium`,l(`Forklaringen om rustkammeret er indøvet; {villain} har sagt den før og er mere bange for brevet i tasken end for spydene.`,`The story about the armoury is rehearsed; {villain} has told it before and is more worried about the letter in the satchel than about the spears.`),l(`Forklaringen lyder rimelig, og {npc2} tror på den med det samme.`,`The explanation sounds reasonable, and {npc2} believes it at once.`))],fight:!1,alternatives:[l(`Lad vognen stå i vadestedet, og fortsæt til fods: Følget går hurtigere, og {villain} afslører sig ved at følge med uden sin last.`,`Leave the wagon in the ford and continue on foot: the party moves faster, and {villain} gives the game away by coming along without the load.`),l(`Lad {npc2} læse brevet fra tasken: Tolken ser straks, at vendingerne er forkerte, og at ingen fra klanerne har skrevet det.`,`Let {npc2} read the letter from the satchel: the interpreter sees at once that the phrasing is wrong and that nobody from the clans wrote it.`)],dmNotes:l(`Vadestedet er stedet, hvor masken kan glide. Lad {villain} forklare sig godt, og lad spillerne afgøre, om de vil konfrontere købmanden nu eller vente og se, hvad der sker i {place}.`,`The ford is where the mask can slip. Let {villain} explain well, and let the players decide whether to confront the merchant now or wait and see what happens in {place}.`)},{kind:`investigation`,at:`site`,present:[`npc2`,`villain`],title:l(`Kluden på genvejen`,`The Rag on the Short Cut`),summary:l([`Et stykke inde ad genvejen gennem {place} hænger en rød klud bundet om en sten, i samme farve som {villain}s presenning, og længere fremme er der friske spor af mange fødder.`,`Sporene fører videre mod det sted, hvor genvejen kommer ud, og {villain} bliver mere og mere stille og spejder efter flere klude.`,`Her kan heltene regne ud, at bagholdet venter dér, hvor {villain} vil standse følget, og gøre sig klar.`],[`A little way along the short cut through {place} a red rag hangs knotted round a stone, the same colour as {villain}’s tarpaulin, and further on there are fresh tracks of many feet.`,`The tracks lead on toward the place where the short cut comes out, and {villain} grows quieter and quieter, watching for more rags.`,`Here the heroes can work out that the ambush waits where {villain} means to halt the party, and get ready.`]),readAloud:l([`Genvejen bliver smallere og mørkere, og vejkanterne rejser sig på begge sider.`,`På en sten ved vejkanten sidder en rød klud bundet fast med en dobbelt knude, og jorden omkring den er trådt op af mange fødder.`,`Længere fremme holder en fugl op med at synge, da følget kommer nærmere.`],[`The short cut grows narrower and darker, its banks rising on both sides.`,`On a stone at the roadside a red rag is tied fast with a double knot, and the ground around it is trampled by many feet.`,`Further on a bird stops singing as you come closer.`]),details:[l(`Kluden er et tegn til dem, der venter: Her kommer følget. Den er skåret af samme røde stof som {villain}s presenning, og et hjørne af presenningen mangler.`,`The rag is a sign for those waiting: this is where the party comes through. It is cut from the same red cloth as {villain}’s tarpaulin, and a corner of the tarpaulin is missing.`),l(`Sporene af mange fødder fører mod det sted, hvor genvejen kommer ud ved et vandhul; dér vil {villain} holde an "for at give hestene vand" ved middagstid (andet tik).`,`The tracks of many feet lead toward the place where the short cut comes out by a watering hole; that is where {villain} means to stop "to water the horses" at midday (the second tick).`),l(`Er vognen blevet i vadestedet, prøver {villain} at få {npc2} til at gå forrest sammen med sig; ellers sætter {villain} tolken op på bukken ved sin side. Begge dele bringer købmanden tæt på kappen, når angrebet kommer.`,`If the wagon was left in the ford, {villain} tries to get {npc2} to walk in front, close by; otherwise {villain} seats the interpreter on the driving seat alongside. Either way the merchant is close to the cloak when the attack comes.`)],checks:[u(`Wisdom (Perception)`,`medium`,l(`Heltene ser kluden i tide og bemærker, at {villain} ser den i samme øjeblik og kigger væk.`,`The heroes spot the rag in time and notice that {villain} sees it at the same moment and looks away.`),l(`Heltene opdager først kluden, da de er gået forbi; de ved, at der er noget, men ikke hvad.`,`The heroes only notice the rag once they have passed it; they know something is up, but not what.`)),u(`Wisdom (Survival)`,`easy`,l(`Sporene er fra i morges: en snes fødder, der gik samme vej og ikke kom tilbage. Bagholdet ligger ved vandhullet, hvor genvejen kommer ud.`,`The tracks are from this morning: a score of feet, all going the same way and none coming back. The ambush lies at the watering hole where the short cut comes out.`),l(`Sporene er for mange og for blandede til at læse; heltene ved kun, at mange er gået denne vej i dag.`,`The tracks are too many and too mixed to read; the heroes only know that many have come this way today.`))],fight:!1,alternatives:[l(`Stil {villain} over for kluden og det manglende hjørne af presenningen her og nu, før følget når vandhullet.`,`Confront {villain} with the rag and the missing corner of the tarpaulin here and now, before the party reaches the watering hole.`),l(`Send en helt i forvejen langs vejkanten for at se bagholdet, før det ser følget.`,`Send one hero ahead along the bank to see the ambush before it sees the party.`)],dmNotes:l(`Lad kluden være lille og let at overse, men giv spillerne mere end én chance for at se den. Det er det øjeblik, hvor mistanken mod den venlige købmand bliver til vished.`,`Make the rag small and easy to miss, but give the players more than one chance to see it. It is the moment suspicion of the friendly merchant turns to certainty.`)}],climax:{kind:`climax`,at:`site`,present:[`npc2`,`villain`],title:l(`Vandhullet ved middagstid`,`The Watering Hole at Midday`),summary:l([`Hvor genvejen kommer ud af {place}, standser {villain} ved et vandhul "for at give hestene vand", og i samme øjeblik angriber {boss} og {villain}s lejede {foe} fra begge sider.`,`I forvirringen går {villain} efter {npc2}s kappe for at bytte våbenhvilen ud med det forfalskede brev.`,`Heltene skal beskytte tolken og kappen, afsløre købmanden og stadig nå rådet i {town} før solnedgang.`],[`Where the short cut comes out of {place}, {villain} stops at a watering hole "to water the horses", and at that very moment {boss} and {villain}’s hired {foe} attack from both sides.`,`In the confusion {villain} goes for {npc2}’s cloak to swap the truce for the forged letter.`,`The heroes must protect the interpreter and the cloak, unmask the merchant and still reach the council in {town} before sunset.`]),readAloud:l([`Genvejen munder ud ved et lille vandhul under en skrænt, og købmanden standser og råber, at her er der vand.`,`Et øjeblik er alt stille, så rejser skikkelser sig fra sivene og kommer ned ad skrænten på én gang.`,`Ved siden af heltene rækker en hånd ud efter tolkens kappe.`],[`The short cut comes out at a small watering hole below a bank, and the merchant stops, calling out that there is water here.`,`For a moment all is still; then figures rise out of the reeds and come down the bank all at once.`,`Beside you a hand reaches for the interpreter’s cloak.`]),details:[l(`{boss} og resten af bagholdet er betalt af {villain} og skal skabe forvirring, ikke vinde; de kæmper hårdt, men flygter, når {boss} falder, eller når det står klart, at ingen betaler dem mere.`,`{boss} and the rest of the ambush are paid by {villain} to cause confusion, not to win; they fight hard, but flee when {boss} falls or when it is clear that nobody will pay them any more.`),l(`{villain} kæmper ikke, men holder sig tæt til {npc2} og prøver at sprætte kappen op og bytte dokumentet; lykkes det, sværger {villain}, at det falske brev er det, klanerne sendte. Læser {npc2} brevet, ser tolken straks, at vendingerne er forkerte, for {villain} kan ikke klanernes sprog.`,`{villain} does not fight, but stays close to {npc2} and tries to slit the cloak open and swap the document; if that works, {villain} swears the forged letter is what the clans sent. If {npc2} reads the letter, the interpreter sees at once that the phrasing is wrong, for {villain} does not speak the clans’ tongue.`),l(`Er {villain} allerede afsløret, angriber bagholdet alligevel, og {villain} prøver at slippe fri i forvirringen. Tog heltene den gamle vej uden om {place}, kommer bagholdet efter dem, hvor vejen går tættest forbi {place}. Det er middag, og der er seks timer til solnedgang og rådets afstemning.`,`If {villain} is already unmasked, the ambush attacks anyway, and {villain} tries to slip free in the confusion. If the heroes took the old road around {place}, the ambush comes after them where the road passes closest to {place}. It is midday, with six hours left until sunset and the council’s vote.`)],checks:[u(`Dexterity (Acrobatics)`,`medium`,l(`En helt kaster sig ind mellem {villain} og tolken, før kniven når kappen; våbenhvilen er i sikkerhed.`,`A hero dives between {villain} and the interpreter before the knife reaches the cloak; the truce is safe.`),l(`{villain} når at sprætte kappen op og bytte dokumentet; heltene må finde den rigtige våbenhvile i {villain}s taske, før det er for sent.`,`{villain} manages to slit the cloak and swap the document; the heroes must find the real truce in {villain}’s satchel before it is too late.`)),u(`Charisma (Persuasion)`,`medium`,l(`Heltene lægger beviserne frem for {npc2}: spydene, det falske segl og regnskabsbogen. {villain} ser, at spillet er tabt, og beder om at blive ført levende til rådet frem for at blive efterladt hos bagholdet.`,`The heroes lay the evidence before {npc2}: the spears, the false seal and the account book. {villain} sees the game is lost and begs to be taken to the council alive rather than left with the ambush.`),l(`{villain} griber det falske brev og flygter mod {town} for at nå rådet først med sin egen udgave af sagen.`,`{villain} grabs the forged letter and flees toward {town} to reach the council first with another version of events.`))],fight:!0,alternatives:[l(`Lad byttet ske: Har heltene allerede flyttet den rigtige våbenhvile, får {villain} kun en tom kappe, og det falske brev bliver beviset på forræderiet.`,`Let the swap happen: if the heroes have already moved the real truce, {villain} gets only an empty cloak, and the forged letter becomes the proof of the betrayal.`),l(`Kald på {npc3}: Har spejderen fulgt følget på afstand, falder klanspejderen bagholdet i ryggen og råber {villain}s navn til begge sider.`,`Call on {npc3}: if the scout has followed the party at a distance, the clan scout falls on the ambush from behind and shouts {villain}’s name to both sides.`)],dmNotes:l(`Kampen handler om en kappe, ikke om at vinde: Beskriv det, hver gang {villain}s hånd kommer tæt på den. Afsløringen er stærkest, når den kommer fra {npc2}s egen mund.`,`The fight is about a cloak, not about winning: describe every time {villain}’s hand comes close to it. The unmasking is strongest when it comes from {npc2}’s own mouth.`)}}},f={...r,...s,...d};export{f as KERNEL_SCENES};